// app/api/auth/me/route.ts
import { NextResponse } from "next/server";
import { obterUsuarioLogado } from "@/lib/authSistema";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function GET() {
  try {
    const usuario = await obterUsuarioLogado();

    if (!usuario) {
      return NextResponse.json(
        {
          autenticado: false,
          usuario: null,
        },
        {
          headers: {
            "Cache-Control": "no-store",
          },
        }
      );
    }

    return NextResponse.json(
      {
        autenticado: true,
        usuario,
      },
      {
        headers: {
          "Cache-Control": "no-store",
        },
      }
    );
  } catch (error) {
    console.error("Erro ao buscar usuário logado:", error);

    return NextResponse.json(
      { message: "Erro ao buscar usuário logado." },
      {
        status: 500,
        headers: {
          "Cache-Control": "no-store",
        },
      }
    );
  }
}

// app/api/auth/minha-conta/route.ts
import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { obterUsuarioLogado } from "@/lib/authSistema";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

function texto(valor: unknown) {
  return String(valor || "").trim();
}

function email(valor: unknown) {
  const limpo = String(valor || "").trim().toLowerCase();
  return limpo || null;
}

function username(valor: unknown) {
  return String(valor || "").trim().toLowerCase();
}

function emailValido(valor: string | null) {
  if (!valor) return true;
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(valor);
}

function usernameValido(valor: string) {
  return /^[a-z0-9._-]{3,30}$/.test(valor);
}

function respostaJson(message: string, status: number) {
  return NextResponse.json(
    {
      message,
    },
    {
      status,
      headers: {
        "Cache-Control": "no-store",
      },
    }
  );
}

export async function PATCH(request: Request) {
  try {
    const usuarioLogado = await obterUsuarioLogado();

    if (!usuarioLogado) {
      return respostaJson("Usuário não autenticado.", 401);
    }

    const body = (await request.json().catch(() => null)) as Record<
      string,
      unknown
    > | null;

    if (!body || typeof body !== "object") {
      return respostaJson("Dados inválidos para atualizar a conta.", 400);
    }

    const name = texto(body.name);
    const login = username(body.username);
    const userEmail = email(body.email);

    if (!name || name.length > 120) {
      return respostaJson("Informe o nome do usuário.", 400);
    }

    if (!login) {
      return respostaJson("Informe o login do usuário.", 400);
    }

    if (!usernameValido(login)) {
      return respostaJson(
        "O login deve ter 3 a 30 caracteres e usar apenas letras, números, ponto, traço ou underline.",
        400
      );
    }

    if (userEmail && userEmail.length > 160) {
      return respostaJson("O e-mail deve ter no máximo 160 caracteres.", 400);
    }

    if (!emailValido(userEmail)) {
      return respostaJson("Informe um e-mail válido.", 400);
    }

    const usuarioDuplicado = await prisma.systemUser.findFirst({
      where: {
        id: {
          not: usuarioLogado.id,
        },
        OR: [
          {
            username: login,
          },
          ...(userEmail
            ? [
                {
                  email: userEmail,
                },
              ]
            : []),
        ],
      },
      select: {
        id: true,
        username: true,
        email: true,
      },
    });

    if (usuarioDuplicado?.username === login) {
      return respostaJson("Já existe outro usuário com esse login.", 400);
    }

    if (userEmail && usuarioDuplicado?.email === userEmail) {
      return respostaJson("Já existe outro usuário com esse e-mail.", 400);
    }

    const usuario = await prisma.systemUser.update({
      where: {
        id: usuarioLogado.id,
      },
      data: {
        name,
        username: login,
        email: userEmail,
      },
      select: {
        id: true,
        name: true,
        username: true,
        email: true,
        role: true,
        status: true,
        lastLoginAt: true,
        createdAt: true,
      },
    });

    return NextResponse.json(
      {
        message: "Conta atualizada com sucesso.",
        usuario,
      },
      {
        headers: {
          "Cache-Control": "no-store",
        },
      }
    );
  } catch (error) {
    console.error("Erro ao atualizar minha conta:", error);

    return respostaJson("Erro ao atualizar minha conta.", 500);
  }
}

// app/api/auth/setup/route.ts
import crypto from "node:crypto";
import { NextResponse } from "next/server";
import { SystemUserRole, SystemUserStatus } from "@prisma/client";
import { prisma } from "@/lib/prisma";
import { criarHashSenha, definirSessaoUsuario } from "@/lib/authSistema";
import { TODAS_PERMISSOES } from "@/lib/permissoesSistema";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const BOOTSTRAP_HEADER = "x-nio-os-bootstrap";
const BOOTSTRAP_CONTEXT = "nio-os-first-admin-v1";

let criandoPrimeiroAdmin = false;

function bootstrapEsperado() {
  const secret = String(process.env.AUTH_SECRET || "").trim();

  if (secret.length < 32) return "";

  return crypto
    .createHmac("sha256", secret)
    .update(BOOTSTRAP_CONTEXT)
    .digest("hex");
}

function bootstrapDesktopValido(request: Request) {
  if (process.env.NODE_ENV !== "production") return true;

  const esperado = bootstrapEsperado();
  const recebido = String(request.headers.get(BOOTSTRAP_HEADER) || "")
    .trim()
    .toLowerCase();

  if (
    !esperado ||
    !/^[a-f0-9]{64}$/.test(recebido) ||
    esperado.length !== recebido.length
  ) {
    return false;
  }

  return crypto.timingSafeEqual(
    Buffer.from(esperado, "utf8"),
    Buffer.from(recebido, "utf8")
  );
}

function texto(valor: unknown) {
  return String(valor || "").trim();
}

function login(valor: unknown) {
  return texto(valor).toLowerCase();
}

function email(valor: unknown) {
  const limpo = texto(valor).toLowerCase();
  return limpo || null;
}

function loginValido(valor: string) {
  return /^[a-z0-9._-]{3,30}$/.test(valor);
}

function emailValido(valor: string | null) {
  if (!valor) return true;
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(valor);
}

function respostaJson(message: string, status: number, extra?: object) {
  return NextResponse.json(
    {
      message,
      ...(extra || {}),
    },
    {
      status,
      headers: {
        "Cache-Control": "no-store",
      },
    }
  );
}

export async function GET() {
  try {
    const totalUsuarios = await prisma.systemUser.count();

    return NextResponse.json(
      {
        precisaCriarAdmin: totalUsuarios === 0,
      },
      {
        headers: {
          "Cache-Control": "no-store",
        },
      }
    );
  } catch (error) {
    console.error("Erro ao verificar setup:", error);

    return respostaJson("Erro ao verificar primeiro acesso.", 500);
  }
}

export async function POST(request: Request) {
  if (!bootstrapDesktopValido(request)) {
    return respostaJson(
      "O primeiro administrador deve ser criado no computador servidor.",
      403
    );
  }

  if (criandoPrimeiroAdmin) {
    return respostaJson(
      "A criação do primeiro administrador já está em andamento.",
      409
    );
  }

  criandoPrimeiroAdmin = true;

  try {
    const totalUsuarios = await prisma.systemUser.count();

    if (totalUsuarios > 0) {
      return respostaJson("O primeiro administrador já foi criado.", 409);
    }

    const body = (await request.json().catch(() => null)) as Record<
      string,
      unknown
    > | null;

    if (!body || typeof body !== "object") {
      return respostaJson("Dados inválidos para criar administrador.", 400);
    }

    const name = texto(body.name);
    const username = login(body.username);
    const userEmail = email(body.email);
    const password = texto(body.password);

    if (!name || name.length > 120) {
      return respostaJson("Informe o nome do administrador.", 400);
    }

    if (!loginValido(username)) {
      return respostaJson(
        "O usuário precisa ter 3 a 30 caracteres e usar apenas letras, números, ponto, traço ou underline.",
        400
      );
    }

    if (!emailValido(userEmail)) {
      return respostaJson("Informe um e-mail válido.", 400);
    }

    if (!password || password.length < 6 || password.length > 200) {
      return respostaJson(
        "A senha precisa ter entre 6 e 200 caracteres.",
        400
      );
    }

    if ((await prisma.systemUser.count()) > 0) {
      return respostaJson("O primeiro administrador já foi criado.", 409);
    }

    const usuario = await prisma.systemUser.create({
      data: {
        name,
        username,
        email: userEmail,
        passwordHash: criarHashSenha(password),
        role: SystemUserRole.ADMIN,
        status: SystemUserStatus.ATIVO,
        lastLoginAt: new Date(),
        permissions: {
          create: TODAS_PERMISSOES.map((key) => ({
            key,
          })),
        },
      },
      select: {
        id: true,
        name: true,
        username: true,
        email: true,
        role: true,
        status: true,
      },
    });

    await definirSessaoUsuario(usuario.id);

    return NextResponse.json(
      {
        message: "Administrador criado com sucesso.",
        usuario,
      },
      {
        headers: {
          "Cache-Control": "no-store",
        },
      }
    );
  } catch (error) {
    console.error("Erro ao criar primeiro admin:", {
      name: error instanceof Error ? error.name : "Erro",
    });

    return respostaJson("Erro ao criar primeiro administrador.", 500);
  } finally {
    criandoPrimeiroAdmin = false;
  }
}

// app/api/auth/trocar-senha/route.ts
import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import {
  criarHashSenha,
  obterUsuarioLogado,
  verificarSenha,
} from "@/lib/authSistema";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

function texto(valor: unknown) {
  return String(valor || "").trim();
}

function respostaJson(message: string, status: number) {
  return NextResponse.json(
    {
      message,
    },
    {
      status,
      headers: {
        "Cache-Control": "no-store",
      },
    }
  );
}

export async function PATCH(request: Request) {
  try {
    const usuarioLogado = await obterUsuarioLogado();

    if (!usuarioLogado) {
      return respostaJson("Usuário não autenticado.", 401);
    }

    const body = (await request.json().catch(() => null)) as Record<
      string,
      unknown
    > | null;

    if (!body || typeof body !== "object") {
      return respostaJson("Dados inválidos para trocar senha.", 400);
    }

    const senhaAtual = texto(body.senhaAtual);
    const novaSenha = texto(body.novaSenha);
    const confirmarSenha = texto(body.confirmarSenha);

    if (!senhaAtual || !novaSenha || !confirmarSenha) {
      return respostaJson("Preencha todos os campos de senha.", 400);
    }

    if (
      senhaAtual.length > 200 ||
      novaSenha.length > 200 ||
      confirmarSenha.length > 200
    ) {
      return respostaJson("A senha deve ter no máximo 200 caracteres.", 400);
    }

    if (novaSenha.length < 6) {
      return respostaJson("A nova senha precisa ter pelo menos 6 caracteres.", 400);
    }

    if (novaSenha !== confirmarSenha) {
      return respostaJson("A confirmação da senha não confere.", 400);
    }

    if (senhaAtual === novaSenha) {
      return respostaJson(
        "A nova senha precisa ser diferente da senha atual.",
        400
      );
    }

    const usuario = await prisma.systemUser.findUnique({
      where: {
        id: usuarioLogado.id,
      },
      select: {
        id: true,
        passwordHash: true,
      },
    });

    if (!usuario) {
      return respostaJson("Usuário não encontrado.", 404);
    }

    const senhaCorreta = verificarSenha(senhaAtual, usuario.passwordHash);

    if (!senhaCorreta) {
      return respostaJson("Senha atual incorreta.", 400);
    }

    await prisma.systemUser.update({
      where: {
        id: usuario.id,
      },
      data: {
        passwordHash: criarHashSenha(novaSenha),
      },
      select: {
        id: true,
      },
    });

    return NextResponse.json(
      {
        message: "Senha alterada com sucesso.",
      },
      {
        headers: {
          "Cache-Control": "no-store",
        },
      }
    );
  } catch (error) {
    console.error("Erro ao trocar senha:", error);

    return respostaJson("Erro ao trocar senha.", 500);
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import {
  exigirPermissaoApi,
  usuarioTemPermissao,
} from "@/lib/permissaoApi";
import {
  clienteSelect,
  ordemClienteSelect,
  prepararDadosCliente,
  verificarDuplicidadeCliente,
} from "@/lib/server/clientesCore";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{
    id: string;
  }>;
};

type UsuarioPermissao = {
  id: string;
  name: string;
  username: string;
  role: string;
  status: string;
  permissions?: string[];
};

function podeVerOrdensDoCliente(usuario: UsuarioPermissao) {
  return usuarioTemPermissao(usuario, "ordens.ver");
}

function podeVerFinanceiro(usuario: UsuarioPermissao) {
  return usuarioTemPermissao(usuario, [
    "pagamentos.ver",
    "pagamentos.registrar",
    "relatorios.financeiro",
  ]);
}

export async function GET(_request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi([
      "clientes.ver",
      "ordens.criar",
      "ordens.editar",
      "ordens.ver",
    ]);

    if (!acesso.ok) {
      return acesso.response;
    }

    const { id } = await context.params;

    const cliente = await prisma.customer.findUnique({
      where: {
        id,
      },
      select: clienteSelect,
    });

    if (!cliente) {
      return NextResponse.json(
        { message: "Cliente não encontrado." },
        { status: 404 }
      );
    }

    const usuarioPodeVerOrdens = podeVerOrdensDoCliente(acesso.usuario);
    const usuarioPodeVerFinanceiro = podeVerFinanceiro(acesso.usuario);

    const orders = usuarioPodeVerOrdens
      ? await prisma.serviceOrder.findMany({
          where: {
            customerId: id,
          },
          orderBy: {
            openedAt: "desc",
          },
          select: ordemClienteSelect,
        })
      : [];

    return NextResponse.json({
      ...cliente,
      orders: orders.map((ordem) => ({
        ...ordem,
        totalAmount: usuarioPodeVerFinanceiro ? ordem.totalAmount : null,
      })),
    });
  } catch (error) {
    console.error("Erro ao buscar cliente:", error);

    return NextResponse.json(
      { message: "Erro ao buscar cliente." },
      { status: 500 }
    );
  }
}

export async function PUT(request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("clientes.editar");

    if (!acesso.ok) {
      return acesso.response;
    }

    const { id } = await context.params;

    const clienteExistente = await prisma.customer.findUnique({
      where: {
        id,
      },
      select: {
        id: true,
      },
    });

    if (!clienteExistente) {
      return NextResponse.json(
        { message: "Cliente não encontrado." },
        { status: 404 }
      );
    }

    const body = await request.json().catch(() => null);
    const preparado = prepararDadosCliente(body);

    if (!preparado.ok) {
      return NextResponse.json(
        { message: preparado.message },
        { status: preparado.status }
      );
    }

    const dados = preparado.data;

    const erroDuplicidade = await verificarDuplicidadeCliente({
      cpf: dados.cpf,
      whatsapp: dados.whatsapp,
      email: dados.email,
      ignorarClienteId: id,
    });

    if (erroDuplicidade) {
      return NextResponse.json({ message: erroDuplicidade }, { status: 400 });
    }

    const cliente = await prisma.customer.update({
      where: {
        id,
      },
      data: dados,
      select: clienteSelect,
    });

    return NextResponse.json(cliente);
  } catch (error) {
    console.error("Erro ao editar cliente:", error);

    return NextResponse.json(
      { message: "Erro ao editar cliente." },
      { status: 500 }
    );
  }
}

export async function DELETE(_request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("clientes.excluir");

    if (!acesso.ok) {
      return acesso.response;
    }

    const { id } = await context.params;

    const cliente = await prisma.customer.findUnique({
      where: {
        id,
      },
      include: {
        _count: {
          select: {
            orders: true,
          },
        },
      },
    });

    if (!cliente) {
      return NextResponse.json(
        { message: "Cliente não encontrado." },
        { status: 404 }
      );
    }

    const totalOrdens = cliente._count.orders;

    if (totalOrdens > 0) {
      return NextResponse.json(
        {
          message: `Este cliente possui ${totalOrdens} OS vinculada(s). Por segurança, ele não pode ser excluído.`,
        },
        { status: 400 }
      );
    }

    await prisma.customer.delete({
      where: {
        id,
      },
    });

    return NextResponse.json({
