export async function GET() {
  try {
    const acesso = await exigirPermissaoApi([
      "clientes.ver",
      "ordens.criar",
      "ordens.editar",
    ]);

    if (!acesso.ok) {
      return acesso.response;
    }

    const clientes = await prisma.customer.findMany({
      orderBy: {
        createdAt: "desc",
      },
      select: clienteSelect,
    });

    return NextResponse.json(clientes);
