    console.error("Erro ao cadastrar cliente:", error);

    return NextResponse.json(
      { message: "Erro ao cadastrar cliente." },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { mkdir, writeFile } from "fs/promises";
import path from "path";
import { prisma } from "@/lib/prisma";
import { caminhoPublicoRuntime, caminhoUploadPublico } from "@/lib/runtimeStorage";
import { exigirPermissaoApi } from "@/lib/permissaoApi";
import { textoGarantiaPadrao } from "@/lib/configuracoesPadrao";
export const runtime = "nodejs";
export const dynamic = "force-dynamic";

function ehPng(buffer: Buffer) {
  const assinaturaPng = Buffer.from([
    0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a,
  ]);

  return buffer.length >= 8 && buffer.subarray(0, 8).equals(assinaturaPng);
}

async function obterOuCriarConfiguracoes() {
  const existente = await prisma.companySettings.findFirst();

  if (existente) return existente;

  return prisma.companySettings.create({
    data: {
      companyName: "Minha Empresa",
      primaryColor: "#2563EB",
      defaultWarrantyDays: 90,
      warrantyText: textoGarantiaPadrao,
      footerText:
        "Documento gerado automaticamente pelo sistema de Ordem de Serviço.",
      defaultOperator: "Sistema",
      productsModuleEnabled: true,
    },
  });
}

export async function POST(request: Request) {
  try {
    const acesso = await exigirPermissaoApi("configuracoes.editar");

    if (!acesso.ok) {
      return acesso.response;
    }

    const formData = await request.formData().catch(() => null);
    const file = formData?.get("logo");

    if (!(file instanceof File)) {
      return NextResponse.json(
        { message: "Nenhum arquivo enviado." },
        { status: 400 }
      );
    }

    if (file.type !== "image/png") {
      return NextResponse.json(
        { message: "Envie uma imagem no formato PNG." },
        { status: 400 }
      );
    }

    const maxSize = 2 * 1024 * 1024;

    if (file.size > maxSize) {
      return NextResponse.json(
        { message: "A logo deve ter no máximo 2MB." },
        { status: 400 }
      );
    }

    const bytes = await file.arrayBuffer();
    const buffer = Buffer.from(bytes);

    if (!ehPng(buffer)) {
      return NextResponse.json(
        { message: "O arquivo enviado não parece ser uma imagem PNG válida." },
        { status: 400 }
      );
    }

    const uploadDir = caminhoUploadPublico();
    const filePath = path.join(uploadDir, "logo.png");

    await mkdir(uploadDir, { recursive: true });
    await writeFile(filePath, buffer);

    const configuracoes = await obterOuCriarConfiguracoes();

    await prisma.companySettings.update({
      where: {
        id: configuracoes.id,
      },
      data: {
        logoUrl: "/uploads/logo.png",
      },
    });

    return NextResponse.json({
      message: "Logo atualizada com sucesso.",
      logoUrl: `/uploads/logo.png?v=${Date.now()}`,
    });
  } catch (error) {
    console.error("Erro ao atualizar logo:", error);

    return NextResponse.json(
      { message: "Erro ao atualizar logo." },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { type CompanySettings } from "@prisma/client";
import { prisma } from "@/lib/prisma";
import { exigirPermissaoApi } from "@/lib/permissaoApi";
import { textoGarantiaPadrao } from "@/lib/configuracoesPadrao";
import {
  normalizarDiasFuncionamento,
  normalizarHora,
  serializarDiasFuncionamento,
} from "@/lib/funcionamentoLoja";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

function texto(valor: unknown) {
  return String(valor || "").trim();
}

function textoOuNulo(valor: unknown) {
  const valorLimpo = texto(valor);
  return valorLimpo || null;
}

function numeroGarantia(valor: unknown, fallback: number) {
  if (valor === undefined || valor === null || valor === "") {
    return fallback;
  }

  const numero = Number(valor);

  if (!Number.isFinite(numero) || numero < 0) {
    return fallback;
  }

  return Math.round(numero);
}

function emailValido(email: string | null) {
  if (!email) return true;
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function moduloProdutosAtivo(valor: unknown, fallback = true) {
  if (valor === undefined || valor === null) return fallback;
  return valor !== false;
}

function respostaConfiguracoes(configuracoes: CompanySettings) {
  return {
    ...configuracoes,

    nomeEmpresa: configuracoes.companyName,
    nomeFantasia: configuracoes.tradeName,

    documento: configuracoes.cnpj,
    endereco: configuracoes.address,
    cep: configuracoes.zipCode,

    telefone: configuracoes.phone,
    site: configuracoes.website,

    cidade: configuracoes.city,
    estado: configuracoes.state,

    rodape: configuracoes.footerText,
    operadorPadrao: configuracoes.defaultOperator || "Sistema",
    productsModuleEnabled: configuracoes.productsModuleEnabled !== false,

    businessDays: normalizarDiasFuncionamento(configuracoes.businessDays),
    workingDays: normalizarDiasFuncionamento(configuracoes.businessDays),
    businessOpenTime: normalizarHora(configuracoes.businessOpenTime, "08:00"),
    openingTime: normalizarHora(configuracoes.businessOpenTime, "08:00"),
    businessCloseTime: normalizarHora(configuracoes.businessCloseTime, "18:00"),
    closingTime: normalizarHora(configuracoes.businessCloseTime, "18:00"),
  };
}

async function obterOuCriarConfiguracoes() {
  const existente = await prisma.companySettings.findFirst();

  if (existente) return existente;

  return prisma.companySettings.create({
    data: {
      companyName: "Minha Empresa",
      primaryColor: "#2563EB",
      defaultWarrantyDays: 90,
      warrantyText: textoGarantiaPadrao,
      footerText:
        "Documento gerado automaticamente pelo sistema de Ordem de Serviço.",
      defaultOperator: "Sistema",
      productsModuleEnabled: true,
      businessDays: "1,2,3,4,5,6",
      businessOpenTime: "08:00",
      businessCloseTime: "18:00",
    },
  });
}

export async function GET() {
  try {
    // Leitura mantida sem bloqueio de permissão porque menu, PDFs e páginas
    // operacionais dependem das configurações públicas da empresa.
    // Alterações continuam protegidas no PUT por configuracoes.editar.
    const configuracoes = await obterOuCriarConfiguracoes();

    return NextResponse.json(respostaConfiguracoes(configuracoes));
  } catch (error) {
    console.error("Erro ao buscar configurações:", error);

    return NextResponse.json(
      { message: "Erro ao buscar configurações." },
      { status: 500 }
    );
  }
}

export async function PUT(request: Request) {
  try {
    const acesso = await exigirPermissaoApi("configuracoes.editar");

    if (!acesso.ok) {
      return acesso.response;
    }

    const body = (await request.json().catch(() => null)) as Record<
      string,
      unknown
    > | null;

    if (!body || typeof body !== "object") {
      return NextResponse.json(
        { message: "Dados inválidos para salvar configurações." },
        { status: 400 }
      );
    }

    const existente = await obterOuCriarConfiguracoes();

    const companyName = texto(body.companyName || body.nomeEmpresa);

    if (!companyName) {
      return NextResponse.json(
        { message: "O nome da empresa é obrigatório." },
        { status: 400 }
      );
    }

    const email = textoOuNulo(body.email);

    if (!emailValido(email)) {
      return NextResponse.json(
        { message: "Informe um e-mail válido." },
        { status: 400 }
      );
    }

    const state = texto(body.state || body.estado).toUpperCase();

    if (state && state.length !== 2) {
      return NextResponse.json(
        { message: "Use apenas a sigla do estado. Exemplo: BA." },
        { status: 400 }
      );
    }

    const defaultWarrantyDays = numeroGarantia(
      body.defaultWarrantyDays,
      existente.defaultWarrantyDays || 90
    );

    const warrantyText =
      body.warrantyText !== undefined
        ? texto(body.warrantyText) || textoGarantiaPadrao
        : existente.warrantyText || textoGarantiaPadrao;

    const businessDays = normalizarDiasFuncionamento(
      body.businessDays ?? body.workingDays ?? existente.businessDays
    );

    if (businessDays.length === 0) {
      return NextResponse.json(
        { message: "Selecione pelo menos um dia de funcionamento." },
        { status: 400 }
      );
    }

    const businessOpenTime = normalizarHora(
      body.businessOpenTime ?? body.openingTime,
      existente.businessOpenTime || "08:00"
    );

    const businessCloseTime = normalizarHora(
      body.businessCloseTime ?? body.closingTime,
      existente.businessCloseTime || "18:00"
    );

    const data = {
      companyName,
      tradeName: textoOuNulo(body.tradeName || body.nomeFantasia),

      cnpj: textoOuNulo(body.cnpj || body.documento),

      address: textoOuNulo(body.address || body.endereco),
      phone: textoOuNulo(body.phone || body.telefone),
      whatsapp: textoOuNulo(body.whatsapp),
      email,
      website: textoOuNulo(body.website || body.site),
      instagram: textoOuNulo(body.instagram),
      facebook: textoOuNulo(body.facebook),

      logoUrl:
        body.logoUrl !== undefined
          ? textoOuNulo(body.logoUrl)
          : existente.logoUrl || null,

      bannerUrl:
        body.bannerUrl !== undefined
          ? textoOuNulo(body.bannerUrl)
          : existente.bannerUrl || null,

      primaryColor:
        texto(body.primaryColor) || existente.primaryColor || "#2563EB",

      footerText: textoOuNulo(body.footerText || body.rodape),
      warrantyText,

      defaultWarrantyDays,

      city: textoOuNulo(body.city || body.cidade),
      state: state || null,
      zipCode: textoOuNulo(body.zipCode || body.cep),

      defaultOperator:
        texto(body.defaultOperator || body.operadorPadrao) ||
        existente.defaultOperator ||
        "Sistema",

      productsModuleEnabled: moduloProdutosAtivo(
        body.productsModuleEnabled,
        existente.productsModuleEnabled !== false
      ),

      businessDays: serializarDiasFuncionamento(businessDays),
      businessOpenTime,
      businessCloseTime,
    };

    const configuracoes = await prisma.companySettings.update({
      where: {
        id: existente.id,
      },
      data,
    });

    return NextResponse.json(respostaConfiguracoes(configuracoes));
  } catch (error) {
    console.error("Erro ao salvar configurações:", error);

    return NextResponse.json(
      { message: "Erro ao salvar configurações." },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { ProductSaleStatus } from "@prisma/client";
import { prisma } from "@/lib/prisma";
import {
  exigirPermissaoApi,
  usuarioPodeVerDadosFinanceirosSensiveis,
  usuarioTemPermissao,
} from "@/lib/permissaoApi";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

function respostaJson(data: unknown, init?: ResponseInit) {
  return NextResponse.json(data, {
    ...init,
    headers: {
      "Cache-Control": "no-store",
      ...(init?.headers || {}),
    },
  });
}

function adicionarDias(data: Date, dias: number) {
  const novaData = new Date(data);
  novaData.setDate(novaData.getDate() + dias);
  return novaData;
}

function inicioDoDia(data: Date) {
  const novaData = new Date(data);
  novaData.setHours(0, 0, 0, 0);
  return novaData;
}

function diferencaDias(dataFinal: Date, dataInicial: Date) {
  const umDia = 1000 * 60 * 60 * 24;

  return Math.ceil(
    (inicioDoDia(dataFinal).getTime() - inicioDoDia(dataInicial).getTime()) /
      umDia
  );
}

function numero(valor: unknown) {
  const n = Number(valor ?? 0);
  return Number.isFinite(n) ? n : 0;
}

function inteiro(valor: unknown) {
  return Math.max(0, Math.floor(numero(valor)));
}

export async function GET() {
  try {
    const acesso = await exigirPermissaoApi("dashboard.ver");

    if (!acesso.ok) {
      return acesso.response;
    }

    const usuario = acesso.usuario;

    const podeVerOrdens = usuarioTemPermissao(usuario, "ordens.ver");
    const podeCriarOrdens = usuarioTemPermissao(usuario, "ordens.criar");
    const podeVerClientes = usuarioTemPermissao(usuario, "clientes.ver");
    const podeVerGarantias = usuarioTemPermissao(usuario, "garantias.ver");
    const financeiroSensivelLiberado =
      usuarioPodeVerDadosFinanceirosSensiveis(usuario);
    const podeVerRelatorios = usuarioTemPermissao(usuario, "relatorios.ver");

    const configuracoes = await prisma.companySettings.findFirst({
      select: {
        productsModuleEnabled: true,
      },
    });

    const productsModuleEnabled =
      configuracoes?.productsModuleEnabled !== false;

    const podeVerProdutos =
      productsModuleEnabled && usuarioTemPermissao(usuario, "produtos.ver");

    const podeVerEstoque =
      productsModuleEnabled && usuarioTemPermissao(usuario, "estoque.ver");

    const podeVerVendasProdutos =
      productsModuleEnabled && usuarioTemPermissao(usuario, "vendas.ver");

    const agora = new Date();

    const inicioMes = new Date(
      agora.getFullYear(),
      agora.getMonth(),
      1,
      0,
      0,
      0,
      0
    );

    const fimMes = new Date(
      agora.getFullYear(),
      agora.getMonth() + 1,
      1,
      0,
      0,
      0,
      0
    );

    const hojeInicio = inicioDoDia(new Date());

    const [
      osRecebidas,
      osAbertas,
      osConcluidas,
      osEmAnalise,
      osEmReparo,
      aguardandoPeca,
      prontas,
      osAtrasadas,
      ultimasOrdens,
      clientes,
      recebidoPagamentosAggregate,
      recebidoAntigoAggregate,
      ordensComGarantia,
      vendasProdutosMes,
      ultimasVendasProdutos,
      produtosEstoqueBaixoLista,
      produtosAtivos,
    ] = await Promise.all([
      podeVerOrdens
        ? prisma.serviceOrder.count({
            where: {
              status: "RECEBIDO",
            },
          })
        : Promise.resolve(null),

      podeVerOrdens
        ? prisma.serviceOrder.count({
            where: {
              status: {
                notIn: ["PRONTO", "ENTREGUE", "CANCELADO"],
              },
            },
          })
        : Promise.resolve(null),

      podeVerOrdens
        ? prisma.serviceOrder.count({
            where: {
              status: "ENTREGUE",
            },
          })
        : Promise.resolve(null),

      podeVerOrdens
        ? prisma.serviceOrder.count({
            where: {
              status: "EM_ANALISE",
            },
          })
        : Promise.resolve(null),

      podeVerOrdens
        ? prisma.serviceOrder.count({
            where: {
              status: "EM_REPARO",
            },
          })
        : Promise.resolve(null),

      podeVerOrdens
        ? prisma.serviceOrder.count({
            where: {
              status: "AGUARDANDO_PECA",
            },
          })
        : Promise.resolve(null),

      podeVerOrdens
        ? prisma.serviceOrder.count({
            where: {
              status: "PRONTO",
            },
          })
        : Promise.resolve(null),

      podeVerOrdens
        ? prisma.serviceOrder.count({
            where: {
              expectedDeliveryDate: {
                lt: hojeInicio,
              },
              status: {
                notIn: ["PRONTO", "ENTREGUE", "CANCELADO"],
              },
            },
          })
        : Promise.resolve(null),

      podeVerOrdens
        ? prisma.serviceOrder.findMany({
            take: 6,
            orderBy: {
              openedAt: "desc",
            },
            select: {
              id: true,
              osNumber: true,
              equipmentType: true,
              equipmentOther: true,
              brand: true,
              model: true,
              status: true,
              openedAt: true,
              totalAmount: true,
              customer: {
                select: {
                  name: true,
                  whatsapp: true,
                },
              },
            },
          })
        : Promise.resolve([]),

      podeVerClientes ? prisma.customer.count() : Promise.resolve(null),

      podeVerOrdens
        ? prisma.serviceOrderPayment.aggregate({
            where: {
              createdAt: {
                gte: inicioMes,
                lt: fimMes,
              },
            },
            _sum: {
              amount: true,
            },
          })
        : Promise.resolve(null),

      podeVerOrdens
        ? prisma.serviceOrder.aggregate({
            where: {
              paymentReceivedAt: {
                gte: inicioMes,
                lt: fimMes,
              },
              paymentPercent: {
                gt: 0,
              },
              payments: {
                none: {},
              },
            },
            _sum: {
              paidAmount: true,
            },
          })
        : Promise.resolve(null),

      podeVerGarantias
        ? prisma.serviceOrder.findMany({
            where: {
              finalization: {
                isNot: null,
              },
            },
            select: {
              finalization: {
                select: {
                  deliveredAt: true,
                  warrantyDays: true,
                },
              },
            },
          })
        : Promise.resolve([]),

      productsModuleEnabled && podeVerVendasProdutos
        ? prisma.productSale.findMany({
            where: {
              status: ProductSaleStatus.CONCLUIDA,
              soldAt: {
                gte: inicioMes,
                lt: fimMes,
              },
            },
            select: {
              id: true,
              items: {
                select: {
                  quantity: true,
                },
              },
              totalAmount: true,
              ...(financeiroSensivelLiberado
                ? {
                    costAmount: true,
                    taxAmount: true,
                    profitAmount: true,
                  }
                : {}),
            },
          })
        : Promise.resolve([]),

      podeVerVendasProdutos
        ? prisma.productSale.findMany({
            take: 6,
            where: {
              status: ProductSaleStatus.CONCLUIDA,
            },
            orderBy: {
              soldAt: "desc",
            },
            select: {
              id: true,
              saleNumber: true,
              soldAt: true,
              customerName: true,
              paymentMethod: true,
              userName: true,
              totalAmount: true,
              customer: {
                select: {
                  name: true,
                  whatsapp: true,
                },
              },
              items: {
                select: {
                  productName: true,
                  quantity: true,
                  totalAmount: true,
                },
              },
            },
          })
        : Promise.resolve([]),

      podeVerEstoque
        ? prisma.product.findMany({
            where: {
              isActive: true,
              stockQuantity: {
                not: null,
              },
              minStock: {
                gt: 0,
              },
            },
            select: {
              id: true,
              name: true,
              sku: true,
              category: true,
              stockQuantity: true,
              minStock: true,
            },
            orderBy: {
              name: "asc",
            },
          })
        : Promise.resolve([]),

      podeVerProdutos
        ? prisma.product.count({
            where: {
              isActive: true,
            },
          })
        : Promise.resolve(null),
    ]);

    const vendasMes = vendasProdutosMes as Array<{
      totalAmount?: unknown;
      costAmount?: unknown;
      taxAmount?: unknown;
      profitAmount?: unknown;
      items?: Array<{
        quantity?: unknown;
      }>;
    }>;

    const totalRecebidoOSMes = podeVerOrdens
      ? numero(recebidoPagamentosAggregate?._sum.amount) +
        numero(recebidoAntigoAggregate?._sum.paidAmount)
      : null;

    const receitaProdutosMes =
      podeVerVendasProdutos && productsModuleEnabled
        ? vendasMes.reduce(
            (total, venda) => total + numero(venda.totalAmount),
            0
          )
        : null;

    const lucroProdutosMes =
      financeiroSensivelLiberado && productsModuleEnabled
        ? vendasMes.reduce(
            (total, venda) => total + numero(venda.profitAmount),
            0
          )
        : null;

    const custoProdutosMes =
      financeiroSensivelLiberado && productsModuleEnabled
        ? vendasMes.reduce(
            (total, venda) => total + numero(venda.costAmount),
            0
          )
        : null;

    const impostoProdutosMes =
      financeiroSensivelLiberado && productsModuleEnabled
        ? vendasMes.reduce(
            (total, venda) => total + numero(venda.taxAmount),
            0
          )
        : null;

    const totalRecebidoMes = podeVerOrdens || podeVerVendasProdutos
      ? numero(totalRecebidoOSMes) +
        (productsModuleEnabled ? numero(receitaProdutosMes) : 0)
      : null;

    const vendasProdutosQuantidade = podeVerVendasProdutos
      ? vendasMes.length
      : null;

    const itensProdutosVendidosMes = podeVerVendasProdutos
      ? vendasMes.reduce((total, venda) => {
          const itens = Array.isArray(venda.items) ? venda.items : [];

          return (
            total +
            itens.reduce(
              (subtotal, item) => subtotal + inteiro(item.quantity),
              0
            )
          );
        }, 0)
      : null;

    const produtosEstoqueBaixo = podeVerEstoque
      ? produtosEstoqueBaixoLista.filter((produto) => {
          if (produto.stockQuantity === null) return false;

          const estoque = produto.stockQuantity;
          const minimo = inteiro(produto.minStock);

          return minimo > 0 && estoque < minimo;
        })
      : [];

    const hoje = new Date();

    const garantiasCalculadas = ordensComGarantia
      .filter((ordem) => ordem.finalization)
      .map((ordem) => {
        const entregueEm = ordem.finalization?.deliveredAt
          ? new Date(ordem.finalization.deliveredAt)
          : null;

        const garantiaDias = Number(ordem.finalization?.warrantyDays || 0);

        const venceEm =
          entregueEm && garantiaDias > 0
            ? adicionarDias(entregueEm, garantiaDias)
            : null;

        const diasRestantes = venceEm ? diferencaDias(venceEm, hoje) : null;

        let statusGarantia = "SEM_GARANTIA";

        if (venceEm && diasRestantes !== null) {
          if (diasRestantes < 0) {
            statusGarantia = "VENCIDA";
          } else if (diasRestantes <= 7) {
            statusGarantia = "VENCENDO";
          } else {
            statusGarantia = "VIGENTE";
          }
        }

        return {
          statusGarantia,
        };
      });

    const garantiasVencendo = podeVerGarantias
      ? garantiasCalculadas.filter((item) => item.statusGarantia === "VENCENDO")
          .length
      : null;

    const garantiasVencidas = podeVerGarantias
      ? garantiasCalculadas.filter((item) => item.statusGarantia === "VENCIDA")
          .length
      : null;

    const ultimasOrdensSeguras = podeVerOrdens
      ? ultimasOrdens.map((ordem) => ({
          ...ordem,
          totalAmount: ordem.totalAmount,
        }))
      : [];

    const ultimasVendasProdutosSeguras = podeVerVendasProdutos
      ? ultimasVendasProdutos.map((venda) => ({
          ...venda,
          totalAmount: "totalAmount" in venda ? venda.totalAmount : null,
          items: venda.items.map((item) => ({
            ...item,
            totalAmount: "totalAmount" in item ? item.totalAmount : null,
          })),
        }))
      : [];

    return respostaJson({
      productsModuleEnabled,

      permissoes: {
        productsModuleEnabled,
        podeVerOrdens,
        podeCriarOrdens,
        podeVerClientes,
        podeVerGarantias,
        podeVerProdutos,
        podeVerEstoque,
        podeVerVendasProdutos,
        podeVerFinanceiro: financeiroSensivelLiberado,
        financeiroSensivelLiberado,
        podeVerRelatorios,
      },

      osRecebidas,
      osAbertas,
      osConcluidas,
      osEntregues: osConcluidas,
      osEmAnalise,
      emAnalise: osEmAnalise,
      osEmReparo,
      emReparo: osEmReparo,
      aguardandoPeca,
      prontas,
      osProntas: prontas,
      osAtrasadas,
      clientes,
      garantiasVencendo,
      garantiasVencidas,

      produtosAtivos,
      produtosEstoqueBaixo: produtosEstoqueBaixo.length,
      produtosEstoqueBaixoLista: produtosEstoqueBaixo.slice(0, 8),

      vendasProdutosQuantidade,
      itensProdutosVendidosMes,

      totalRecebidoOSMes,
      receitaProdutosMes,
      lucroProdutosMes,
      custoProdutosMes,
      impostoProdutosMes,
      totalRecebidoMes,

      recebidoMes: totalRecebidoMes,
      recebidoNoMes: totalRecebidoMes,
      totalRecebidoNoMes: totalRecebidoMes,

      ultimasOrdens: ultimasOrdensSeguras,
      ultimasVendasProdutos: ultimasVendasProdutosSeguras,
    });
  } catch (error) {
    console.error("Erro ao carregar painel inicial:", error);

    return respostaJson(
      {
        message: "Erro ao carregar painel inicial.",
      },
      {
        status: 500,
      }
    );
  }
}

