import { NextResponse } from "next/server";
import { ProductSaleStatus } from "@prisma/client";
import { prisma } from "@/lib/prisma";
import {
  exigirPermissaoApi,
  usuarioPodeVerDadosFinanceirosSensiveis,
} from "@/lib/permissaoApi";
import { moduloProdutosEstaAtivo } from "@/lib/moduloProdutos";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

function numero(valor: unknown) {
  const n = Number(valor ?? 0);
  return Number.isFinite(n) ? n : 0;
}

function texto(valor: unknown) {
  return String(valor || "").trim();
}

function inicioMesAtual() {
  const hoje = new Date();
  return new Date(hoje.getFullYear(), hoje.getMonth(), 1, 0, 0, 0, 0);
}

function fimMesAtual() {
  const hoje = new Date();
  return new Date(hoje.getFullYear(), hoje.getMonth() + 1, 0, 23, 59, 59, 999);
}

function criarDataLocalSegura(data: string) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(data);

  if (!match) return null;

  const ano = Number(match[1]);
  const mes = Number(match[2]);
  const dia = Number(match[3]);
  const d = new Date(ano, mes - 1, dia);

  if (
    d.getFullYear() !== ano ||
    d.getMonth() !== mes - 1 ||
    d.getDate() !== dia
  ) {
    return null;
  }

  return d;
}

function inicioDoDia(data: Date) {
  const d = new Date(data);
  d.setHours(0, 0, 0, 0);
  return d;
}

function fimDoDia(data: Date) {
  const d = new Date(data);
  d.setHours(23, 59, 59, 999);
  return d;
}


function formatarDataInput(data: Date) {
  const ano = data.getFullYear();
  const mes = String(data.getMonth() + 1).padStart(2, "0");
  const dia = String(data.getDate()).padStart(2, "0");

  return `${ano}-${mes}-${dia}`;
}

function nomeFormaPagamento(forma: string) {
  const nomes: Record<string, string> = {
    PIX: "PIX",
    DINHEIRO: "Dinheiro",
    CARTAO: "Cartão",
    PARCELADO: "Parcelado",
    AGUARDANDO_PAGAMENTO: "Aguardando pagamento",
  };

  return nomes[forma] || forma || "-";
}

export async function GET(request: Request) {
  try {
    const acesso = await exigirPermissaoApi([
      "relatorios.ver",
      "relatorios.financeiro",
    ]);

    if (!acesso.ok) {
      return acesso.response;
    }
    const financeiroSensivelLiberado =
      usuarioPodeVerDadosFinanceirosSensiveis(acesso.usuario);

    const productsModuleEnabled = await moduloProdutosEstaAtivo();
    const { searchParams } = new URL(request.url);

    const dataInicioParam = texto(searchParams.get("dataInicio"));
    const dataFimParam = texto(searchParams.get("dataFim"));

    const inicioInformado = dataInicioParam
      ? criarDataLocalSegura(dataInicioParam)
      : null;

    const fimInformado = dataFimParam ? criarDataLocalSegura(dataFimParam) : null;

    if (dataInicioParam && !inicioInformado) {
      return NextResponse.json(
        { message: "Data inicial inválida." },
        { status: 400 }
      );
    }

    if (dataFimParam && !fimInformado) {
      return NextResponse.json(
        { message: "Data final inválida." },
        { status: 400 }
      );
    }

    const inicio = inicioInformado ? inicioDoDia(inicioInformado) : inicioMesAtual();

    const fim = fimInformado ? fimDoDia(fimInformado) : fimMesAtual();

    if (fim < inicio) {
      return NextResponse.json(
        { message: "A data final não pode ser menor que a data inicial." },
        { status: 400 }
      );
    }

    const [pagamentosOS, vendasProdutos] = await Promise.all([
      prisma.serviceOrderPayment.findMany({
        where: {
          createdAt: {
            gte: inicio,
            lte: fim,
          },
        },
        orderBy: {
          createdAt: "desc",
        },
        include: {
          serviceOrder: {
            select: {
              id: true,
              osNumber: true,
              customer: {
                select: {
                  id: true,
                  name: true,
                  whatsapp: true,
                },
              },
            },
          },
        },
      }),

      productsModuleEnabled
        ? prisma.productSale.findMany({
            where: {
              status: ProductSaleStatus.CONCLUIDA,
              soldAt: {
                gte: inicio,
                lte: fim,
              },
            },
            orderBy: {
              soldAt: "desc",
            },
            include: {
              customer: {
                select: {
                  id: true,
                  name: true,
                  whatsapp: true,
                },
              },
              items: {
                select: {
                  quantity: true,
                },
              },
            },
          })
        : Promise.resolve([]),
    ]);

    const recebidoOS = pagamentosOS.reduce(
      (total, pagamento) => total + numero(pagamento.amount),
      0
    );

    const recebidoProdutos = productsModuleEnabled
      ? vendasProdutos.reduce(
          (total, venda) => total + numero(venda.totalAmount),
          0
        )
      : 0;

    const custoProdutos = productsModuleEnabled
      ? vendasProdutos.reduce(
          (total, venda) => total + numero(venda.costAmount),
          0
        )
      : 0;

    const impostoProdutos = productsModuleEnabled
      ? vendasProdutos.reduce(
          (total, venda) => total + numero(venda.taxAmount),
          0
        )
      : 0;

    const lucroProdutos = productsModuleEnabled
      ? vendasProdutos.reduce(
          (total, venda) => total + numero(venda.profitAmount),
          0
        )
      : 0;

    const itensProdutos = productsModuleEnabled
      ? vendasProdutos.reduce((total, venda) => {
          return (
            total +
            venda.items.reduce(
              (subtotal, item) =>
                subtotal + Math.max(0, Number(item.quantity || 0)),
              0
            )
          );
        }, 0)
      : 0;

    const formasMap = new Map<
      string,
      {
        forma: string;
        label: string;
        total: number;
        os: number;
        produtos: number;
        quantidadeOS: number;
        quantidadeProdutos: number;
      }
    >();

    function adicionarForma(
      formaOriginal: string,
      tipo: "os" | "produtos",
      valor: number
    ) {
      const forma = formaOriginal || "NAO_INFORMADO";

      const atual =
        formasMap.get(forma) ||
        {
          forma,
          label: nomeFormaPagamento(forma),
          total: 0,
          os: 0,
          produtos: 0,
          quantidadeOS: 0,
          quantidadeProdutos: 0,
        };

      atual.total += valor;

      if (tipo === "os") {
        atual.os += valor;
        atual.quantidadeOS += 1;
      } else {
        atual.produtos += valor;
        atual.quantidadeProdutos += 1;
      }

      formasMap.set(forma, atual);
    }

    for (const pagamento of pagamentosOS) {
      adicionarForma(
        String(pagamento.paymentMethod || ""),
        "os",
        numero(pagamento.amount)
      );
    }

    if (productsModuleEnabled) {
      for (const venda of vendasProdutos) {
        adicionarForma(
          String(venda.paymentMethod || ""),
          "produtos",
          numero(venda.totalAmount)
        );
      }
    }

    const porFormaPagamento = Array.from(formasMap.values()).sort(
      (a, b) => b.total - a.total
    );

    const movimentosOS = pagamentosOS.map((pagamento) => ({
      id: pagamento.id,
      tipo: "OS" as const,
      data: pagamento.createdAt,
      descricao: `Pagamento OS Nº ${String(
        pagamento.serviceOrder?.osNumber || "-"
      ).padStart(3, "0")}`,
      cliente: pagamento.serviceOrder?.customer?.name || "Cliente não informado",
      forma: String(pagamento.paymentMethod || ""),
      formaLabel: nomeFormaPagamento(String(pagamento.paymentMethod || "")),
      valor: numero(pagamento.amount),
      usuario: pagamento.userName || "Sistema",
    }));

    const movimentosProdutos = productsModuleEnabled
      ? vendasProdutos.map((venda) => ({
          id: venda.id,
          tipo: "PRODUTO" as const,
          data: venda.soldAt,
          descricao: `Venda produto Nº ${String(venda.saleNumber).padStart(
            3,
            "0"
          )}`,
          cliente: venda.customer?.name || venda.customerName || "Consumidor",
          forma: String(venda.paymentMethod || ""),
          formaLabel: nomeFormaPagamento(String(venda.paymentMethod || "")),
          valor: numero(venda.totalAmount),
          usuario: venda.userName || "Sistema",
        }))
      : [];

    const movimentos = [...movimentosOS, ...movimentosProdutos]
      .sort((a, b) => new Date(b.data).getTime() - new Date(a.data).getTime())
      .slice(0, 80);

    const receitaTotal = recebidoOS + recebidoProdutos;
    const quantidadeMovimentos = pagamentosOS.length + vendasProdutos.length;

    return NextResponse.json({
      productsModuleEnabled,
      financeiroSensivelLiberado,
      periodo: {
        dataInicio: formatarDataInput(inicio),
        dataFim: formatarDataInput(fim),
      },
      resumo: {
        receitaTotal,
        recebidoOS,
        recebidoProdutos,

        pagamentosOS: pagamentosOS.length,
        vendasProdutos: productsModuleEnabled ? vendasProdutos.length : 0,
        itensProdutos,

        custoProdutos: financeiroSensivelLiberado ? custoProdutos : null,
        impostoProdutos: financeiroSensivelLiberado ? impostoProdutos : null,
        lucroProdutos: financeiroSensivelLiberado ? lucroProdutos : null,

        ticketMedioGeral:
          quantidadeMovimentos > 0 ? receitaTotal / quantidadeMovimentos : 0,

        participacaoOS:
          receitaTotal > 0 ? (recebidoOS / receitaTotal) * 100 : 0,

        participacaoProdutos:
          productsModuleEnabled && receitaTotal > 0
            ? (recebidoProdutos / receitaTotal) * 100
            : 0,
      },
      porFormaPagamento,
      movimentos,
    });
  } catch (error) {
    console.error("Erro ao gerar financeiro geral:", error);

    return NextResponse.json(
      { message: "Erro ao gerar financeiro geral." },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { exigirPermissaoApi } from "@/lib/permissaoApi";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type FiltroGarantia =
  | "TODAS"
  | "VIGENTE"
  | "VENCENDO"
  | "VENCIDA"
  | "SEM_GARANTIA";

const FILTROS_PERMITIDOS: FiltroGarantia[] = [
  "TODAS",
  "VIGENTE",
  "VENCENDO",
  "VENCIDA",
  "SEM_GARANTIA",
];

function adicionarDias(data: Date, dias: number) {
  const novaData = new Date(data);
  novaData.setDate(novaData.getDate() + dias);
  return novaData;
}

function inicioDoDia(data: Date) {
  const novaData = new Date(data);
  novaData.setHours(0, 0, 0, 0);
  return novaData;
}

function diferencaDias(dataFinal: Date, dataInicial: Date) {
  const umDia = 1000 * 60 * 60 * 24;

  return Math.ceil(
    (inicioDoDia(dataFinal).getTime() - inicioDoDia(dataInicial).getTime()) /
      umDia
  );
}

function normalizarFiltro(valor: string | null): FiltroGarantia {
  const filtro = String(valor || "TODAS").trim().toUpperCase();

  return FILTROS_PERMITIDOS.includes(filtro as FiltroGarantia)
    ? (filtro as FiltroGarantia)
    : "TODAS";
}

function resolverStatusGarantia({
  venceEm,
  diasRestantes,
}: {
  venceEm: Date | null;
  diasRestantes: number | null;
}): Exclude<FiltroGarantia, "TODAS"> {
  if (!venceEm || diasRestantes === null) return "SEM_GARANTIA";
  if (diasRestantes < 0) return "VENCIDA";
  if (diasRestantes <= 7) return "VENCENDO";

  return "VIGENTE";
}

function montarResumo(
  garantias: {
    statusGarantia: Exclude<FiltroGarantia, "TODAS">;
  }[]
) {
  return {
    total: garantias.length,
    vigentes: garantias.filter((item) => item.statusGarantia === "VIGENTE")
      .length,
    vencendo: garantias.filter((item) => item.statusGarantia === "VENCENDO")
      .length,
    vencidas: garantias.filter((item) => item.statusGarantia === "VENCIDA")
      .length,
    semGarantia: garantias.filter(
      (item) => item.statusGarantia === "SEM_GARANTIA"
    ).length,
  };
}

export async function GET(request: Request) {
  try {
    const acesso = await exigirPermissaoApi("garantias.ver");

    if (!acesso.ok) {
      return acesso.response;
    }

    const { searchParams } = new URL(request.url);
    const filtro = normalizarFiltro(searchParams.get("filtro"));

    const ordens = await prisma.serviceOrder.findMany({
      where: {
        finalization: {
          isNot: null,
        },
      },
      select: {
        id: true,
        osNumber: true,
        equipmentType: true,
        equipmentOther: true,
        brand: true,
        model: true,
        status: true,
        openedAt: true,
        customer: {
          select: {
            id: true,
            name: true,
            whatsapp: true,
          },
        },
        finalization: {
          select: {
            deliveredAt: true,
            warrantyDays: true,
          },
        },
      },
      orderBy: {
        openedAt: "desc",
      },
    });

    const hoje = new Date();

    const todasGarantias = ordens.map((ordem) => {
      const entregueEm = ordem.finalization?.deliveredAt
        ? new Date(ordem.finalization.deliveredAt)
        : null;

      const warrantyDays = Number(ordem.finalization?.warrantyDays || 0);

      const venceEm =
        entregueEm && warrantyDays > 0
          ? adicionarDias(entregueEm, warrantyDays)
          : null;

      const diasRestantes = venceEm ? diferencaDias(venceEm, hoje) : null;

      const statusGarantia = resolverStatusGarantia({
        venceEm,
        diasRestantes,
      });

      return {
        id: ordem.id,
        serviceOrderId: ordem.id,
        orderId: ordem.id,
        osNumber: ordem.osNumber,
        numeroOS: ordem.osNumber,

        customer: ordem.customer,
        customerName: ordem.customer?.name || "-",
        customerWhatsapp: ordem.customer?.whatsapp || null,

        equipmentType: ordem.equipmentType,
        equipmentOther: ordem.equipmentOther,
        brand: ordem.brand,
        model: ordem.model,

        orderStatus: ordem.status,

        entregueEm,
        deliveredAt: entregueEm,

        warrantyDays,
        garantiaDias: warrantyDays,

        venceEm,
        warrantyExpiresAt: venceEm,
        expiresAt: venceEm,

        diasRestantes,
        daysRemaining: diasRestantes,

        statusGarantia,
        warrantyStatus: statusGarantia,
      };
    });

    const garantias =
      filtro === "TODAS"
        ? todasGarantias
        : todasGarantias.filter((item) => item.statusGarantia === filtro);

    return NextResponse.json({
