import { createHmac } from "node:crypto";
import { NextResponse } from "next/server";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const PROTOCOL_VERSION = 1;
const IDENTITY_CONTEXT = "nio-os-server-identity-v1";

function serverIdentity() {
  const secret = String(process.env.AUTH_SECRET || "").trim();

  if (secret.length < 32) return "";

  return createHmac("sha256", secret)
    .update(IDENTITY_CONTEXT)
    .digest("hex");
}

export async function GET(request: Request) {
  const identity = serverIdentity();
  const url = new URL(request.url);

  if (!identity) {
    return NextResponse.json(
      {
        ok: false,
        app: "Nio-OS",
        service: "nio-os-local-server",
        mode: "server",
        protocolVersion: PROTOCOL_VERSION,
        code: "SERVER_IDENTITY_UNAVAILABLE",
      },
      {
        status: 503,
        headers: {
          "Cache-Control": "no-store",
        },
      }
    );
  }

  return NextResponse.json(
    {
      ok: true,
      app: "Nio-OS",
      service: "nio-os-local-server",
      mode: "server",
      protocolVersion: PROTOCOL_VERSION,
      identity,
      origin: url.origin,
      timestamp: new Date().toISOString(),
    },
    {
      status: 200,
      headers: {
        "Cache-Control": "no-store",
      },
    }
  );
}

import { NextResponse } from "next/server";
import { OrderStatus, PaymentMethod } from "@prisma/client";
import { prisma } from "@/lib/prisma";
import { exigirAdministradorApi } from "@/lib/permissaoApi";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

function numeroSeguro(valor: unknown) {
  const numero = Number(valor ?? 0);
  return Number.isFinite(numero) ? numero : 0;
}

function pagamentoValido(valor: unknown): PaymentMethod {
  const recebido = String(valor || "").trim();

  if (Object.values(PaymentMethod).includes(recebido as PaymentMethod)) {
    if (recebido !== PaymentMethod.AGUARDANDO_PAGAMENTO) {
      return recebido as PaymentMethod;
    }
  }

  return PaymentMethod.PIX;
}

async function buscarOrdensParaRegularizar() {
  const ordens = await prisma.serviceOrder.findMany({
    where: {
      status: OrderStatus.ENTREGUE,
    },
    include: {
      customer: true,
      finalization: true,
      payments: true,
    },
    orderBy: {
      osNumber: "asc",
    },
  });

  return ordens.filter((ordem) => {
    if (!ordem.finalization) return false;

    const valorFinal = numeroSeguro(
      ordem.finalization.finalAmount || ordem.totalAmount
    );

    const valorPago = numeroSeguro(ordem.paidAmount);
    const percentualPago = numeroSeguro(ordem.paymentPercent);

    if (valorFinal <= 0) return false;

    return percentualPago < 100 || valorPago < valorFinal;
  });
}

export async function GET() {
  try {
    const acesso = await exigirAdministradorApi();

    if (!acesso.ok) {
      return acesso.response;
    }

    const ordens = await buscarOrdensParaRegularizar();

    return NextResponse.json({
      total: ordens.length,
      ordens: ordens.map((ordem) => ({
        id: ordem.id,
        osNumber: ordem.osNumber,
        cliente: ordem.customer?.name || "-",
        valorFinal: numeroSeguro(
          ordem.finalization?.finalAmount || ordem.totalAmount
        ),
        valorPagoAtual: numeroSeguro(ordem.paidAmount),
        percentualAtual: numeroSeguro(ordem.paymentPercent),
        formaPagamento:
          ordem.finalization?.paymentMethod || ordem.paymentMethod || "PIX",
      })),
    });
  } catch (error) {
    console.error("Erro ao buscar OS para regularizar:", error);

    return NextResponse.json(
      { message: "Erro ao buscar OS para regularizar." },
      { status: 500 }
    );
  }
}

export async function POST() {
  try {
    const acesso = await exigirAdministradorApi();

    if (!acesso.ok) {
      return acesso.response;
    }

    const ordens = await buscarOrdensParaRegularizar();

    const resultado = await prisma.$transaction(async (tx) => {
      const regularizadas = [];

      for (const ordem of ordens) {
        const valorFinal = numeroSeguro(
          ordem.finalization?.finalAmount || ordem.totalAmount
        );

        const formaPagamento = pagamentoValido(
          ordem.finalization?.paymentMethod || ordem.paymentMethod
        );

        const ordemAtualizada = await tx.serviceOrder.update({
          where: {
            id: ordem.id,
          },
          data: {
            totalAmount: valorFinal,
            paidAmount: valorFinal,
            paymentPercent: 100,
            paymentReceivedAt: new Date(),
            paymentMethod: formaPagamento,

            payments: {
              create: {
                amount: valorFinal,
                percent: 100,
                paymentMethod: formaPagamento,
                note: "Pagamento regularizado automaticamente para OS antiga já finalizada.",
              },
            },

            histories: {
              create: {
                userName: "Sistema",
                action: "REGULARIZACAO_PAGAMENTO",
                description:
                  "Pagamento de 100% regularizado automaticamente para OS antiga já finalizada.",
              },
            },
          },
        });

        regularizadas.push({
          id: ordemAtualizada.id,
          osNumber: ordemAtualizada.osNumber,
          valor: valorFinal,
          paymentMethod: formaPagamento,
        });
      }

      return regularizadas;
    });

    return NextResponse.json({
      message: "Pagamentos regularizados com sucesso.",
      total: resultado.length,
      regularizadas: resultado,
    });
  } catch (error) {
    console.error("Erro ao regularizar pagamentos:", error);

    return NextResponse.json(
      { message: "Erro ao regularizar pagamentos." },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import fs from "fs/promises";
import path from "path";
import { exigirPermissaoApi } from "@/lib/permissaoApi";
import { caminhoStorageRuntime, caminhoUploadPublico } from "@/lib/runtimeStorage";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{
    id: string;
    anexoId: string;
  }>;
};

function nomeOperador(usuario: {
  name?: string | null;
  username?: string | null;
  email?: string | null;
} | null | undefined) {
  return (
    String(usuario?.name || usuario?.username || usuario?.email || "").trim() ||
    "Sistema"
  );
}

function caminhosPossiveisDoAnexo(url: string | null | undefined) {
  const valor = String(url || "").split("?")[0].trim();
  const nomeArquivo = path.basename(valor);

  if (!nomeArquivo || nomeArquivo === "." || nomeArquivo === "..") {
    return [];
  }

  const caminhos = [
    caminhoStorageRuntime("uploads", "anexos", nomeArquivo),
    caminhoUploadPublico("anexos", nomeArquivo),
  ];

  if (valor.startsWith("/uploads/") || valor.startsWith("uploads/")) {
    caminhos.push(
      caminhoUploadPublico(valor.replace(/^\/+uploads[\\/]+/, ""))
    );
  }

  return Array.from(new Set(caminhos));
}

async function removerArquivoFisico(url: string | null | undefined) {
  const caminhos = caminhosPossiveisDoAnexo(url);

  for (const caminho of caminhos) {
    try {
      await fs.unlink(caminho);
      return;
    } catch {
      // Se o arquivo físico não existir neste caminho, tenta o próximo.
    }
  }
}


export async function DELETE(_request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.anexos");

    if (!acesso.ok) {
      return acesso.response;
    }

    const userName = nomeOperador(acesso.usuario);

    const { id, anexoId } = await context.params;

    const anexo = await prisma.serviceOrderAttachment.findFirst({
      where: {
        id: anexoId,
        serviceOrderId: id,
      },
    });

    if (!anexo) {
      return NextResponse.json(
        { message: "Anexo não encontrado." },
        { status: 404 }
      );
    }

    await removerArquivoFisico(anexo.url);

    await prisma.serviceOrderAttachment.delete({
      where: {
        id: anexo.id,
      },
    });

    await prisma.serviceOrder.update({
      where: { id },
      data: {
        histories: {
          create: {
            userName,
            action: "ANEXO_REMOVIDO",
            description: `Anexo removido: ${anexo.originalName}`,
          },
        },
      },
    });

    return NextResponse.json({
      message: "Anexo removido com sucesso.",
    });
  } catch (error) {
    console.error("Erro ao remover anexo da OS:", error);

    return NextResponse.json(
      { message: "Erro ao remover anexo da OS." },
      { status: 500 }
    );
  }
}

import { randomUUID } from "crypto";
import { mkdir, writeFile } from "fs/promises";
import path from "path";
import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { resolverOperadorPadrao } from "@/lib/operadorSistema";
import { exigirPermissaoApi } from "@/lib/permissaoApi";
import { caminhoStorageRuntime } from "@/lib/runtimeStorage";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{
    id: string;
  }>;
};

type UsuarioSessao = {
  name?: string | null;
  username?: string | null;
  email?: string | null;
};

const TAMANHO_MAXIMO_ANEXO = 10 * 1024 * 1024;

const TIPOS_PERMITIDOS = new Map([
  [".png", "image/png"],
  [".jpg", "image/jpeg"],
  [".jpeg", "image/jpeg"],
  [".webp", "image/webp"],
  [".pdf", "application/pdf"],
]);

function nomeOperador(usuario: unknown) {
  const dadosUsuario = usuario as UsuarioSessao | null;

  return (
    dadosUsuario?.name || dadosUsuario?.username || dadosUsuario?.email || "Sistema"
  );
}

function limparNomeArquivo(nome: string) {
  return nome
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9._-]/g, "-")
    .replace(/-+/g, "-")
    .replace(/^[-.]+|[-.]+$/g, "")
    .toLowerCase();
}

function normalizarExtensao(nomeArquivo: string) {
  return path.extname(nomeArquivo || "").toLowerCase();
}

function urlProtegidaAnexo(fileName: string) {
  return `/api/uploads/anexos/${encodeURIComponent(fileName)}`;
}

function caminhoDiretorioAnexos() {
  return caminhoStorageRuntime("uploads", "anexos");
}

function parecePng(buffer: Buffer) {
  const assinatura = Buffer.from([
    0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a,
  ]);

  return buffer.length >= assinatura.length && buffer.subarray(0, 8).equals(assinatura);
}

function pareceJpeg(buffer: Buffer) {
  return buffer.length >= 3 && buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff;
}

function pareceWebp(buffer: Buffer) {
  return (
    buffer.length >= 12 &&
    buffer.subarray(0, 4).toString("ascii") === "RIFF" &&
    buffer.subarray(8, 12).toString("ascii") === "WEBP"
  );
}

function parecePdf(buffer: Buffer) {
  return buffer.length >= 4 && buffer.subarray(0, 4).toString("ascii") === "%PDF";
}

function arquivoPareceValido(buffer: Buffer, extensao: string) {
  if (extensao === ".png") return parecePng(buffer);
  if (extensao === ".jpg" || extensao === ".jpeg") return pareceJpeg(buffer);
  if (extensao === ".webp") return pareceWebp(buffer);
  if (extensao === ".pdf") return parecePdf(buffer);

  return false;
}

function sanitizarAnexo<T extends { fileName: string; url: string | null }>(anexo: T) {
  return {
    ...anexo,
    url: urlProtegidaAnexo(anexo.fileName),
  };
}

export async function GET(_request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.anexos");

    if (!acesso.ok) {
      return acesso.response;
    }

    const { id } = await context.params;

    if (!id) {
      return NextResponse.json(
        { message: "ID da OS não informado." },
        { status: 400 }
      );
    }

    const ordemExiste = await prisma.serviceOrder.findUnique({
      where: {
        id,
      },
      select: {
        id: true,
      },
    });

    if (!ordemExiste) {
      return NextResponse.json(
        { message: "Ordem não encontrada." },
        { status: 404 }
      );
    }

    const anexos = await prisma.serviceOrderAttachment.findMany({
      where: {
        serviceOrderId: id,
      },
      orderBy: {
        createdAt: "desc",
      },
    });

    return NextResponse.json(anexos.map(sanitizarAnexo));
  } catch (error) {
    console.error("Erro ao buscar anexos da OS:", error);

    return NextResponse.json(
      { message: "Erro ao buscar anexos da OS." },
      { status: 500 }
    );
  }
}

export async function POST(request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.anexos");

    if (!acesso.ok) {
      return acesso.response;
    }

    const { id } = await context.params;

    if (!id) {
      return NextResponse.json(
        { message: "ID da OS não informado." },
        { status: 400 }
      );
    }

    const ordem = await prisma.serviceOrder.findUnique({
      where: { id },
      select: {
        id: true,
        osNumber: true,
      },
    });

    if (!ordem) {
      return NextResponse.json(
        { message: "Ordem não encontrada." },
        { status: 404 }
      );
    }

    const formData = await request.formData().catch(() => null);

    if (!formData) {
      return NextResponse.json(
        { message: "Dados inválidos para envio do anexo." },
        { status: 400 }
      );
    }

    const arquivo =
      formData.get("file") ||
      formData.get("arquivo") ||
      formData.get("anexo") ||
      formData.get("attachment");

    if (!(arquivo instanceof File)) {
      return NextResponse.json(
        { message: "Nenhum arquivo enviado." },
        { status: 400 }
      );
    }

    if (arquivo.size <= 0) {
      return NextResponse.json(
        { message: "O arquivo enviado está vazio." },
        { status: 400 }
      );
    }

    if (arquivo.size > TAMANHO_MAXIMO_ANEXO) {
      return NextResponse.json(
        { message: "O anexo deve ter no máximo 10MB." },
        { status: 400 }
      );
    }

    const originalName = arquivo.name || "arquivo";
    const extensao = normalizarExtensao(originalName);
    const mimePermitido = TIPOS_PERMITIDOS.get(extensao);

    if (!mimePermitido) {
      return NextResponse.json(
        {
          message:
            "Tipo de anexo não permitido. Envie PNG, JPG, WEBP ou PDF.",
        },
        { status: 400 }
      );
    }

    const bytes = await arquivo.arrayBuffer();
    const buffer = Buffer.from(bytes);

    if (!arquivoPareceValido(buffer, extensao)) {
      return NextResponse.json(
        {
          message:
            "O arquivo enviado não parece corresponder ao tipo informado.",
        },
        { status: 400 }
      );
    }

    const uploadDir = caminhoDiretorioAnexos();
    await mkdir(uploadDir, { recursive: true });

    const baseName = limparNomeArquivo(
      path.basename(originalName, extensao) || "anexo"
    );

    const numeroOS = String(ordem.osNumber || "sem-numero").replace(/\D/g, "") || "sem-numero";
    const fileName = `os-${numeroOS}-${Date.now()}-${randomUUID()}-${baseName}${extensao}`;
    const filePath = path.join(uploadDir, fileName);

    await writeFile(filePath, buffer, {
      flag: "wx",
    });

    const url = urlProtegidaAnexo(fileName);
    const userName = await resolverOperadorPadrao(nomeOperador(acesso.usuario));

    const anexo = await prisma.serviceOrderAttachment.create({
      data: {
        serviceOrderId: id,
        fileName,
        originalName,
        url,
        mimeType: mimePermitido,
        size: arquivo.size,
      },
    });

    await prisma.orderHistory.create({
      data: {
        serviceOrderId: id,
        userName,
        action: "ANEXO_ADICIONADO",
        description: `Anexo adicionado à OS: ${originalName}.`,
      },
    });

    return NextResponse.json(sanitizarAnexo(anexo), { status: 201 });
  } catch (error) {
    console.error("Erro ao salvar anexo da OS:", error);

    return NextResponse.json(
      { message: "Erro ao salvar anexo da OS." },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { OrderStatus } from "@prisma/client";
import { prisma } from "@/lib/prisma";
import {
  exigirPermissaoApi,
  usuarioPodeVerDadosFinanceirosSensiveis,
  usuarioTemPermissao,
} from "@/lib/permissaoApi";
import { requireIdempotencyKey } from "@/lib/estoqueTecnico/validation";
import { cancelServiceOrderAndReleaseReservedTechnicalParts } from "@/lib/estoqueTecnico";
import { toFutureHttpError } from "@/lib/estoqueTecnico/errors";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{
    id: string;
  }>;
};

type UsuarioSessao = NonNullable<Parameters<typeof usuarioTemPermissao>[0]>;

const STATUS_CANCELAVEIS = new Set<string>([
  OrderStatus.RECEBIDO,
  OrderStatus.EM_ANALISE,
  OrderStatus.AGUARDANDO_PECA,
  OrderStatus.EM_REPARO,
  OrderStatus.PRONTO,
]);

function nomeOperador(usuario: UsuarioSessao | null | undefined) {
  return usuario?.name?.trim() || usuario?.username?.trim() || "Sistema";
}

function podeVerDadosPagamento(usuario: UsuarioSessao | null | undefined) {
  if (!usuario) return false;

  return usuarioTemPermissao(usuario, [
    "pagamentos.ver",
    "pagamentos.registrar",
    "relatorios.financeiro",
  ]);
}

function ocultarDadosPagamentoDaOrdem(ordem: any, mostrarPagamentos: boolean) {
  if (mostrarPagamentos) return ordem;

  return {
    ...ordem,
    paidAmount: null,
    paymentPercent: null,
    paymentReceivedAt: null,
    paymentMethod: null,
    payments: [],
    finalization: ordem.finalization
      ? {
          ...ordem.finalization,
          finalAmount: null,
          paymentMethod: null,
        }
      : null,
  };
}

function respostaJson(body: unknown, status = 200) {
  return NextResponse.json(body, {
    status,
    headers: { "Cache-Control": "no-store" },
  });
}

function respostaErroEstoque(error: unknown) {
  const mapped = toFutureHttpError(error);
  const headers: Record<string, string> = {
    "Cache-Control": "no-store",
  };

  if (mapped.body.retryable) {
    headers["Retry-After"] = "1";
  }

  return NextResponse.json(mapped.body, {
    status: mapped.status,
    headers,
  });
}

function validarPayloadCancelamento(body: Record<string, unknown>) {
  const permitidos = new Set([
    "motivo",
    "expectedCurrentStatus",
    "confirmation",
  ]);

  if (Object.keys(body).some((key) => !permitidos.has(key))) {
    return "O payload contém campos não permitidos para cancelar a OS.";
  }

  if (typeof body.motivo !== "string") {
    return "Informe o motivo do cancelamento.";
  }

  const motivo = body.motivo.trim();

  if (!motivo) {
    return "Informe o motivo do cancelamento.";
  }

  if (motivo.length < 10) {
    return "Descreva melhor o motivo do cancelamento.";
  }

  if (motivo.length > 1000) {
    return "O motivo do cancelamento deve ter no máximo 1000 caracteres.";
  }

  if (
    typeof body.expectedCurrentStatus !== "string" ||
    !STATUS_CANCELAVEIS.has(body.expectedCurrentStatus)
  ) {
    return "Informe o status atual esperado da OS.";
  }

  if (body.confirmation !== true) {
    return "Confirme o cancelamento da OS.";
  }

  return null;
}

export async function PATCH(request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.cancelar");

    if (!acesso.ok) {
      return acesso.response;
    }

    const contentType = String(
      request.headers.get("content-type") || "",
    ).toLowerCase();

    if (!contentType.startsWith("application/json")) {
      return respostaJson(
        {
          code: "VALIDATION_ERROR",
          message: "Content-Type application/json é obrigatório.",
        },
        422,
      );
    }

    const body = (await request.json().catch(() => null)) as
      | Record<string, unknown>
      | null;

    if (!body || typeof body !== "object" || Array.isArray(body)) {
      return respostaJson(
        {
          code: "VALIDATION_ERROR",
          message: "Dados inválidos para cancelar a OS.",
        },
        422,
      );
    }

    const payloadError = validarPayloadCancelamento(body);

    if (payloadError) {
      return respostaJson(
        {
          code: "VALIDATION_ERROR",
          message: payloadError,
        },
        422,
      );
    }

    let idempotencyKey: string;

    try {
      idempotencyKey = requireIdempotencyKey(
        request.headers.get("Idempotency-Key"),
      );
    } catch (error) {
      const mapped = toFutureHttpError(error);

      return NextResponse.json(mapped.body, {
        status: 422,
        headers: { "Cache-Control": "no-store" },
      });
    }

    const { id } = await context.params;
    const userName = nomeOperador(acesso.usuario);
    const motivo = String(body.motivo).trim();
    const expectedCurrentStatus = String(body.expectedCurrentStatus);

    let result;

    try {
      result = cancelServiceOrderAndReleaseReservedTechnicalParts(
        id,
        {
          expectedCurrentStatus,
          confirmation: true,
          reason: motivo,
        },
        {
          operatorId: acesso.usuario.id || null,
          operatorName: userName,
          canViewFinancialData:
            usuarioPodeVerDadosFinanceirosSensiveis(acesso.usuario),
          idempotencyKey,
        },
      );
    } catch (error) {
      return respostaErroEstoque(error);
    }

    // O commit técnico já ocorreu. Esta leitura serve apenas para preservar
    // o contrato histórico da rota; falha aqui nunca deve ser reportada como rollback.
    try {
      const ordemCompleta = await prisma.serviceOrder.findUnique({
        where: { id },
        include: {
          customer: true,
          histories: { orderBy: { createdAt: "desc" } },
          finalization: true,
          attachments: true,
          payments: { orderBy: { createdAt: "desc" } },
        },
      });

      if (ordemCompleta) {
        return NextResponse.json(
          ocultarDadosPagamentoDaOrdem(
            ordemCompleta,
            podeVerDadosPagamento(acesso.usuario),
          ),
          { headers: { "Cache-Control": "no-store" } },
        );
      }
    } catch {
      // O cancelamento já foi confirmado na transação SQLite.
    }

    return NextResponse.json(
      {
        ...result,
        reloadOrder: true,
      },
      { headers: { "Cache-Control": "no-store" } },
    );
  } catch {
    return respostaJson(
      {
        code: "INTERNAL_ERROR",
        message: "Erro ao cancelar ordem de serviço.",
      },
      500,
    );
  }
}

import { NextResponse } from "next/server";
import { PaymentMethod } from "@prisma/client";
import { prisma } from "@/lib/prisma";
import { gerarProximoNumeroOS } from "@/lib/numeroSequencial";
import {
  exigirPermissaoApi,
  usuarioTemPermissao,
} from "@/lib/permissaoApi";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{
    id: string;
  }>;
};

type UsuarioSessao = NonNullable<Parameters<typeof usuarioTemPermissao>[0]>;

function numeroSeguro(valor: unknown) {
  const numero = Number(valor ?? 0);
  return Number.isFinite(numero) ? numero : 0;
}

function nomeOperador(usuario: UsuarioSessao | null | undefined) {
  return usuario?.name?.trim() || usuario?.username?.trim() || "Sistema";
}

function podeVerDadosPagamento(usuario: UsuarioSessao | null | undefined) {
  if (!usuario) return false;

  return usuarioTemPermissao(usuario, [
    "pagamentos.ver",
    "pagamentos.registrar",
    "relatorios.financeiro",
  ]);
}

function ocultarDadosPagamentoDaOrdem(ordem: any, mostrarPagamentos: boolean) {
  if (mostrarPagamentos) return ordem;

  return {
    ...ordem,
    paidAmount: null,
    paymentPercent: null,
    paymentReceivedAt: null,
    paymentMethod: null,
    payments: [],
    finalization: ordem.finalization
      ? {
          ...ordem.finalization,
          finalAmount: null,
          paymentMethod: null,
        }
      : null,
  };
}

export async function POST(_request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.criar");

    if (!acesso.ok) return acesso.response;

    const { id } = await context.params;
    const userName = nomeOperador(acesso.usuario);
    const usuarioPodeCopiarFormaPagamento = usuarioTemPermissao(acesso.usuario, [
      "pagamentos.registrar",
      "relatorios.financeiro",
    ]);

    const ordemOriginal = await prisma.serviceOrder.findUnique({
      where: { id },
    });

    if (!ordemOriginal) {
      return NextResponse.json(
        { message: "Ordem original não encontrada." },
        { status: 404 }
      );
    }

    const numeroOriginal = String(ordemOriginal.osNumber).padStart(3, "0");

    const novaOrdem = await prisma.serviceOrder.create({
      data: {

        osNumber: await gerarProximoNumeroOS(),customerId: ordemOriginal.customerId,
        equipmentType: ordemOriginal.equipmentType,
        equipmentOther: ordemOriginal.equipmentOther,
        brand: ordemOriginal.brand,
        model: ordemOriginal.model,
        serialNumber: ordemOriginal.serialNumber,
        imei: ordemOriginal.imei,
        devicePassword: ordemOriginal.devicePassword,
        deliveredAccessories: ordemOriginal.deliveredAccessories,
        reportedDefect: ordemOriginal.reportedDefect,
        technicalNotes: ordemOriginal.technicalNotes,
        requiredParts: ordemOriginal.requiredParts,
        partsCost: numeroSeguro(ordemOriginal.partsCost),
        laborCost: numeroSeguro(ordemOriginal.laborCost),
        discount: numeroSeguro(ordemOriginal.discount),
        totalAmount: numeroSeguro(ordemOriginal.totalAmount),
        paymentMethod: usuarioPodeCopiarFormaPagamento
          ? ordemOriginal.paymentMethod
          : PaymentMethod.AGUARDANDO_PAGAMENTO,
        status: "RECEBIDO",
        expectedDeliveryDate: ordemOriginal.expectedDeliveryDate,
        histories: {
          create: {
            userName,
            action: "DUPLICACAO_OS",
            description: `Ordem duplicada a partir da OS Nº ${numeroOriginal}.`,
          },
        },
      },
      include: {
        customer: true,
        histories: { orderBy: { createdAt: "desc" } },
      },
    });

    return NextResponse.json(
      ocultarDadosPagamentoDaOrdem(
        novaOrdem,
        podeVerDadosPagamento(acesso.usuario)
      ),
      { status: 201 }
    );
  } catch (error) {
    console.error("Erro ao duplicar ordem:", error);

    const message =
      error instanceof Error
        ? error.message
        : "Erro ao duplicar ordem de serviço.";

    return NextResponse.json({ message }, { status: 500 });
  }
}

