        .fillColor("#111827")
        .text(cliente, 12, 52, {
          width: 142,
          height: 13,
          ellipsis: true,
        });

      doc
        .fontSize(7)
        .font("Helvetica-Bold")
        .fillColor("#475569")
        .text("STATUS", 164, 43);

      doc
        .roundedRect(164, 52, 58, 15, 4)
        .fillColor("#f1f5f9")
        .fill()
        .strokeColor("#cbd5e1")
        .stroke();

      doc
        .fontSize(7)
        .font("Helvetica-Bold")
        .fillColor("#111827")
        .text(status, 168, 56, {
          width: 50,
          height: 9,
          align: "center",
          ellipsis: true,
        });

      doc
        .fontSize(7)
        .font("Helvetica-Bold")
        .fillColor("#475569")
        .text("WHATSAPP", 12, 70);

      doc
        .fontSize(8)
        .font("Helvetica")
        .fillColor("#111827")
        .text(whatsapp, 12, 79, {
          width: 82,
          height: 10,
          ellipsis: true,
        });

      doc
        .fontSize(7)
        .font("Helvetica-Bold")
        .fillColor("#475569")
        .text("ENTRADA", 100, 70);

      doc
        .fontSize(8)
        .font("Helvetica")
        .fillColor("#111827")
        .text(formatarData(ordem.openedAt), 100, 79, {
          width: 54,
          height: 10,
          ellipsis: true,
        });

      doc
        .fontSize(7)
        .font("Helvetica-Bold")
        .fillColor("#475569")
        .text("PREVISÃO", 164, 70);

      doc
        .fontSize(8)
        .font("Helvetica")
        .fillColor("#111827")
        .text(formatarData(ordem.expectedDeliveryDate), 164, 79, {
          width: 58,
          height: 10,
          ellipsis: true,
        });

      doc
        .fontSize(7)
        .font("Helvetica-Bold")
        .fillColor("#475569")
        .text("EQUIP.", 12, 93);

      doc
        .fontSize(8)
        .font("Helvetica-Bold")
        .fillColor("#111827")
        .text(equipamento, 12, 102, {
          width: 62,
          height: 10,
          ellipsis: true,
        });

      doc
        .fontSize(7)
        .font("Helvetica-Bold")
        .fillColor("#475569")
        .text("MARCA/MODELO", 80, 93);

      doc
        .fontSize(8)
        .font("Helvetica")
        .fillColor("#111827")
        .text(marcaModelo || "-", 80, 102, {
          width: 72,
          height: 10,
          ellipsis: true,
        });

      doc
        .fontSize(7)
        .font("Helvetica-Bold")
        .fillColor("#475569")
        .text("IMEI/SÉRIE", 158, 93);

      doc
        .fontSize(8)
