export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{
    id: string;
  }>;
};

const LIMITE_OBSERVACAO = 3000;

function texto(valor: unknown) {
  return String(valor || "").trim();
}

function nomeOperador(usuario: unknown) {
  const dados = usuario as
    | {
        name?: string | null;
        nome?: string | null;
        username?: string | null;
        email?: string | null;
      }
    | null
    | undefined;

  return (
    texto(dados?.name) ||
    texto(dados?.nome) ||
    texto(dados?.username) ||
    texto(dados?.email) ||
    "Sistema"
  );
}

function sanitizarObservacao(observacao: {
  id: string;
  serviceOrderId: string;
  userName: string | null;
  note: string;
  createdAt: Date;
}) {
  return {
    id: observacao.id,
    serviceOrderId: observacao.serviceOrderId,
    userName: observacao.userName || "Sistema",
    note: observacao.note,
    createdAt: observacao.createdAt,
  };
}

export async function GET(_request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.observacoes");

    if (!acesso.ok) {
      return acesso.response;
    }

    const { id } = await context.params;

    const ordem = await prisma.serviceOrder.findUnique({
      where: { id },
      select: { id: true },
    });

    if (!ordem) {
      return NextResponse.json(
        { message: "Ordem não encontrada." },
        { status: 404 }
      );
    }

    const observacoes = await prisma.serviceOrderInternalNote.findMany({
      where: {
        serviceOrderId: id,
      },
      orderBy: {
        createdAt: "desc",
      },
    });

    return NextResponse.json(observacoes.map(sanitizarObservacao));
  } catch (error) {
    console.error("Erro ao buscar observações da OS:", error);

    return NextResponse.json(
      { message: "Erro ao buscar observações da OS." },
      { status: 500 }
    );
  }
}

export async function POST(request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.observacoes");

    if (!acesso.ok) {
      return acesso.response;
    }

    const { id } = await context.params;
    const body = (await request.json().catch(() => null)) as Record<
      string,
      unknown
    > | null;

    if (!body || typeof body !== "object") {
      return NextResponse.json(
        { message: "Dados inválidos para salvar observação." },
        { status: 400 }
      );
    }

    const note = texto(
      body.note || body.observacao || body.observacaoInterna || body.texto
    );

    if (!note) {
      return NextResponse.json(
        { message: "Informe a observação." },
        { status: 400 }
      );
    }

    if (note.length > LIMITE_OBSERVACAO) {
      return NextResponse.json(
        {
          message: `A observação deve ter no máximo ${LIMITE_OBSERVACAO} caracteres.`,
        },
        { status: 400 }
      );
    }

    const ordem = await prisma.serviceOrder.findUnique({
      where: { id },
      select: { id: true },
    });

    if (!ordem) {
      return NextResponse.json(
        { message: "Ordem não encontrada." },
        { status: 404 }
      );
    }

    const userName = nomeOperador(acesso.usuario);

    const observacao = await prisma.serviceOrderInternalNote.create({
      data: {
        serviceOrderId: id,
        userName,
        note,
      },
    });

    await prisma.orderHistory.create({
      data: {
        serviceOrderId: id,
        userName,
        action: "OBSERVACAO_INTERNA",
        description: "Observação interna adicionada à OS.",
      },
    });

    return NextResponse.json(sanitizarObservacao(observacao), { status: 201 });
  } catch (error) {
    console.error("Erro ao salvar observação da OS:", error);

    return NextResponse.json(
      { message: "Erro ao salvar observação da OS." },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { OrderStatus, PaymentMethod } from "@prisma/client";
import { prisma } from "@/lib/prisma";
import { resolverOperadorPadrao } from "@/lib/operadorSistema";
import { exigirPermissaoApi } from "@/lib/permissaoApi";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{
    id: string;
  }>;
};

const formasPagamentoPermitidas: PaymentMethod[] = [
  PaymentMethod.DINHEIRO,
  PaymentMethod.PIX,
  PaymentMethod.CARTAO,
  PaymentMethod.PARCELADO,
];

const nomesPagamento: Record<string, string> = {
  DINHEIRO: "Dinheiro",
  PIX: "Pix",
  CARTAO: "Cartão",
  PARCELADO: "Parcelado",
  AGUARDANDO_PAGAMENTO: "Aguardando pagamento",
};

function formatarMoeda(valor: number) {
  return valor.toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL",
  });
}

function numeroPercentual(valor: unknown) {
  const numero = Number(String(valor ?? "").replace(",", "."));

  return Number.isFinite(numero) ? numero : 0;
}

function limitarTexto(valor: unknown, limite = 500) {
  const texto = String(valor || "").trim();

  return texto ? texto.slice(0, limite) : null;
}

function nomeOperadorUsuario(usuario: unknown) {
  const dados = usuario as {
    name?: string | null;
    username?: string | null;
  } | null;

  return String(dados?.name || dados?.username || "").trim();
}

export async function GET(_request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi([
      "pagamentos.ver",
      "pagamentos.registrar",
      "relatorios.financeiro",
    ]);

    if (!acesso.ok) {
      return acesso.response;
    }

    const { id } = await context.params;

    const pagamentos = await prisma.serviceOrderPayment.findMany({
      where: {
        serviceOrderId: id,
      },
      orderBy: {
        createdAt: "desc",
      },
    });

    return NextResponse.json(pagamentos);
  } catch (error) {
    console.error("Erro ao buscar pagamentos:", error);

    return NextResponse.json(
      { message: "Erro ao buscar pagamentos." },
      { status: 500 }
    );
  }
}

export async function PATCH(request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("pagamentos.registrar");

    if (!acesso.ok) {
      return acesso.response;
    }

    const { id } = await context.params;
    const body = await request.json().catch(() => ({}));

    const paymentMethodRecebido = String(body.paymentMethod || "")
      .trim()
      .toUpperCase();
    const paymentMethod = paymentMethodRecebido as PaymentMethod;

    const userName =
      nomeOperadorUsuario(acesso.usuario) || (await resolverOperadorPadrao(null));

    const note = limitarTexto(body.note);
    const paymentPercent = numeroPercentual(body.paymentPercent);

    if (!formasPagamentoPermitidas.includes(paymentMethod)) {
      return NextResponse.json(
        { message: "Forma de pagamento inválida." },
        { status: 400 }
      );
    }

    if (
      !Number.isFinite(paymentPercent) ||
      paymentPercent <= 0 ||
      paymentPercent > 100
    ) {
      return NextResponse.json(
        { message: "Informe um percentual entre 1% e 100%." },
        { status: 400 }
      );
    }

    const ordemExistente = await prisma.serviceOrder.findUnique({
      where: {
        id,
      },
      include: {
        finalization: true,
      },
    });

    if (!ordemExistente) {
      return NextResponse.json(
        { message: "Ordem não encontrada." },
        { status: 404 }
      );
    }

    if (ordemExistente.status === OrderStatus.CANCELADO) {
      return NextResponse.json(
        { message: "Não é possível receber pagamento de uma OS cancelada." },
        { status: 400 }
      );
    }

    if (
      ordemExistente.status === OrderStatus.ENTREGUE ||
      ordemExistente.finalization
    ) {
      return NextResponse.json(
        {
          message:
            "Não é possível registrar pagamento em uma OS finalizada/entregue. Reabra a OS primeiro.",
        },
        { status: 400 }
      );
    }

    const totalAmount = Number(ordemExistente.totalAmount || 0);

    if (!Number.isFinite(totalAmount) || totalAmount <= 0) {
      return NextResponse.json(
        {
          message:
            "A OS não possui valor total válido para receber pagamento.",
        },
        { status: 400 }
      );
    }

    const percentualJaPago = Number(ordemExistente.paymentPercent || 0);
    const valorJaPago = Number(ordemExistente.paidAmount || 0);

    if (percentualJaPago >= 100) {
      return NextResponse.json(
        { message: "Esta OS já está com pagamento completo." },
        { status: 400 }
      );
    }

    const novoPercentualTotal = percentualJaPago + paymentPercent;

    if (novoPercentualTotal > 100) {
      return NextResponse.json(
        {
          message: `Pagamento excede 100%. Já consta ${percentualJaPago}% pago. Restante: ${
            100 - percentualJaPago
          }%.`,
        },
        { status: 400 }
      );
    }

    const valorPagamento = Number(
      ((totalAmount * paymentPercent) / 100).toFixed(2)
    );

    const novoValorPago = Number((valorJaPago + valorPagamento).toFixed(2));

    const tipoPagamento =
      novoPercentualTotal >= 100 ? "Pagamento total" : "Pagamento parcial";

    const ordem = await prisma.serviceOrder.update({
      where: {
        id,
      },
      data: {
        paymentMethod,
        paymentPercent: novoPercentualTotal,
        paidAmount: novoValorPago,
        paymentReceivedAt: new Date(),

        payments: {
          create: {
            amount: valorPagamento,
            percent: paymentPercent,
            paymentMethod,
            note,
            userName,
          },
        },

        histories: {
          create: {
            userName,
            action:
              novoPercentualTotal >= 100
                ? "PAGAMENTO_TOTAL"
                : "PAGAMENTO_PARCIAL",
            description: `${tipoPagamento} registrado. Forma: ${
              nomesPagamento[paymentMethod] || paymentMethod
            }. Percentual deste pagamento: ${paymentPercent}%. Valor: ${formatarMoeda(
              valorPagamento
            )}. Total pago: ${novoPercentualTotal}%.`,
          },
        },
      },
      include: {
        customer: true,
        histories: {
          orderBy: {
            createdAt: "desc",
          },
        },
        finalization: true,
        payments: {
          orderBy: {
            createdAt: "desc",
          },
        },
      },
    });

    return NextResponse.json(ordem);
  } catch (error) {
    console.error("Erro ao registrar pagamento:", error);

    return NextResponse.json(
      { message: "Erro ao registrar pagamento." },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import {
  exigirPermissaoApi,
  usuarioPodeVerDadosFinanceirosSensiveis,
  usuarioTemPermissao,
} from "@/lib/permissaoApi";
import { toFutureHttpError } from "@/lib/estoqueTecnico/errors";
import { reverseConsumedTechnicalPartManually } from "@/lib/estoqueTecnico/orderReversalService";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{
    id: string;
    itemId: string;
  }>;
};

type UsuarioSessao = NonNullable<Parameters<typeof usuarioTemPermissao>[0]>;

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function nomeOperador(usuario: UsuarioSessao | null | undefined) {
  return usuario?.name?.trim() || usuario?.username?.trim() || "Sistema";
}

function json(
  body: unknown,
  status = 200,
  extraHeaders?: Record<string, string>,
) {
  return NextResponse.json(body, {
    status,
    headers: {
      "Cache-Control": "no-store",
      ...(extraHeaders || {}),
    },
  });
}

function origemPermitida(request: Request) {
  const origin = request.headers.get("origin");
  if (!origin) return true;

  try {
    return new URL(origin).origin === new URL(request.url).origin;
  } catch {
    return false;
  }
}

function idempotencyKey(request: Request) {
  const value = request.headers.get("Idempotency-Key")?.trim() || "";
  return UUID_PATTERN.test(value) ? value : null;
}

function validarPayload(body: Record<string, unknown>) {
  const allowed = new Set([
    "technicalPartVersion",
    "expectedQuantity",
    "physicalReturnConfirmed",
    "confirmation",
    "reason",
  ]);

  if (Object.keys(body).some((key) => !allowed.has(key))) {
    return "O payload contém campos não permitidos para estorno.";
  }

  if (
    !Number.isInteger(body.technicalPartVersion) ||
    Number(body.technicalPartVersion) < 0
  ) {
    return "A versão da peça técnica é inválida.";
  }

  if (
    !Number.isInteger(body.expectedQuantity) ||
    Number(body.expectedQuantity) <= 0
  ) {
    return "A quantidade esperada é inválida.";
  }

  if (body.physicalReturnConfirmed !== true) {
    return "Confirme que a peça retornou fisicamente ao estoque.";
  }

  if (body.confirmation !== true) {
    return "Confirme o estorno manual da peça.";
  }

  if (typeof body.reason !== "string") {
    return "Informe o motivo do estorno.";
  }

  const reason = body.reason.trim();
  if (reason.length < 10) return "Descreva melhor o motivo do estorno.";
  if (reason.length > 1000) {
    return "O motivo deve ter no máximo 1000 caracteres.";
  }

  return null;
}

function estoqueError(error: unknown) {
  const mapped = toFutureHttpError(error);
  return json(
    mapped.body,
    mapped.status,
    mapped.body.retryable ? { "Retry-After": "1" } : undefined,
  );
}

export async function PATCH(request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.editar");
    if (!acesso.ok) return acesso.response;

    if (!origemPermitida(request)) {
      return json(
        {
          code: "PERMISSION_DENIED",
          message: "Origem da requisição não permitida.",
        },
        403,
      );
    }

    const contentType = (request.headers.get("content-type") || "").toLowerCase();
    if (!contentType.startsWith("application/json")) {
      return json(
        {
          code: "VALIDATION_ERROR",
          message: "Content-Type application/json é obrigatório.",
        },
        422,
      );
    }

    const key = idempotencyKey(request);
    if (!key) {
      return json(
        {
          code: "IDEMPOTENCY_KEY_INVALID",
          message: "Idempotency-Key UUID válido é obrigatório.",
        },
        422,
      );
    }

    const body = (await request.json().catch(() => null)) as
      | Record<string, unknown>
      | null;

    if (!body || typeof body !== "object" || Array.isArray(body)) {
      return json(
        {
          code: "VALIDATION_ERROR",
          message: "Dados inválidos para estornar a peça.",
        },
        422,
      );
    }

    const validationMessage = validarPayload(body);
    if (validationMessage) {
      return json(
        {
          code: "VALIDATION_ERROR",
          message: validationMessage,
        },
        422,
      );
    }

    const { id, itemId } = await context.params;

    // Segurança de recurso: itemId precisa pertencer à OS presente na própria URL.
    // A mutação real continua sendo executada exclusivamente pelo core transacional.
    const scopedItem = await prisma.serviceOrderPart.findFirst({
      where: {
        id: itemId,
        serviceOrderId: id,
      },
      select: {
        id: true,
      },
    });

    if (!scopedItem) {
      return json(
        {
          code: "SERVICE_ORDER_PART_NOT_FOUND",
          message: "O item técnico não foi encontrado nesta OS.",
        },
        404,
      );
    }

    try {
      const result = reverseConsumedTechnicalPartManually(
        itemId,
        {
          technicalPartVersion: Number(body.technicalPartVersion),
          expectedQuantity: Number(body.expectedQuantity),
          physicalReturnConfirmed: true,
          confirmation: true,
          reason: String(body.reason).trim(),
        },
        {
          operatorId: acesso.usuario.id || null,
          operatorName: nomeOperador(acesso.usuario),
          canViewFinancialData:
            usuarioPodeVerDadosFinanceirosSensiveis(acesso.usuario),
          idempotencyKey: key,
        },
      );

      return json(result);
    } catch (error) {
      return estoqueError(error);
    }
  } catch {
    return json(
      {
        code: "INTERNAL_ERROR",
        message: "Erro ao estornar peça técnica.",
      },
      500,
    );
  }
}

import {
  changeReservedTechnicalPartQuantity,
  listTechnicalPartsForOrder,
  releaseTechnicalPartFromOrder,
} from "@/lib/estoqueTecnico";
import { stockError } from "@/lib/estoqueTecnico/errors";
import {
  assertAllowedKeys,
  requireNonEmptyString,
  requirePlainRecord,
  requirePositiveInteger,
  requireVersion,
} from "@/lib/estoqueTecnico/validation";
import { exigirPermissaoApi } from "@/lib/permissaoApi";
import {
  commandContext,
  jsonNoStore,
  readJsonObject,
  requireSameOrigin,
  stockHttpError,
} from "@/lib/server/estoqueTecnicoHttp";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type RouteContext = { params: Promise<{ id: string; itemId: string }> };

function requireOwnedItem(serviceOrderId: string, itemId: string) {
  const result = listTechnicalPartsForOrder(serviceOrderId, {
    canViewFinancialData: false,
    states: ["RESERVED", "CONSUMED", "RELEASED", "REVERSED"],
  });
  const item = result.items.find((candidate) => candidate.id === itemId);
  if (!item) {
    throw stockError(
      "SERVICE_ORDER_PART_NOT_FOUND",
      404,
      "O item técnico não foi encontrado nesta ordem de serviço.",
    );
  }
  return item;
}

function changeBody(value: unknown) {
  const body = requirePlainRecord(value);
  assertAllowedKeys(body, [
    "technicalPartVersion",
    "expectedQuantity",
    "newQuantity",
    "reason",
  ]);
  return {
    technicalPartVersion: requireVersion(body.technicalPartVersion, "technicalPartVersion"),
    expectedQuantity: requirePositiveInteger(body.expectedQuantity, "expectedQuantity"),
    newQuantity: requirePositiveInteger(body.newQuantity, "newQuantity"),
    reason: requireNonEmptyString(body.reason, "reason", 1000),
  };
}

function releaseBody(value: unknown) {
  const body = requirePlainRecord(value);
  assertAllowedKeys(body, ["technicalPartVersion", "expectedQuantity", "reason"]);
  return {
    technicalPartVersion: requireVersion(body.technicalPartVersion, "technicalPartVersion"),
    expectedQuantity: requirePositiveInteger(body.expectedQuantity, "expectedQuantity"),
    reason: requireNonEmptyString(body.reason, "reason", 1000),
  };
}

export async function PATCH(request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.editar");
    if (!acesso.ok) return acesso.response;
    requireSameOrigin(request);

    const { id, itemId } = await context.params;
    requireOwnedItem(id, itemId);
    const result = changeReservedTechnicalPartQuantity(
      itemId,
      changeBody(await readJsonObject(request)),
      commandContext(request, acesso.usuario),
    );
    return jsonNoStore(result);
  } catch (error) {
    return stockHttpError(error);
  }
}

export async function DELETE(request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.editar");
    if (!acesso.ok) return acesso.response;
    requireSameOrigin(request);

    const { id, itemId } = await context.params;
    requireOwnedItem(id, itemId);
    const result = releaseTechnicalPartFromOrder(
      itemId,
      releaseBody(await readJsonObject(request)),
      commandContext(request, acesso.usuario),
    );
    return jsonNoStore(result);
  } catch (error) {
    return stockHttpError(error);
  }
}

import {
  getTechnicalPartById,
  listTechnicalParts,
  listTechnicalPartsForOrder,
  reserveTechnicalPartForOrder,
} from "@/lib/estoqueTecnico";
import { validationError } from "@/lib/estoqueTecnico/errors";
import {
  assertAllowedKeys,
  requireBoolean,
  requireNonEmptyString,
  requirePlainRecord,
  requirePositiveInteger,
  requireVersion,
} from "@/lib/estoqueTecnico/validation";
import { exigirPermissaoApi } from "@/lib/permissaoApi";
import {
  commandContext,
  jsonNoStore,
  readJsonObject,
  requireSameOrigin,
  stockHttpError,
} from "@/lib/server/estoqueTecnicoHttp";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type RouteContext = { params: Promise<{ id: string }> };

function reserveBody(value: unknown) {
  const body = requirePlainRecord(value);
  assertAllowedKeys(body, [
    "technicalPartId",
    "technicalPartVersion",
    "quantity",
    "confirmReplaceLegacyPartsCost",
  ]);
  return {
    technicalPartId: requireNonEmptyString(body.technicalPartId, "technicalPartId", 191),
    technicalPartVersion: requireVersion(body.technicalPartVersion, "technicalPartVersion"),
    quantity: requirePositiveInteger(body.quantity, "quantity"),
    confirmReplaceLegacyPartsCost:
      body.confirmReplaceLegacyPartsCost === undefined
        ? false
        : requireBoolean(body.confirmReplaceLegacyPartsCost, "confirmReplaceLegacyPartsCost"),
  };
}

export async function GET(request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.editar");
    if (!acesso.ok) return acesso.response;

    const { id } = await context.params;
    const params = new URL(request.url).searchParams;
    for (const key of params.keys()) {
      if (key !== "q") {
        throw validationError("O parâmetro informado não é permitido.", { field: key });
      }
    }

    const vinculadas = listTechnicalPartsForOrder(id, {
      canViewFinancialData: false,
      states: ["RESERVED", "CONSUMED"],
    });
    const ativas = new Set(vinculadas.items.map((item) => item.technicalPartId));
    const q = params.get("q")?.trim();
    const result = listTechnicalParts(
      {
        ...(q ? { q } : {}),
        active: true,
        page: 1,
        pageSize: 20,
        sort: "name_asc",
      },
      { canViewFinancialData: false },
    );

    return jsonNoStore({
      items: result.items.map((raw) => {
        const item = raw as Record<string, unknown>;
        return {
          id: String(item.id),
          name: String(item.name),
          sku: item.sku === null ? null : String(item.sku || ""),
          defaultSalePrice: Number(item.defaultSalePrice || 0),
          quantityOnHand: item.quantityOnHand === null ? null : Number(item.quantityOnHand),
          quantityReserved: Number(item.quantityReserved || 0),
          quantityAvailable: item.quantityAvailable === null ? null : Number(item.quantityAvailable || 0),
          version: Number(item.version || 0),
          alreadyActive: ativas.has(String(item.id)),
        };
      }),
    });
  } catch (error) {
    return stockHttpError(error);
  }
}

export async function POST(request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.editar");
    if (!acesso.ok) return acesso.response;

    requireSameOrigin(request);
    const { id } = await context.params;
    const input = reserveBody(await readJsonObject(request));
    const part = getTechnicalPartById(input.technicalPartId, {
      canViewFinancialData: false,
    }) as Record<string, unknown>;

    const result = reserveTechnicalPartForOrder(
      id,
      {
        ...input,
        unitPrice: Number(part.defaultSalePrice || 0),
      },
      commandContext(request, acesso.usuario),
    );

    return jsonNoStore(result, result.idempotentReplay ? 200 : 201);
  } catch (error) {
    return stockHttpError(error);
  }
}

import { NextResponse } from "next/server";
import { OrderStatus } from "@prisma/client";
import { prisma } from "@/lib/prisma";
import {
  exigirPermissaoApi,
  usuarioTemPermissao,
} from "@/lib/permissaoApi";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{
    id: string;
  }>;
};

type UsuarioSessao = NonNullable<Parameters<typeof usuarioTemPermissao>[0]>;

function nomeOperador(usuario: UsuarioSessao | null | undefined) {
  return usuario?.name?.trim() || usuario?.username?.trim() || "Sistema";
}

function podeVerDadosPagamento(usuario: UsuarioSessao | null | undefined) {
  if (!usuario) return false;

  return usuarioTemPermissao(usuario, [
    "pagamentos.ver",
    "pagamentos.registrar",
    "relatorios.financeiro",
  ]);
}

function ocultarDadosPagamentoDaOrdem(ordem: any, mostrarPagamentos: boolean) {
  if (mostrarPagamentos) return ordem;

  return {
    ...ordem,
    paidAmount: null,
    paymentPercent: null,
    paymentReceivedAt: null,
    paymentMethod: null,
    payments: [],
    finalization: ordem.finalization
      ? {
          ...ordem.finalization,
          finalAmount: null,
          paymentMethod: null,
        }
      : null,
  };
}

export async function PATCH(_request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.reabrir");

    if (!acesso.ok) return acesso.response;

    const { id } = await context.params;
    const userName = nomeOperador(acesso.usuario);

    const ordemExistente = await prisma.serviceOrder.findUnique({
      where: { id },
      include: { finalization: true },
    });

    if (!ordemExistente) {
      return NextResponse.json(
        { message: "Ordem não encontrada." },
        { status: 404 }
      );
    }

    const estaFinalizada =
      ordemExistente.status === OrderStatus.ENTREGUE ||
      Boolean(ordemExistente.finalization);

    const estaCancelada = ordemExistente.status === OrderStatus.CANCELADO;

    if (!estaFinalizada && !estaCancelada) {
      return NextResponse.json(
        { message: "Esta OS já está aberta." },
        { status: 400 }
      );
    }

    const ordem = await prisma.$transaction(async (tx) => {
      if (ordemExistente.finalization) {
        await tx.orderFinalization.deleteMany({
          where: { serviceOrderId: id },
        });
      }

      return tx.serviceOrder.update({
        where: { id },
        data: {
          status: OrderStatus.RECEBIDO,
          finalizedAt: null,
          histories: {
            create: {
              userName,
              action: "REABERTURA_OS",
              description:
                "Ordem de serviço reaberta. Finalização removida e status alterado para Recebido.",
            },
          },
        },
        include: {
          customer: true,
          histories: { orderBy: { createdAt: "desc" } },
          finalization: true,
          attachments: true,
          payments: { orderBy: { createdAt: "desc" } },
        },
      });
    });

    return NextResponse.json(
      ocultarDadosPagamentoDaOrdem(ordem, podeVerDadosPagamento(acesso.usuario))
    );
  } catch (error) {
    console.error("Erro ao reabrir OS:", error);

    return NextResponse.json(
      { message: "Erro ao reabrir ordem de serviço." },
      { status: 500 }
    );
  }
}

