export async function GET(request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.imprimir");

    if (!acesso.ok) {
      return acesso.response;
    }

    if (
      !usuarioTemPermissao(acesso.usuario, [
        "pagamentos.ver",
        "pagamentos.registrar",
        "relatorios.financeiro",
      ])
    ) {
      return NextResponse.json(
        { message: "Você não tem permissão financeira para gerar recibo." },
        { status: 403 }
      );
    }

    const userName = nomeOperador(acesso.usuario);

    const { id } = await context.params;

    const ordem = await prisma.serviceOrder.findUnique({
      where: { id },
      include: {
        customer: true,
        finalization: true,
        payments: {
          orderBy: {
            createdAt: "desc",
          },
        },
      },
    });

    if (!ordem) {
      return NextResponse.json(
        { message: "Ordem não encontrada." },
        { status: 404 }
      );
    }

    if (Number(ordem.paymentPercent || 0) <= 0) {
      return NextResponse.json(
        { message: "Esta OS ainda não possui pagamento registrado." },
        { status: 400 }
      );
    }

    const { origin } = new URL(request.url);
    const empresa = await buscarConfiguracoesSistema(origin);

    const pdfBuffer = await gerarPDFRecibo({
      ordem,
      empresa,
    });

    await prisma.serviceOrder.update({
      where: { id },
      data: {
        histories: {
          create: {
            userName,
            action: "RECIBO_PAGAMENTO",
            description: "Recibo de pagamento gerado em PDF.",
          },
        },
      },
    });

    const pdfArrayBuffer = pdfBuffer.buffer.slice(
      pdfBuffer.byteOffset,
      pdfBuffer.byteOffset + pdfBuffer.byteLength
    ) as ArrayBuffer;

    const numeroOS = String(ordem.osNumber || ordem.id).padStart(3, "0");

    return new Response(pdfArrayBuffer, {
      status: 200,
      headers: {
        "Content-Type": "application/pdf",
        "Content-Disposition": `inline; filename="recibo-os-${numeroOS}.pdf"`,
        "Cache-Control": "no-store",
      },
    });
  } catch (error) {
    console.error("Erro ao gerar recibo:", error);

    return NextResponse.json(
      { message: "Erro ao gerar recibo de pagamento." },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { EquipmentType, OrderStatus, PaymentMethod } from "@prisma/client";
import { prisma } from "@/lib/prisma";
import {
  exigirPermissaoApi,
  usuarioTemPermissao,
} from "@/lib/permissaoApi";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{
    id: string;
  }>;
};

type UsuarioSessao = NonNullable<Parameters<typeof usuarioTemPermissao>[0]>;

function calcularTotal(partsCost: number, laborCost: number, discount: number) {
  return Math.max(partsCost + laborCost - discount, 0);
}

function textoOuNulo(valor: unknown, limite = 1000) {
  const texto = String(valor || "")
    .trim()
    .slice(0, limite);

  return texto || null;
}

function textoObrigatorio(valor: unknown, limite = 1000) {
  return String(valor || "")
    .trim()
    .slice(0, limite);
}

function numeroSeguro(valor: unknown) {
  const numero = Number(valor ?? 0);
  return Number.isFinite(numero) ? Math.max(numero, 0) : 0;
}

function nomeOperador(usuario: UsuarioSessao | null | undefined) {
  return usuario?.name?.trim() || usuario?.username?.trim() || "Sistema";
}

function dataOuNulo(valor: unknown) {
  if (!valor) return null;

  const data = new Date(String(valor));

  if (Number.isNaN(data.getTime())) return "INVALIDA" as const;

  return data;
}

export async function GET(_request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.ver");

    if (!acesso.ok) return acesso.response;

    const { id } = await context.params;

    const ordem = await prisma.serviceOrder.findUnique({
      where: { id },
      include: {
        customer: true,
        histories: { orderBy: { createdAt: "desc" } },
        finalization: true,
        attachments: { orderBy: { createdAt: "desc" } },
        payments: { orderBy: { createdAt: "desc" } },
        technicalParts: {
          orderBy: [{ createdAt: "asc" }, { id: "asc" }],
          select: {
            id: true,
            technicalPartId: true,
            partNameSnapshot: true,
            partSkuSnapshot: true,
            unitPriceSnapshot: true,
            quantity: true,
            totalPriceSnapshot: true,
            state: true,
            consumedAt: true,
            reversedAt: true,
            responsibleUserNameSnapshot: true,
            technicalPart: {
              select: {
                version: true,
              },
            },
          },
        },
      },
    });

    if (!ordem) {
      return NextResponse.json(
        { message: "Ordem não encontrada." },
        { status: 404 }
      );
    }

    return NextResponse.json(ordem);
  } catch (error) {
    console.error("Erro ao buscar ordem:", error);

    return NextResponse.json(
      { message: "Erro ao buscar ordem." },
      { status: 500 }
    );
  }
}

export async function PUT(request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.editar");

    if (!acesso.ok) return acesso.response;

    const { id } = await context.params;
    const body = (await request.json().catch(() => null)) as Record<
      string,
      unknown
    > | null;

    if (!body || typeof body !== "object") {
      return NextResponse.json(
        { message: "Dados inválidos para editar a OS." },
        { status: 400 }
      );
    }

    const userName = nomeOperador(acesso.usuario);
    const customerId = textoObrigatorio(body.customerId, 80);

    if (!customerId) {
      return NextResponse.json(
        { message: "Selecione um cliente." },
        { status: 400 }
      );
    }

    const equipamentoRecebido = textoObrigatorio(
      body.equipmentType,
      40
    ) as EquipmentType;

    if (!Object.values(EquipmentType).includes(equipamentoRecebido)) {
      return NextResponse.json(
        { message: "Tipo de equipamento inválido." },
        { status: 400 }
      );
    }

    if (
      equipamentoRecebido === EquipmentType.OUTRO &&
      !textoObrigatorio(body.equipmentOther, 120)
    ) {
      return NextResponse.json(
        { message: "Informe qual é o equipamento." },
        { status: 400 }
      );
    }

    const reportedDefect = textoObrigatorio(body.reportedDefect, 4000);

    if (!reportedDefect) {
      return NextResponse.json(
        { message: "Informe o defeito relatado pelo cliente." },
        { status: 400 }
      );
    }

    const [ordemExistente, clienteExiste] = await Promise.all([
      prisma.serviceOrder.findUnique({
        where: { id },
        include: {
          finalization: true,
          payments: true,
          attachments: true,
        },
      }),
      prisma.customer.findUnique({
        where: { id: customerId },
        select: { id: true },
      }),
    ]);

    if (!clienteExiste) {
      return NextResponse.json(
        { message: "Cliente selecionado não encontrado." },
        { status: 404 }
      );
    }

    if (!ordemExistente) {
      return NextResponse.json(
        { message: "Ordem não encontrada." },
        { status: 404 }
      );
    }

    if (ordemExistente.status === OrderStatus.CANCELADO) {
      return NextResponse.json(
        {
          message:
            "Não é possível editar uma OS cancelada. Reabra a OS primeiro.",
        },
        { status: 400 }
      );
    }

    if (
      ordemExistente.status === OrderStatus.ENTREGUE ||
      ordemExistente.finalization
    ) {
      return NextResponse.json(
        {
          message:
            "Não é possível editar uma OS finalizada/entregue. Reabra a OS primeiro.",
        },
        { status: 400 }
      );
    }

    const statusRecebido = textoObrigatorio(
      body.status || ordemExistente.status,
      40
    ) as OrderStatus;

    if (!Object.values(OrderStatus).includes(statusRecebido)) {
      return NextResponse.json(
        { message: "Status inválido." },
        { status: 400 }
      );
    }

    const statusPermitidosNaEdicao: OrderStatus[] = [
      OrderStatus.RECEBIDO,
      OrderStatus.EM_ANALISE,
      OrderStatus.AGUARDANDO_PECA,
      OrderStatus.EM_REPARO,
    ];

    const statusEhMesmoAtual = statusRecebido === ordemExistente.status;

    if (
      !statusEhMesmoAtual &&
      !statusPermitidosNaEdicao.includes(statusRecebido)
    ) {
      return NextResponse.json(
        {
          message:
            "Status inválido para edição. Use o status rápido para PRONTO, a finalização para ENTREGUE e a tela de cancelamento para CANCELADO.",
        },
        { status: 400 }
      );
    }

    if (ordemExistente.status === OrderStatus.PRONTO && !statusEhMesmoAtual) {
      return NextResponse.json(
        {
          message:
            "Esta OS está PRONTA. Para alterar o status, use o status rápido.",
        },
        { status: 400 }
      );
    }

    const statusParaSalvar = statusEhMesmoAtual
      ? ordemExistente.status
      : statusRecebido;

    const partsCost = numeroSeguro(body.partsCost);
    const laborCost = numeroSeguro(body.laborCost);
    const discount = numeroSeguro(body.discount);
    const totalAmount = calcularTotal(partsCost, laborCost, discount);

    let paymentMethod = ordemExistente.paymentMethod;

    const paymentMethodRecebido = textoObrigatorio(
      body.paymentMethod || "AGUARDANDO_PAGAMENTO",
      40
    ) as PaymentMethod;

      if (!Object.values(PaymentMethod).includes(paymentMethodRecebido)) {
        return NextResponse.json(
          { message: "Forma de pagamento inválida." },
          { status: 400 }
        );
      }

    paymentMethod = paymentMethodRecebido;

    const expectedDeliveryDate = dataOuNulo(body.expectedDeliveryDate);

    if (expectedDeliveryDate === "INVALIDA") {
      return NextResponse.json(
        { message: "Data prevista para entrega inválida." },
        { status: 400 }
      );
    }

    const ordem = await prisma.serviceOrder.update({
      where: { id },
      data: {
        customerId,
        equipmentType: equipamentoRecebido,
        equipmentOther:
          equipamentoRecebido === EquipmentType.OUTRO
            ? textoOuNulo(body.equipmentOther, 120)
            : null,
        brand: textoOuNulo(body.brand, 120),
        model: textoOuNulo(body.model, 120),
        serialNumber: textoOuNulo(body.serialNumber, 120),
        imei: textoOuNulo(body.imei, 80),
        devicePassword: textoOuNulo(body.devicePassword, 120),
        deliveredAccessories: textoOuNulo(body.deliveredAccessories, 2000),
        reportedDefect,
        technicalNotes: textoOuNulo(body.technicalNotes, 4000),
        requiredParts: textoOuNulo(body.requiredParts, 2000),
        partsCost,
        laborCost,
        discount,
        totalAmount,
        paymentMethod,
        status: statusParaSalvar,
        expectedDeliveryDate,
        histories: {
          create: {
            userName,
            action: "EDICAO_OS",
            description: "Ordem de serviço editada.",
          },
        },
      },
      include: {
        customer: true,
        histories: { orderBy: { createdAt: "desc" } },
        finalization: true,
        attachments: { orderBy: { createdAt: "desc" } },
        payments: { orderBy: { createdAt: "desc" } },
      },
    });

    return NextResponse.json(ordem);
  } catch (error) {
    console.error("Erro ao editar ordem:", error);

    return NextResponse.json(
      { message: "Erro ao editar ordem de serviço." },
      { status: 500 }
    );
  }
}

export async function DELETE(_request: Request, context: RouteContext) {
  try {
    const acesso = await exigirPermissaoApi("ordens.cancelar");

    if (!acesso.ok) return acesso.response;

    const { id } = await context.params;

    const ordemExistente = await prisma.serviceOrder.findUnique({
      where: { id },
      include: {
        finalization: true,
        payments: true,
        attachments: true,
      },
    });

    if (!ordemExistente) {
      return NextResponse.json(
        { message: "Ordem não encontrada." },
        { status: 404 }
      );
    }

    const temPagamento =
      ordemExistente.payments.length > 0 ||
      numeroSeguro(ordemExistente.paidAmount) > 0 ||
      numeroSeguro(ordemExistente.paymentPercent) > 0;

    const temFinalizacao =
      ordemExistente.status === OrderStatus.ENTREGUE ||
      Boolean(ordemExistente.finalization);

    const temAnexo = ordemExistente.attachments.length > 0;

    if (temPagamento || temFinalizacao || temAnexo) {
      return NextResponse.json(
        {
          message:
            "Esta OS possui pagamento, finalização ou anexo. Por segurança, ela não pode ser excluída definitivamente. Use Cancelar OS.",
        },
        { status: 400 }
      );
    }

    await prisma.$transaction([
      prisma.serviceOrderInternalNote.deleteMany({
        where: { serviceOrderId: id },
      }),
      prisma.orderHistory.deleteMany({
        where: { serviceOrderId: id },
      }),
      prisma.serviceOrder.delete({
        where: { id },
      }),
    ]);

    return NextResponse.json({
      message: "Ordem excluída com sucesso.",
    });
  } catch (error) {
    console.error("Erro ao excluir ordem:", error);

    return NextResponse.json(
      { message: "Erro ao excluir ordem de serviço." },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { OrderStatus } from "@prisma/client";
import { prisma } from "@/lib/prisma";
import {
  exigirPermissaoApi,
  usuarioPodeVerDadosFinanceirosSensiveis,
  usuarioTemPermissao,
} from "@/lib/permissaoApi";
import { requireIdempotencyKey } from "@/lib/estoqueTecnico/validation";
import {
  markServiceOrderReadyAndConsumeTechnicalParts,
} from "@/lib/estoqueTecnico";
import { toFutureHttpError } from "@/lib/estoqueTecnico/errors";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{
    id: string;
  }>;
};

type UsuarioSessao = NonNullable<Parameters<typeof usuarioTemPermissao>[0]>;

const statusPermitidos: OrderStatus[] = [
  OrderStatus.RECEBIDO,
  OrderStatus.EM_ANALISE,
  OrderStatus.AGUARDANDO_PECA,
  OrderStatus.EM_REPARO,
];

const nomesStatus: Record<string, string> = {
  RECEBIDO: "Recebido",
  EM_ANALISE: "Em análise",
  AGUARDANDO_PECA: "Aguardando peça",
  EM_REPARO: "Em reparo",
  PRONTO: "Pronto",
  ENTREGUE: "Entregue",
  CANCELADO: "Cancelado",
};

function nomeOperador(usuario: UsuarioSessao | null | undefined) {
  return usuario?.name?.trim() || usuario?.username?.trim() || "Sistema";
}

function podeVerDadosPagamento(usuario: UsuarioSessao | null | undefined) {
  if (!usuario) return false;

  return usuarioTemPermissao(usuario, [
    "pagamentos.ver",
    "pagamentos.registrar",
    "relatorios.financeiro",
  ]);
}

function sanitizarOrdemStatus(
  ordem: any,
  mostrarPagamentos: boolean,
  mostrarFinanceiroSensivel: boolean,
) {
  const base = mostrarPagamentos
    ? ordem
    : {
        ...ordem,
        paidAmount: null,
        paymentPercent: null,
        paymentReceivedAt: null,
        paymentMethod: null,
        payments: [],
        finalization: ordem.finalization
          ? {
              ...ordem.finalization,
              finalAmount: null,
              paymentMethod: null,
            }
          : null,
      };

  if (mostrarFinanceiroSensivel) return base;

  return {
    ...base,
    technicianProfitPercentSnapshot: null,
  };
}

function respostaErroEstoque(error: unknown) {
  const mapped = toFutureHttpError(error);
  const headers: Record<string, string> = { "Cache-Control": "no-store" };
  if (mapped.body.retryable) headers["Retry-After"] = "1";
  return NextResponse.json(mapped.body, { status: mapped.status, headers });
}

function validarComandoPronto(body: Record<string, unknown>) {
  const permitidos = new Set([
    "status",
    "expectedCurrentStatus",
    "confirmation",
    "technicianUserId",
  ]);
  if (Object.keys(body).some((key) => !permitidos.has(key))) {
    return "O payload contém campos não permitidos para concluir a OS.";
  }
  if (body.status !== OrderStatus.PRONTO) return "O status de destino deve ser PRONTO.";
  const statusesOrigem: string[] = [
    OrderStatus.RECEBIDO,
    OrderStatus.EM_ANALISE,
    OrderStatus.AGUARDANDO_PECA,
    OrderStatus.EM_REPARO,
  ];
  if (
    typeof body.expectedCurrentStatus !== "string" ||
    !statusesOrigem.includes(body.expectedCurrentStatus)
  ) {
    return "Informe o status atual esperado da OS.";
  }
  if (body.confirmation !== true) return "Confirme a conclusão do reparo.";
  if (
    typeof body.technicianUserId !== "string" ||
    !body.technicianUserId.trim()
  ) {
    return "Selecione o técnico responsável pelo serviço.";
  }
  return null;
}

export async function PATCH(request: Request, context: RouteContext) {
  try {
    const body = (await request.json().catch(() => null)) as Record<
      string,
      unknown
    > | null;

    if (!body || typeof body !== "object") {
      return NextResponse.json(
        { message: "Dados inválidos para alterar status." },
        { status: 400 }
      );
    }

    const statusSolicitado = String(body.status || "").trim().toUpperCase();

    const permissaoStatus =
      statusSolicitado === OrderStatus.PRONTO
        ? "ordens.marcar_pronto"
        : "ordens.alterar_status";

    const acesso = await exigirPermissaoApi(permissaoStatus);

    if (!acesso.ok) return acesso.response;

    const { id } = await context.params;
    const novoStatus = statusSolicitado as OrderStatus;
    const userName = nomeOperador(acesso.usuario);

    if (statusSolicitado === OrderStatus.PRONTO) {
      if (!String(request.headers.get("content-type") || "").toLowerCase().startsWith("application/json")) {
        return NextResponse.json(
          { code: "VALIDATION_ERROR", message: "Content-Type application/json é obrigatório." },
          { status: 422, headers: { "Cache-Control": "no-store" } },
        );
      }
      const payloadError = validarComandoPronto(body);
      if (payloadError) {
        return NextResponse.json(
          { code: "VALIDATION_ERROR", message: payloadError },
          { status: 422, headers: { "Cache-Control": "no-store" } },
        );
      }
      let idempotencyKey: string;
      try {
        idempotencyKey = requireIdempotencyKey(request.headers.get("Idempotency-Key"));
      } catch (error) {
        const mapped = toFutureHttpError(error);
        return NextResponse.json(
          { ...mapped.body, code: mapped.body.code },
          { status: 422, headers: { "Cache-Control": "no-store" } },
        );
      }
      try {
        const result = markServiceOrderReadyAndConsumeTechnicalParts(
          id,
          {
            expectedCurrentStatus: body.expectedCurrentStatus,
            confirmation: true,
            technicianUserId: String(body.technicianUserId).trim(),
          },
          {
            operatorId: acesso.usuario.id || null,
            operatorName: userName,
            canViewFinancialData: usuarioPodeVerDadosFinanceirosSensiveis(acesso.usuario),
            idempotencyKey,
          },
        );

        // Leitura complementar somente após o commit para manter o contrato
        // histórico da rota; falhas aqui não desfazem o consumo confirmado.
        try {
          const ordemCompleta = await prisma.serviceOrder.findUnique({
            where: { id },
            include: {
              customer: true,
              histories: { orderBy: { createdAt: "desc" } },
              finalization: true,
              attachments: true,
              payments: { orderBy: { createdAt: "desc" } },
            },
          });
          if (ordemCompleta) {
            return NextResponse.json(
              sanitizarOrdemStatus(
                ordemCompleta,
                podeVerDadosPagamento(acesso.usuario),
                usuarioPodeVerDadosFinanceirosSensiveis(acesso.usuario),
              ),
            );
          }
        } catch {
          // O commit já ocorreu; retornar o resumo seguro abaixo.
        }
        return NextResponse.json({
          ...result,
          reloadOrder: true,
        });
      } catch (error) {
        return respostaErroEstoque(error);
      }
    }

    if (!statusPermitidos.includes(novoStatus)) {
      return NextResponse.json(
        {
          message:
            "Status inválido para alteração rápida. Para cancelar, use a tela de cancelamento. Para entregar, use a finalização.",
        },
        { status: 400 }
      );
    }

    const ordemExistente = await prisma.serviceOrder.findUnique({
      where: { id },
      include: { finalization: true },
    });

    if (!ordemExistente) {
      return NextResponse.json(
        { message: "Ordem não encontrada." },
        { status: 404 }
      );
    }

    if (ordemExistente.status === OrderStatus.CANCELADO) {
      return NextResponse.json(
        {
          message:
            "Não é possível alterar status de uma OS cancelada. Reabra a OS primeiro.",
        },
        { status: 400 }
      );
    }

    if (
      ordemExistente.status === OrderStatus.ENTREGUE ||
      ordemExistente.finalization
    ) {
      return NextResponse.json(
        {
          message:
            "Não é possível alterar status de uma OS finalizada/entregue. Reabra a OS primeiro.",
        },
        { status: 400 }
      );
    }

    if (ordemExistente.status === novoStatus) {
      return NextResponse.json(
        { message: "Escolha um status diferente do atual." },
        { status: 400 }
      );
    }

    const statusAnterior = ordemExistente.status;

    const descriptionStatus = `Status alterado de ${
      nomesStatus[statusAnterior] || statusAnterior
    } para ${nomesStatus[novoStatus] || novoStatus}.`;

    const ordemAtualizada = await prisma.serviceOrder.update({
      where: { id },
      data: {
        status: novoStatus,
        histories: {
          create: {
            userName,
            action: "ALTERACAO_STATUS",
            description: descriptionStatus,
          },
        },
      },
      include: {
        customer: true,
        histories: { orderBy: { createdAt: "desc" } },
        finalization: true,
        attachments: true,
        payments: { orderBy: { createdAt: "desc" } },
      },
    });

    return NextResponse.json(
      sanitizarOrdemStatus(
        ordemAtualizada,
        podeVerDadosPagamento(acesso.usuario),
        usuarioPodeVerDadosFinanceirosSensiveis(acesso.usuario),
      )
    );
  } catch {
    return NextResponse.json(
      { message: "Erro ao alterar status da OS." },
      { status: 500 }
    );
  }
}

// app/api/ordens/atrasadas/route.ts
// v1.1.0 - Mantém proteção server-side e sanitização financeira.

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { exigirPermissaoApi } from "@/lib/permissaoApi";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

function inicioDoDia(data: Date) {
  const novaData = new Date(data);
  novaData.setHours(0, 0, 0, 0);
  return novaData;
}

function calcularDiasAtraso(dataPrevisao: Date | string | null) {
  if (!dataPrevisao) return 0;

  const hoje = inicioDoDia(new Date());
  const previsao = inicioDoDia(new Date(dataPrevisao));

  if (Number.isNaN(previsao.getTime())) return 0;

  const umDia = 1000 * 60 * 60 * 24;
  const diferenca = Math.floor((hoje.getTime() - previsao.getTime()) / umDia);

  return Math.max(diferenca, 0);
}

function resumoPorStatus(ordens: { status: string }[]) {
  return {
    recebido: ordens.filter((ordem) => ordem.status === "RECEBIDO").length,
    emAnalise: ordens.filter((ordem) => ordem.status === "EM_ANALISE").length,
    aguardandoPeca: ordens.filter((ordem) => ordem.status === "AGUARDANDO_PECA")
      .length,
    emReparo: ordens.filter((ordem) => ordem.status === "EM_REPARO").length,
  };
}

export async function GET() {
  try {
    const acesso = await exigirPermissaoApi("ordens.ver");

    if (!acesso.ok) {
      return acesso.response;
    }

    const hoje = inicioDoDia(new Date());

    const ordens = await prisma.serviceOrder.findMany({
      where: {
        expectedDeliveryDate: {
          lt: hoje,
        },
        status: {
          notIn: ["PRONTO", "ENTREGUE", "CANCELADO"],
        },
      },
      select: {
        id: true,
        osNumber: true,

        customer: {
          select: {
            id: true,
            name: true,
            whatsapp: true,
          },
        },

        equipmentType: true,
        equipmentOther: true,
        brand: true,
        model: true,

        status: true,
        totalAmount: true,
        openedAt: true,
        expectedDeliveryDate: true,
      },
      orderBy: {
        expectedDeliveryDate: "asc",
      },
    });

    const ordensFormatadas = ordens.map((ordem) => {
      const diasAtraso = calcularDiasAtraso(ordem.expectedDeliveryDate);

      return {
        id: ordem.id,
        osNumber: ordem.osNumber,

        customer: ordem.customer,
        customerName: ordem.customer?.name || null,
        customerWhatsapp: ordem.customer?.whatsapp || null,

        equipmentType: ordem.equipmentType,
        equipmentOther: ordem.equipmentOther,
        brand: ordem.brand,
        model: ordem.model,

        status: ordem.status,
        totalAmount: ordem.totalAmount,
        openedAt: ordem.openedAt,
        expectedDeliveryDate: ordem.expectedDeliveryDate,

        diasAtraso,
        daysLate: diasAtraso,
      };
    });

    const maiorAtraso = ordensFormatadas.reduce((maior, ordem) => {
      return ordem.diasAtraso > maior ? ordem.diasAtraso : maior;
    }, 0);

    const valorEmAberto = ordens.reduce(
      (total, ordem) => total + Number(ordem.totalAmount || 0),
      0
    );

    return NextResponse.json({
      financeiroLiberado: true,
      resumo: {
        total: ordensFormatadas.length,
        maiorAtraso,
        valorEmAberto,
        ...resumoPorStatus(ordensFormatadas),
      },
      ordens: ordensFormatadas,
    });
  } catch (error) {
    console.error("Erro ao buscar OS atrasadas:", error);

    return NextResponse.json(
      { message: "Erro ao buscar OS atrasadas." },
      { status: 500 }
    );
  }
}

