import PDFDocument from "pdfkit";
import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { exigirPermissaoApi } from "@/lib/permissaoApi";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const nomesPagamento: Record<string, string> = {
  DINHEIRO: "Dinheiro",
  PIX: "Pix",
  CARTAO_CREDITO: "Cartão de crédito",
  CARTAO_DEBITO: "Cartão de débito",
  TRANSFERENCIA: "Transferência",
};

function criarDataLocal(data: string) {
  const [ano, mes, dia] = data.split("-").map(Number);

  return new Date(ano, mes - 1, dia);
}

function inicioDoDia(data: string) {
  const d = criarDataLocal(data);
  d.setHours(0, 0, 0, 0);
  return d;
}

function fimDoDia(data: string) {
  const d = criarDataLocal(data);
  d.setHours(23, 59, 59, 999);
  return d;
}

function formatarMoeda(valor: unknown) {
  return Number(valor || 0).toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL",
  });
}

function formatarData(data: unknown) {
  if (!data) return "-";

  const d = new Date(String(data));

  if (Number.isNaN(d.getTime())) return "-";

  return d.toLocaleDateString("pt-BR");
}

function formatarDataHora(data: unknown) {
  if (!data) return "-";

  const d = new Date(String(data));

  if (Number.isNaN(d.getTime())) return "-";

  return d.toLocaleString("pt-BR");
}

function gerarPDFPagamentos({
  pagamentos,
  dataInicial,
  dataFinal,
}: {
  pagamentos: any[];
  dataInicial: Date;
  dataFinal: Date;
}): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    try {
      const doc = new PDFDocument({
        size: "A4",
        layout: "landscape",
        margin: 30,
      });

      const chunks: Buffer[] = [];

      doc.on("data", (chunk) => chunks.push(chunk));
      doc.on("end", () => resolve(Buffer.concat(chunks)));
      doc.on("error", reject);

      const totalRecebido = pagamentos.reduce((total, pagamento) => {
        return total + Number(pagamento.amount || 0);
      }, 0);

      const totalPagamentos = pagamentos.length;
      const ticketMedio =
        totalPagamentos > 0 ? totalRecebido / totalPagamentos : 0;

      // Cabeçalho
      doc
        .font("Helvetica-Bold")
        .fontSize(18)
        .fillColor("#111827")
        .text("Extrato de Pagamentos", {
          align: "center",
        });

      doc.moveDown(0.3);

      doc
        .font("Helvetica")
        .fontSize(9)
        .fillColor("#475569")
        .text(
          `Periodo: ${formatarData(dataInicial)} ate ${formatarData(dataFinal)}`,
          {
            align: "center",
          }
        );

      doc.moveDown(1);

      // Cards resumo
      const cardY = doc.y;
      const cardW = 240;
      const cardH = 52;

      function card(titulo: string, valor: string, x: number) {
        doc
          .roundedRect(x, cardY, cardW, cardH, 8)
          .fillColor("#f8fafc")
          .fill()
          .strokeColor("#e5e7eb")
          .stroke();

        doc
          .font("Helvetica")
          .fontSize(8)
          .fillColor("#64748b")
          .text(titulo, x + 10, cardY + 10, {
            width: cardW - 20,
          });

        doc
          .font("Helvetica-Bold")
          .fontSize(14)
          .fillColor("#111827")
          .text(valor, x + 10, cardY + 27, {
            width: cardW - 20,
          });
      }

      card("Total recebido", formatarMoeda(totalRecebido), 30);
      card("Pagamentos", String(totalPagamentos), 290);
      card("Ticket medio", formatarMoeda(ticketMedio), 550);

      doc.y = cardY + cardH + 22;

      // Tabela
      const startX = 30;
      let y = doc.y;

      const colunas = {
        data: 85,
        os: 70,
        cliente: 160,
        forma: 105,
        percentual: 70,
        valor: 85,
        observacao: 210,
      };

      function desenharCabecalhoTabela() {
        doc
          .rect(startX, y, 780, 24)
          .fillColor("#f1f5f9")
          .fill();

        doc
          .font("Helvetica-Bold")
          .fontSize(8)
          .fillColor("#111827")
          .text("Data", startX + 6, y + 8, { width: colunas.data })
          .text("OS", startX + 6 + colunas.data, y + 8, {
            width: colunas.os,
          })
          .text("Cliente", startX + 6 + colunas.data + colunas.os, y + 8, {
            width: colunas.cliente,
          })
          .text(
            "Forma",
            startX + 6 + colunas.data + colunas.os + colunas.cliente,
            y + 8,
            { width: colunas.forma }
          )
          .text(
            "%",
            startX +
              6 +
              colunas.data +
              colunas.os +
              colunas.cliente +
              colunas.forma,
            y + 8,
            { width: colunas.percentual }
          )
          .text(
            "Valor",
            startX +
              6 +
              colunas.data +
              colunas.os +
              colunas.cliente +
              colunas.forma +
              colunas.percentual,
            y + 8,
            { width: colunas.valor }
          )
          .text(
            "Observacao",
            startX +
              6 +
              colunas.data +
              colunas.os +
              colunas.cliente +
              colunas.forma +
              colunas.percentual +
              colunas.valor,
            y + 8,
            { width: colunas.observacao }
          );

        y += 28;
      }

      desenharCabecalhoTabela();

      if (pagamentos.length === 0) {
        doc
          .font("Helvetica")
          .fontSize(10)
          .fillColor("#64748b")
          .text("Nenhum pagamento encontrado no periodo.", startX, y + 10);
      } else {
        pagamentos.forEach((pagamento) => {
          if (y > 520) {
            doc.addPage();
            y = 30;
            desenharCabecalhoTabela();
          }

          const ordem = pagamento.serviceOrder;
          const cliente = ordem?.customer;
          const numeroOS = String(ordem?.osNumber || "").padStart(3, "0");

          doc
            .moveTo(startX, y - 4)
            .lineTo(810, y - 4)
            .strokeColor("#e5e7eb")
            .stroke();

          doc
            .font("Helvetica")
            .fontSize(8)
            .fillColor("#111827")
            .text(formatarDataHora(pagamento.createdAt), startX + 6, y, {
              width: colunas.data,
              height: 24,
              ellipsis: true,
            })
            .text(`Nº ${numeroOS}`, startX + 6 + colunas.data, y, {
              width: colunas.os,
              height: 24,
              ellipsis: true,
            })
            .text(
              cliente?.name || "-",
              startX + 6 + colunas.data + colunas.os,
              y,
              {
                width: colunas.cliente,
                height: 24,
                ellipsis: true,
              }
            )
            .text(
              nomesPagamento[pagamento.paymentMethod] ||
                pagamento.paymentMethod ||
                "-",
              startX + 6 + colunas.data + colunas.os + colunas.cliente,
              y,
              {
                width: colunas.forma,
                height: 24,
                ellipsis: true,
              }
            )
            .text(
              `${pagamento.percent}%`,
              startX +
                6 +
                colunas.data +
                colunas.os +
                colunas.cliente +
                colunas.forma,
              y,
              {
                width: colunas.percentual,
                height: 24,
              }
            )
            .text(
              formatarMoeda(pagamento.amount),
              startX +
                6 +
                colunas.data +
                colunas.os +
                colunas.cliente +
                colunas.forma +
                colunas.percentual,
              y,
              {
                width: colunas.valor,
                height: 24,
              }
            )
            .text(
              pagamento.note || "-",
              startX +
                6 +
                colunas.data +
                colunas.os +
                colunas.cliente +
                colunas.forma +
                colunas.percentual +
                colunas.valor,
              y,
              {
                width: colunas.observacao,
                height: 24,
                ellipsis: true,
              }
            );

          y += 30;
        });
      }

      // Rodapé
      doc
        .font("Helvetica")
        .fontSize(8)
        .fillColor("#64748b")
        .text(
          "Documento gerado automaticamente pelo sistema de Ordem de Servico.",
          30,
          560,
          {
            width: 780,
            align: "center",
          }
        );

      doc.end();
    } catch (error) {
      reject(error);
    }
  });
}

export async function GET(request: Request) {
  try {
    const acesso = await exigirPermissaoApi([
      "pagamentos.ver",
      "relatorios.financeiro",
    ]);

    if (!acesso.ok) {
      return acesso.response;
    }

    const { searchParams } = new URL(request.url);

    const hoje = new Date();

    const inicioParam = searchParams.get("inicio");
    const fimParam = searchParams.get("fim");

    const dataInicial = inicioParam
      ? inicioDoDia(inicioParam)
      : new Date(hoje.getFullYear(), hoje.getMonth(), 1, 0, 0, 0, 0);

    const dataFinal = fimParam
      ? fimDoDia(fimParam)
      : new Date(hoje.getFullYear(), hoje.getMonth() + 1, 0, 23, 59, 59, 999);

    const pagamentos = await prisma.serviceOrderPayment.findMany({
      where: {
        createdAt: {
          gte: dataInicial,
          lte: dataFinal,
        },
      },
      orderBy: {
        createdAt: "desc",
      },
      include: {
        serviceOrder: {
          include: {
            customer: true,
          },
        },
      },
    });

    const pdfBuffer = await gerarPDFPagamentos({
      pagamentos,
      dataInicial,
      dataFinal,
    });

    const pdfArrayBuffer = pdfBuffer.buffer.slice(
      pdfBuffer.byteOffset,
      pdfBuffer.byteOffset + pdfBuffer.byteLength
    ) as ArrayBuffer;

    return new Response(pdfArrayBuffer, {
      status: 200,
      headers: {
        "Content-Type": "application/pdf",
        "Content-Disposition": `inline; filename="extrato-pagamentos.pdf"`,
        "Cache-Control": "no-store",
      },
    });
  } catch (error) {
    console.error("Erro ao gerar PDF de pagamentos:", error);

    return NextResponse.json(
      { message: "Erro ao gerar PDF de pagamentos." },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { PaymentMethod, Prisma } from "@prisma/client";
import { prisma } from "@/lib/prisma";
import { exigirPermissaoApi } from "@/lib/permissaoApi";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const FORMAS_PAGAMENTO_VALIDAS = [
  PaymentMethod.PIX,
  PaymentMethod.DINHEIRO,
  PaymentMethod.CARTAO,
  PaymentMethod.PARCELADO,
] as const;

type FormaPagamentoFiltro = (typeof FORMAS_PAGAMENTO_VALIDAS)[number];

function formaPagamentoValida(
  valor: string | null
): FormaPagamentoFiltro | "INVALIDA" | null {
  if (!valor || valor === "TODAS") return null;

  const forma = valor.toUpperCase();

  return (FORMAS_PAGAMENTO_VALIDAS as readonly string[]).includes(forma)
    ? (forma as FormaPagamentoFiltro)
    : "INVALIDA";
}

function criarDataLocalSegura(data: string | null) {
  if (!data) return null;

  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(data);

  if (!match) return null;

  const ano = Number(match[1]);
  const mes = Number(match[2]);
  const dia = Number(match[3]);

  const d = new Date(ano, mes - 1, dia);

  if (
    d.getFullYear() !== ano ||
    d.getMonth() !== mes - 1 ||
    d.getDate() !== dia
  ) {
    return null;
  }

  return d;
}

function inicioDoDia(data: Date) {
  const d = new Date(data);
  d.setHours(0, 0, 0, 0);
  return d;
}

function fimDoDia(data: Date) {
  const d = new Date(data);
  d.setHours(23, 59, 59, 999);
  return d;
}



export async function GET(request: Request) {
  try {
    const acesso = await exigirPermissaoApi(["pagamentos.ver", "relatorios.financeiro"]);

    if (!acesso.ok) {
      return acesso.response;
    }

    const { searchParams } = new URL(request.url);

    const hoje = new Date();

    const inicioParam = searchParams.get("inicio");
    const fimParam = searchParams.get("fim");
    const formaParam = searchParams.get("forma");

    const inicioInformado = criarDataLocalSegura(inicioParam);
    const fimInformado = criarDataLocalSegura(fimParam);
    const formaPagamento = formaPagamentoValida(formaParam);

    if (inicioParam && !inicioInformado) {
      return NextResponse.json(
        { message: "Data inicial inválida." },
        { status: 400 }
      );
    }

    if (fimParam && !fimInformado) {
      return NextResponse.json(
        { message: "Data final inválida." },
        { status: 400 }
      );
    }

    if (formaPagamento === "INVALIDA") {
      return NextResponse.json(
        { message: "Forma de pagamento inválida." },
        { status: 400 }
      );
    }

    const dataInicial = inicioInformado
      ? inicioDoDia(inicioInformado)
      : new Date(hoje.getFullYear(), hoje.getMonth(), 1, 0, 0, 0, 0);

    const dataFinal = fimInformado
      ? fimDoDia(fimInformado)
      : new Date(hoje.getFullYear(), hoje.getMonth() + 1, 0, 23, 59, 59, 999);

    if (dataFinal < dataInicial) {
      return NextResponse.json(
        { message: "A data final não pode ser menor que a data inicial." },
        { status: 400 }
      );
    }

    const where: Prisma.ServiceOrderPaymentWhereInput = {
      createdAt: {
        gte: dataInicial,
        lte: dataFinal,
      },
    };

    if (formaPagamento) {
      where.paymentMethod = formaPagamento;
    }

    const pagamentos = await prisma.serviceOrderPayment.findMany({
      where,
      orderBy: {
        createdAt: "desc",
      },
      select: {
        id: true,
        amount: true,
        percent: true,
        paymentMethod: true,
        note: true,
        userName: true,
        createdAt: true,
        serviceOrder: {
          select: {
            id: true,
            osNumber: true,
            status: true,
            totalAmount: true,
            customer: {
              select: {
                name: true,
                whatsapp: true,
              },
            },
          },
        },
      },
    });

    const totalRecebido = pagamentos.reduce((total, pagamento) => {
      return total + Number(pagamento.amount || 0);
    }, 0);

    const totalPorForma = pagamentos.reduce<Record<string, number>>(
      (acc, pagamento) => {
        const forma = pagamento.paymentMethod || "NAO_INFORMADO";
        acc[forma] = (acc[forma] || 0) + Number(pagamento.amount || 0);
        return acc;
      },
      {}
    );

    const totalPagamentos = pagamentos.length;
    const ticketMedio =
      totalPagamentos > 0 ? totalRecebido / totalPagamentos : 0;

    return NextResponse.json({
      resumo: {
        totalRecebido,
        totalPagamentos,
        ticketMedio,
        dataInicial: dataInicial.toISOString(),
        dataFinal: dataFinal.toISOString(),
        formaPagamento: formaPagamento || "TODAS",
        totalPorForma,
      },
      pagamentos,
    });
  } catch (error) {
    console.error("Erro ao buscar pagamentos:", error);

    return NextResponse.json(
      { message: "Erro ao buscar pagamentos." },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { StockMovementType } from "@prisma/client";
import { prisma } from "@/lib/prisma";
import { exigirModuloProdutosAtivoApi } from "@/lib/moduloProdutos";
import {
  exigirPermissaoApi,
  usuarioTemPermissao,
  usuarioPodeVerDadosFinanceirosSensiveis,
} from "@/lib/permissaoApi";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type UsuarioSessao = NonNullable<Parameters<typeof usuarioTemPermissao>[0]>;

type RouteContext = {
  params: Promise<{
    id: string;
  }>;
};

function numero(valor: unknown) {
  const n = Number(valor ?? 0);
  return Number.isFinite(n) ? n : 0;
}

function inteiro(valor: unknown) {
  return Math.max(0, Math.floor(numero(valor)));
}

function texto(valor: unknown) {
  return String(valor || "").trim();
}

function nomeOperador(usuario: UsuarioSessao) {
  return usuario.name?.trim() || usuario.username?.trim() || "Sistema";
}

function tipoMovimento(valor: unknown) {
  const tipo = texto(valor).toUpperCase();

  if (
    tipo === StockMovementType.ENTRADA ||
    tipo === StockMovementType.SAIDA ||
    tipo === StockMovementType.AJUSTE
  ) {
    return tipo;
  }

  return null;
}

function protegerProduto(produto: any, financeiroSensivelLiberado: boolean) {
  const estoqueIlimitado = produto.stockQuantity === null;
  const valorEstoqueVenda = estoqueIlimitado
    ? null
    : numero(produto.salePrice) * produto.stockQuantity;
  const valorEstoqueCusto = estoqueIlimitado
    ? null
    : numero(produto.costPrice) * produto.stockQuantity;

  if (financeiroSensivelLiberado) {
    return {
      ...produto,
      isUnlimited: estoqueIlimitado,
      valorEstoqueVenda,
      valorEstoqueCusto,
    };
  }

  return {
    ...produto,
    isUnlimited: estoqueIlimitado,
    costPrice: null,
    taxPercent: null,
    valorEstoqueVenda,
    valorEstoqueCusto: null,
  };
}

function calcularNovoEstoque({
  tipo,
  estoqueAtual,
  quantidade,
}: {
  tipo: StockMovementType;
  estoqueAtual: number;
  quantidade: number;
}) {
  if (tipo === StockMovementType.ENTRADA) {
    return estoqueAtual + quantidade;
  }

  if (tipo === StockMovementType.SAIDA) {
    return estoqueAtual - quantidade;
  }

  return quantidade;
}

export async function GET(_request: Request, context: RouteContext) {
  try {
    const bloqueioModuloProdutos = await exigirModuloProdutosAtivoApi();

    if (bloqueioModuloProdutos) {
      return bloqueioModuloProdutos;
    }

    const acesso = await exigirPermissaoApi(["estoque.ver", "produtos.ver"]);

    if (!acesso.ok) {
      return acesso.response;
    }

    const financeiroSensivelLiberado =
      usuarioPodeVerDadosFinanceirosSensiveis(acesso.usuario);

    const { id } = await context.params;

    const produto = await prisma.product.findUnique({
      where: {
        id,
      },
      include: {
        stockMovements: {
          orderBy: {
            createdAt: "desc",
          },
          take: 80,
        },
      },
    });

    if (!produto) {
      return NextResponse.json(
        { message: "Produto não encontrado." },
        { status: 404 }
      );
    }

    return NextResponse.json({
      produto: protegerProduto(produto, financeiroSensivelLiberado),
      movimentos: produto.stockMovements,
    });
  } catch (error) {
    console.error("Erro ao buscar estoque do produto:", error);

    return NextResponse.json(
      { message: "Erro ao buscar estoque do produto." },
      { status: 500 }
    );
  }
}

export async function POST(request: Request, context: RouteContext) {
  try {
    const bloqueioModuloProdutos = await exigirModuloProdutosAtivoApi();

    if (bloqueioModuloProdutos) {
      return bloqueioModuloProdutos;
    }

    const acesso = await exigirPermissaoApi("estoque.ajustar");

    if (!acesso.ok) {
      return acesso.response;
    }

    const financeiroSensivelLiberado =
      usuarioPodeVerDadosFinanceirosSensiveis(acesso.usuario);

    const { id } = await context.params;
    const body = await request.json().catch(() => ({}));

    const tipo = tipoMovimento(body.type);
    const quantidade = inteiro(body.quantity);
    const motivo = texto(body.reason);
    const userName = nomeOperador(acesso.usuario);

    if (!tipo) {
      return NextResponse.json(
        { message: "Tipo de movimentação inválido." },
        { status: 400 }
      );
    }

    if (quantidade <= 0 && tipo !== StockMovementType.AJUSTE) {
      return NextResponse.json(
        { message: "Informe uma quantidade maior que zero." },
        { status: 400 }
      );
    }

    if (tipo === StockMovementType.AJUSTE && quantidade < 0) {
      return NextResponse.json(
        { message: "A quantidade ajustada não pode ser negativa." },
        { status: 400 }
      );
    }

    if (!motivo) {
      return NextResponse.json(
        { message: "Informe o motivo da movimentação." },
        { status: 400 }
      );
    }

    const resultado = await prisma.$transaction(async (tx) => {
      const produto = await tx.product.findUnique({
        where: {
          id,
        },
      });

      if (!produto) {
        throw new Error("PRODUTO_NAO_ENCONTRADO");
      }

      if (produto.stockQuantity === null) {
        throw new Error("UNLIMITED_STOCK_REJECTS_MOVEMENT");
      }

      const estoqueAtual = produto.stockQuantity;
      const novoEstoque = calcularNovoEstoque({
        tipo,
        estoqueAtual,
        quantidade,
      });

      if (novoEstoque < 0) {
        throw new Error("ESTOQUE_INSUFICIENTE");
      }

      const produtoAtualizado = await tx.product.update({
        where: {
          id,
        },
        data: {
          stockQuantity: novoEstoque,
        },
      });

      const movimento = await tx.stockMovement.create({
        data: {
          productId: produto.id,
          type: tipo,
          quantity:
            tipo === StockMovementType.SAIDA
              ? -quantidade
              : tipo === StockMovementType.AJUSTE
                ? novoEstoque - estoqueAtual
                : quantidade,
          previousStock: estoqueAtual,
          newStock: novoEstoque,
          reason: `${motivo} | Operador: ${userName}`,
          userName,
        },
      });

      return {
        produto: produtoAtualizado,
        movimento,
      };
    });

    return NextResponse.json({
      message: "Estoque atualizado com sucesso.",
      produto: protegerProduto(
        resultado.produto,
        financeiroSensivelLiberado
      ),
      movimento: resultado.movimento,
    });
  } catch (error) {
    if (error instanceof Error) {
      if (error.message === "PRODUTO_NAO_ENCONTRADO") {
        return NextResponse.json(
          { message: "Produto não encontrado." },
          { status: 404 }
        );
      }

      if (error.message === "ESTOQUE_INSUFICIENTE") {
        return NextResponse.json(
          { message: "Estoque insuficiente para saída." },
          { status: 400 }
        );
      }

      if (error.message === "UNLIMITED_STOCK_REJECTS_MOVEMENT") {
        return NextResponse.json(
          {
            code: "UNLIMITED_STOCK_REJECTS_MOVEMENT",
            message:
              "Estoque ilimitado não aceita movimentação física. Converta o produto para estoque controlado antes de movimentar.",
          },
          { status: 409 }
        );
      }
    }

    console.error("Erro ao ajustar estoque:", error);

    return NextResponse.json(
      { message: "Erro ao ajustar estoque." },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { exigirModuloProdutosAtivoApi } from "@/lib/moduloProdutos";
import { exigirPermissaoApi } from "@/lib/permissaoApi";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{
    id: string;
  }>;
};

function numero(valor: unknown) {
  const n = Number(valor ?? 0);
  return Number.isFinite(n) ? n : 0;
}

function texto(valor: unknown) {
  return String(valor || "").trim();
}

export async function DELETE(request: Request, context: RouteContext) {
  try {
    const bloqueioModuloProdutos = await exigirModuloProdutosAtivoApi();

    if (bloqueioModuloProdutos) {
      return bloqueioModuloProdutos;
    }

    const acesso = await exigirPermissaoApi("produtos.excluir");

    if (!acesso.ok) {
      return acesso.response;
    }

    const { id } = await context.params;
    const body = await request.json().catch(() => ({}));
    const confirmacao = texto(body.confirmacao).toUpperCase();

    if (confirmacao !== "EXCLUIR") {
      return NextResponse.json(
        {
          message:
            "Confirmação inválida. Digite EXCLUIR para remover definitivamente.",
        },
        { status: 400 }
      );
    }

    const resultado = await prisma.$transaction(async (tx) => {
      const produto = await tx.product.findUnique({
        where: {
          id,
        },
        include: {
          saleItems: {
            select: {
              id: true,
              saleId: true,
            },
          },
        },
      });

      if (!produto) {
        throw new Error("PRODUTO_NAO_ENCONTRADO");
      }

      const saleIds = Array.from(
        new Set(produto.saleItems.map((item) => item.saleId).filter(Boolean))
      );

      const itensRemovidos = await tx.productSaleItem.deleteMany({
        where: {
          productId: id,
        },
      });

      let vendasApagadas = 0;
      let vendasRecalculadas = 0;

      for (const saleId of saleIds) {
        const itensRestantes = await tx.productSaleItem.findMany({
          where: {
            saleId,
          },
        });

        if (itensRestantes.length === 0) {
          await tx.productSale.delete({
            where: {
              id: saleId,
            },
          });

          vendasApagadas += 1;
          continue;
        }

        const subtotalAmount = itensRestantes.reduce(
          (total, item) => total + numero(item.subtotalAmount),
          0
        );

        const taxAmount = itensRestantes.reduce(
          (total, item) => total + numero(item.taxAmount),
          0
        );

        const costAmount = itensRestantes.reduce(
          (total, item) => total + numero(item.costAmount),
          0
        );

        const totalItens = itensRestantes.reduce(
          (total, item) => total + numero(item.totalAmount),
          0
        );

        const vendaAtual = await tx.productSale.findUnique({
          where: {
            id: saleId,
          },
        });

        const discount = numero(vendaAtual?.discount);
        const totalAmount = Math.max(0, totalItens - discount);
        const profitAmount = totalAmount - costAmount - taxAmount;

        await tx.productSale.update({
          where: {
            id: saleId,
          },
          data: {
            subtotalAmount,
            taxAmount,
            costAmount,
            profitAmount,
            totalAmount,
          },
        });

        vendasRecalculadas += 1;
      }

      await tx.product.delete({
        where: {
          id,
        },
      });

      return {
        produto: {
          id: produto.id,
          name: produto.name,
        },
        itensRemovidos: itensRemovidos.count,
        vendasApagadas,
        vendasRecalculadas,
      };
    });

    return NextResponse.json({
      message: "Produto excluído definitivamente.",
      ...resultado,
    });
  } catch (error) {
    if (error instanceof Error && error.message === "PRODUTO_NAO_ENCONTRADO") {
      return NextResponse.json(
        { message: "Produto não encontrado." },
        { status: 404 }
      );
    }

    console.error("Erro ao excluir produto definitivamente:", error);

    return NextResponse.json(
      { message: "Erro ao excluir produto definitivamente." },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { exigirModuloProdutosAtivoApi } from "@/lib/moduloProdutos";
import {
  exigirPermissaoApi,
  usuarioPodeVerDadosFinanceirosSensiveis,
} from "@/lib/permissaoApi";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{
    id: string;
  }>;
};

function texto(valor: unknown) {
  return String(valor || "").trim();
}

function textoOuNulo(valor: unknown) {
  const limpo = texto(valor);
  return limpo || null;
}

function numero(valor: unknown, fallback = 0) {
  const n = Number(valor);

  if (!Number.isFinite(n) || n < 0) return fallback;

  return n;
}

function inteiro(valor: unknown, fallback = 0) {
  return Math.max(0, Math.floor(numero(valor, fallback)));
}

function calcularProduto(produto: {
  salePrice: unknown;
  costPrice: unknown;
  taxPercent: unknown;
  stockQuantity: number | null;
  minStock: number;
}) {
  const salePrice = numero(produto.salePrice);
  const costPrice = numero(produto.costPrice);
  const taxPercent = numero(produto.taxPercent);

  const taxAmount = salePrice * (taxPercent / 100);
  const profitAmount = salePrice - costPrice - taxAmount;
  const marginPercent = salePrice > 0 ? (profitAmount / salePrice) * 100 : 0;

  const unlimitedStock = produto.stockQuantity === null;
  const lowStock =
    !unlimitedStock &&
    produto.minStock > 0 &&
    produto.stockQuantity !== null &&
    produto.stockQuantity < produto.minStock;

  return {
    salePrice,
    costPrice,
    taxPercent,
    taxAmount,
    profitAmount,
    marginPercent,
    unlimitedStock,
    lowStock,
  };
}

function formatarProduto(produto: any) {
  const calculos = calcularProduto(produto);

  return {
    ...produto,

    salePrice: calculos.salePrice,
    costPrice: calculos.costPrice,
    taxPercent: calculos.taxPercent,

    taxAmount: calculos.taxAmount,
    profitAmount: calculos.profitAmount,
    marginPercent: calculos.marginPercent,

    unlimitedStock: calculos.unlimitedStock,
    isUnlimited: calculos.unlimitedStock,
    lowStock: calculos.lowStock,
  };
}

function protegerProduto(produto: any, financeiroSensivelLiberado: boolean) {
  const formatado = formatarProduto(produto);
  const valorEstoqueVenda = formatado.unlimitedStock
    ? null
    : numero(formatado.salePrice) * formatado.stockQuantity;
  const valorEstoqueCusto = formatado.unlimitedStock
    ? null
    : numero(formatado.costPrice) * formatado.stockQuantity;

  if (financeiroSensivelLiberado) {
    return {
      ...formatado,
      valorEstoqueVenda,
      valorEstoqueCusto,
    };
  }

  return {
    ...formatado,

    costPrice: null,
    taxPercent: null,
    taxAmount: null,
    profitAmount: null,
    marginPercent: null,
    valorEstoqueVenda,
    valorEstoqueCusto: null,

    saleItems: Array.isArray(formatado.saleItems)
      ? formatado.saleItems.map((item: any) => ({
          ...item,

          unitCost: null,
          taxPercent: null,
          taxAmount: null,
          costAmount: null,
          profitAmount: null,

          sale: item.sale
            ? {
                ...item.sale,
                totalAmount: item.sale.totalAmount,
              }
            : null,
        }))
      : [],
  };
}

