    if (!body || typeof body !== "object") {
      return NextResponse.json(
        { message: "Dados inválidos para atualizar produto." },
        { status: 400 }
      );
    }

    const produtoAtual = await prisma.product.findUnique({
      where: {
        id,
      },
      select: {
        id: true,
        costPrice: true,
        taxPercent: true,
        stockQuantity: true,
      },
    });

    if (!produtoAtual) {
      return NextResponse.json(
        { message: "Produto não encontrado." },
        { status: 404 }
      );
    }

    const name = texto(body.name);
    const sku = textoOuNulo(body.sku);
    const category = textoOuNulo(body.category);
    const description = textoOuNulo(body.description);
    const imageUrl = textoOuNulo(body.imageUrl);

    const salePrice = numero(body.salePrice);

    const costPrice = financeiroSensivelLiberado
      ? numero(body.costPrice)
      : numero(produtoAtual.costPrice);

    const taxPercent = financeiroSensivelLiberado
      ? numero(body.taxPercent)
      : numero(produtoAtual.taxPercent);

    const unlimitedStock = body.unlimitedStock;
    const temQuantidade = Object.prototype.hasOwnProperty.call(
      body,
      "stockQuantity"
    );

    if (typeof unlimitedStock !== "boolean") {
      return NextResponse.json(
        {
          code: "VALIDATION_ERROR",
          message: "Informe explicitamente se o estoque é ilimitado.",
        },
        { status: 422 }
      );
    }

    if (unlimitedStock && temQuantidade && body.stockQuantity !== undefined) {
      return NextResponse.json(
        {
          code: "VALIDATION_ERROR",
          message: "Produto ilimitado não pode receber quantidade de estoque.",
        },
        { status: 422 }
      );
    }

    if (
      unlimitedStock &&
      produtoAtual.stockQuantity !== null &&
      body.confirmStockModeChange !== true
    ) {
      return NextResponse.json(
        {
          code: "VALIDATION_ERROR",
          message: "Confirme explicitamente a mudança para estoque ilimitado.",
        },
        { status: 422 }
      );
    }

    const quantidadeInformada = Number(body.stockQuantity);

    if (
      !unlimitedStock &&
      (!temQuantidade ||
        !Number.isInteger(quantidadeInformada) ||
        quantidadeInformada < 0)
    ) {
      return NextResponse.json(
        {
          code: "VALIDATION_ERROR",
          message: "Informe uma quantidade inteira maior ou igual a zero.",
        },
        { status: 422 }
      );
    }

    const stockQuantity = unlimitedStock ? null : quantidadeInformada;
    const minStock = inteiro(body.minStock);
    const isActive = body.isActive === false ? false : true;

    if (!name) {
      return NextResponse.json(
        { message: "Informe o nome do produto." },
        { status: 400 }
      );
    }

    if (salePrice <= 0) {
      return NextResponse.json(
        { message: "Informe o valor de venda do produto." },
        { status: 400 }
      );
    }

    if (taxPercent > 100) {
      return NextResponse.json(
        { message: "O imposto não pode ser maior que 100%." },
        { status: 400 }
      );
    }

    if (sku) {
      const skuExistente = await prisma.product.findFirst({
        where: {
          id: {
            not: id,
          },
          sku,
        },
        select: {
          id: true,
        },
      });

      if (skuExistente) {
        return NextResponse.json(
          { message: "Já existe outro produto com esse código/SKU." },
          { status: 400 }
        );
      }
    }

    const produto = await prisma.product.update({
      where: {
        id,
      },
      data: {
        name,
        sku,
        category,
        description,
        imageUrl,
        salePrice,
        costPrice,
        taxPercent,
        stockQuantity,
        minStock,
        isActive,
      },
    });

    return NextResponse.json({
      message:
        produtoAtual.stockQuantity === null !== (stockQuantity === null)
          ? "Produto atualizado com mudança explícita do modo de estoque."
          : "Produto atualizado com sucesso.",
      produto: protegerProduto(produto, financeiroSensivelLiberado),
    });
  } catch (error) {
    console.error("Erro ao atualizar produto:", error);

    return NextResponse.json(
      { message: "Erro ao atualizar produto." },
      { status: 500 }
    );
  }
}

export async function DELETE(_request: Request, context: RouteContext) {
  try {
    const bloqueioModuloProdutos = await exigirModuloProdutosAtivoApi();

    if (bloqueioModuloProdutos) {
      return bloqueioModuloProdutos;
    }

    const acesso = await exigirPermissaoApi("produtos.excluir");

    if (!acesso.ok) {
      return acesso.response;
    }

    const { id } = await context.params;

    const produto = await prisma.product.findUnique({
      where: {
        id,
      },
      select: {
        id: true,
        name: true,
        isActive: true,
      },
    });

    if (!produto) {
      return NextResponse.json(
        { message: "Produto não encontrado." },
        { status: 404 }
      );
    }

    await prisma.product.update({
      where: {
        id,
      },
      data: {
        isActive: false,
      },
      select: {
        id: true,
      },
    });

    return NextResponse.json({
      message: "Produto inativado com sucesso.",
    });
  } catch (error) {
    console.error("Erro ao excluir produto:", error);

    return NextResponse.json(
      { message: "Erro ao excluir produto." },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { ProductSaleStatus } from "@prisma/client";
import { prisma } from "@/lib/prisma";
import { exigirModuloProdutosAtivoApi } from "@/lib/moduloProdutos";
import {
  exigirPermissaoApi,
  usuarioPodeVerDadosFinanceirosSensiveis,
} from "@/lib/permissaoApi";
import {
  labelsDiasFuncionamento,
  lojaAbertaNaData,
  normalizarDiasFuncionamento,
  normalizarHora,
} from "@/lib/funcionamentoLoja";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const DIAS_SEMANA = [
  "Domingo",
  "Segunda-feira",
  "Terça-feira",
  "Quarta-feira",
  "Quinta-feira",
  "Sexta-feira",
  "Sábado",
];

function numero(valor: unknown) {
  const n = Number(valor ?? 0);
  return Number.isFinite(n) ? n : 0;
}

function inteiro(valor: unknown) {
  return Math.max(0, Math.floor(numero(valor)));
}

function texto(valor: unknown) {
  return String(valor || "").trim();
}

function dataInicioMesAtual() {
  const hoje = new Date();
  return new Date(hoje.getFullYear(), hoje.getMonth(), 1, 0, 0, 0, 0);
}

function dataFimMesAtual() {
  const hoje = new Date();
  return new Date(hoje.getFullYear(), hoje.getMonth() + 1, 0, 23, 59, 59, 999);
}

function criarDataLocalSegura(data: string) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(data);

  if (!match) return null;

  const ano = Number(match[1]);
  const mes = Number(match[2]);
  const dia = Number(match[3]);
  const d = new Date(ano, mes - 1, dia);

  if (
    d.getFullYear() !== ano ||
    d.getMonth() !== mes - 1 ||
    d.getDate() !== dia
  ) {
    return null;
  }

  return d;
}

function inicioDoDia(data: Date) {
  const d = new Date(data);
  d.setHours(0, 0, 0, 0);
  return d;
}

function fimDoDia(data: Date) {
  const d = new Date(data);
  d.setHours(23, 59, 59, 999);
  return d;
}


function formatarDataInput(data: Date) {
  const ano = data.getFullYear();
  const mes = String(data.getMonth() + 1).padStart(2, "0");
  const dia = String(data.getDate()).padStart(2, "0");

  return `${ano}-${mes}-${dia}`;
}

function criarDiasDoPeriodo(
  inicio: Date,
  fim: Date,
  diasFuncionamento: number[]
) {
  const dias: {
    data: string;
    label: string;
    vendas: number;
    itensVendidos: number;
    totalVendido: number;
    custoTotal: number;
    impostoTotal: number;
    lucroTotal: number;
  }[] = [];

  const atual = new Date(
    inicio.getFullYear(),
    inicio.getMonth(),
    inicio.getDate(),
    0,
    0,
    0,
    0
  );

  const limite = new Date(
    fim.getFullYear(),
    fim.getMonth(),
    fim.getDate(),
    0,
    0,
    0,
    0
  );

  while (atual <= limite) {
    if (lojaAbertaNaData(atual, diasFuncionamento)) {
      const data = formatarDataInput(atual);

      dias.push({
        data,
        label: atual.toLocaleDateString("pt-BR"),
        vendas: 0,
        itensVendidos: 0,
        totalVendido: 0,
        custoTotal: 0,
        impostoTotal: 0,
        lucroTotal: 0,
      });
    }

    atual.setDate(atual.getDate() + 1);
  }

  return dias;
}

async function buscarFuncionamentoLoja() {
  const configuracoes = await prisma.companySettings.findFirst({
    select: {
      businessDays: true,
      businessOpenTime: true,
      businessCloseTime: true,
    },
  });

  const diasAbertos = normalizarDiasFuncionamento(
    configuracoes?.businessDays
  );

  return {
    diasAbertos,
    labels: labelsDiasFuncionamento(diasAbertos),
    abertura: normalizarHora(configuracoes?.businessOpenTime, "08:00"),
    fechamento: normalizarHora(configuracoes?.businessCloseTime, "18:00"),
  };
}

export async function GET(request: Request) {
  try {
    const bloqueioModuloProdutos = await exigirModuloProdutosAtivoApi();

    if (bloqueioModuloProdutos) {
      return bloqueioModuloProdutos;
    }

    const acesso = await exigirPermissaoApi([
      "relatorios.ver",
      "relatorios.financeiro",
    ]);

    if (!acesso.ok) {
      return acesso.response;
    }
    const financeiroSensivelLiberado =
      usuarioPodeVerDadosFinanceirosSensiveis(acesso.usuario);

    const { searchParams } = new URL(request.url);

    const dataInicioParam = texto(searchParams.get("dataInicio"));
    const dataFimParam = texto(searchParams.get("dataFim"));

    const inicioInformado = dataInicioParam
      ? criarDataLocalSegura(dataInicioParam)
      : null;

    const fimInformado = dataFimParam ? criarDataLocalSegura(dataFimParam) : null;

    if (dataInicioParam && !inicioInformado) {
      return NextResponse.json(
        { message: "Data inicial inválida." },
        { status: 400 }
      );
    }

    if (dataFimParam && !fimInformado) {
      return NextResponse.json(
        { message: "Data final inválida." },
        { status: 400 }
      );
    }

    const inicio = inicioInformado
      ? inicioDoDia(inicioInformado)
      : dataInicioMesAtual();

    const fim = fimInformado ? fimDoDia(fimInformado) : dataFimMesAtual();

    if (fim < inicio) {
      return NextResponse.json(
        { message: "A data final não pode ser menor que a data inicial." },
        { status: 400 }
      );
    }

    const funcionamento = await buscarFuncionamentoLoja();

    const vendas = await prisma.productSale.findMany({
      where: {
        status: ProductSaleStatus.CONCLUIDA,
        soldAt: {
          gte: inicio,
          lte: fim,
        },
      },
      orderBy: {
        soldAt: "desc",
      },
      include: {
        items: true,
      },
    });

    const produtosAtivos = await prisma.product.findMany({
      where: {
        isActive: true,
      },
      select: {
        id: true,
        name: true,
        category: true,
        salePrice: true,
        costPrice: true,
        taxPercent: true,
        stockQuantity: true,
      },
      orderBy: {
        name: "asc",
      },
    });

    const diasSemanaTodos = DIAS_SEMANA.map((dia, index) => ({
      diaSemana: index,
      label: dia,
      lojaAberta: funcionamento.diasAbertos.includes(index),
      vendas: 0,
      itensVendidos: 0,
      totalVendido: 0,
      custoTotal: 0,
      impostoTotal: 0,
      lucroTotal: 0,
    }));

    const diasPeriodo = criarDiasDoPeriodo(
      inicio,
      fim,
      funcionamento.diasAbertos
    );
    const diasPeriodoMap = new Map(diasPeriodo.map((dia) => [dia.data, dia]));

    const produtosMap = new Map<
      string,
      {
        productId: string;
        productName: string;
        category: string | null;
        quantity: number;
        totalVendido: number;
        custoTotal: number;
        impostoTotal: number;
        lucroTotal: number;
      }
    >();

    let totalVendido = 0;
    let custoTotal = 0;
    let impostoTotal = 0;
    let lucroTotal = 0;
    let itensVendidos = 0;

    for (const venda of vendas) {
      const totalVenda = numero(venda.totalAmount);
      const custoVenda = numero(venda.costAmount);
      const impostoVenda = numero(venda.taxAmount);
      const lucroVenda = numero(venda.profitAmount);

      totalVendido += totalVenda;
      custoTotal += custoVenda;
      impostoTotal += impostoVenda;
      lucroTotal += lucroVenda;

      const quantidadeItensVenda = venda.items.reduce(
        (total, item) => total + inteiro(item.quantity),
        0
      );

      itensVendidos += quantidadeItensVenda;

      const dataVenda = new Date(venda.soldAt);
      const diaSemana = dataVenda.getDay();
      const dataKey = formatarDataInput(dataVenda);

      if (diasSemanaTodos[diaSemana]?.lojaAberta) {
        diasSemanaTodos[diaSemana].vendas += 1;
        diasSemanaTodos[diaSemana].itensVendidos += quantidadeItensVenda;
        diasSemanaTodos[diaSemana].totalVendido += totalVenda;
        diasSemanaTodos[diaSemana].custoTotal += custoVenda;
        diasSemanaTodos[diaSemana].impostoTotal += impostoVenda;
        diasSemanaTodos[diaSemana].lucroTotal += lucroVenda;
      }

      const diaPeriodo = diasPeriodoMap.get(dataKey);

      if (diaPeriodo) {
        diaPeriodo.vendas += 1;
        diaPeriodo.itensVendidos += quantidadeItensVenda;
        diaPeriodo.totalVendido += totalVenda;
        diaPeriodo.custoTotal += custoVenda;
        diaPeriodo.impostoTotal += impostoVenda;
        diaPeriodo.lucroTotal += lucroVenda;
      }

      for (const item of venda.items) {
        const productId = item.productId || `manual:${item.productName}`;
        const atual =
          produtosMap.get(productId) ||
          {
            productId,
            productName: item.productName,
            category: null,
            quantity: 0,
            totalVendido: 0,
            custoTotal: 0,
            impostoTotal: 0,
            lucroTotal: 0,
          };

        atual.quantity += inteiro(item.quantity);
        atual.totalVendido += numero(item.totalAmount);
        atual.custoTotal += numero(item.costAmount);
        atual.impostoTotal += numero(item.taxAmount);
        atual.lucroTotal += numero(item.profitAmount);

        produtosMap.set(productId, atual);
      }
    }

    const produtosVendidos = Array.from(produtosMap.values());

    const maisVendidos = [...produtosVendidos]
      .sort((a, b) => b.quantity - a.quantity)
      .slice(0, 5);

    const menosVendidos = [...produtosVendidos]
      .sort((a, b) => a.quantity - b.quantity)
      .slice(0, 5);

    const maiorLucro = [...produtosVendidos]
      .sort((a, b) => b.lucroTotal - a.lucroTotal)
      .slice(0, 5);

    const menorLucro = [...produtosVendidos]
      .sort((a, b) => a.lucroTotal - b.lucroTotal)
      .slice(0, 5);

    const idsVendidos = new Set(
      produtosVendidos
        .filter((produto) => !produto.productId.startsWith("manual:"))
        .map((produto) => produto.productId)
    );

    const produtosSemVenda = produtosAtivos
      .filter((produto) => !idsVendidos.has(produto.id))
      .slice(0, 20)
      .map((produto) => ({
        productId: produto.id,
        productName: produto.name,
        category: produto.category,
        salePrice: numero(produto.salePrice),
        costPrice: numero(produto.costPrice),
        taxPercent: numero(produto.taxPercent),
      }));

    const diasSemana = diasSemanaTodos.filter((dia) => dia.lojaAberta);

    const diaSemanaMaisForte = [...diasSemana].sort(
      (a, b) => b.totalVendido - a.totalVendido
    )[0] || null;

    const diaSemanaMaisFraco = [...diasSemana].sort(
      (a, b) => a.totalVendido - b.totalVendido
    )[0] || null;

    const diasComVenda = diasPeriodo.filter((dia) => dia.totalVendido > 0);

    const diaMesMaisForte =
      [...diasComVenda].sort((a, b) => b.totalVendido - a.totalVendido)[0] ||
      null;

    const diaMesMaisFraco =
      [...diasPeriodo].sort((a, b) => a.totalVendido - b.totalVendido)[0] ||
      null;
    const valorEstoqueVenda = produtosAtivos.reduce((total, produto) => {
      if (produto.stockQuantity === null) return total;
      return total + numero(produto.salePrice) * produto.stockQuantity;
    }, 0);
    const valorEstoqueCusto = financeiroSensivelLiberado
      ? produtosAtivos.reduce((total, produto) => {
          if (produto.stockQuantity === null) return total;
          return total + numero(produto.costPrice) * produto.stockQuantity;
        }, 0)
      : null;

    return NextResponse.json({
      financeiroSensivelLiberado,
      funcionamento,
      periodo: {
        dataInicio: formatarDataInput(inicio),
        dataFim: formatarDataInput(fim),
      },
      resumo: {
        vendas: vendas.length,
        itensVendidos,
        totalVendido,
        valorEstoqueVenda,
        valorEstoqueCusto,
        custoTotal: financeiroSensivelLiberado ? custoTotal : null,
        impostoTotal: financeiroSensivelLiberado ? impostoTotal : null,
        lucroTotal: financeiroSensivelLiberado ? lucroTotal : null,
        ticketMedio: vendas.length > 0 ? totalVendido / vendas.length : 0,
        margemMedia: financeiroSensivelLiberado
          ? totalVendido > 0
            ? (lucroTotal / totalVendido) * 100
            : 0
          : null,
      },
      diagnostico: {
        diaSemanaMaisForte,
        diaSemanaMaisFraco,
        diaMesMaisForte,
        diaMesMaisFraco,
      },
      diasSemana: diasSemana.map((dia) => ({
        ...dia,
        custoTotal: financeiroSensivelLiberado ? dia.custoTotal : null,
        impostoTotal: financeiroSensivelLiberado ? dia.impostoTotal : null,
        lucroTotal: financeiroSensivelLiberado ? dia.lucroTotal : null,
      })),
      diasPeriodo: diasPeriodo.map((dia) => ({
        ...dia,
        custoTotal: financeiroSensivelLiberado ? dia.custoTotal : null,
        impostoTotal: financeiroSensivelLiberado ? dia.impostoTotal : null,
        lucroTotal: financeiroSensivelLiberado ? dia.lucroTotal : null,
      })),
      rankings: {
        maisVendidos: maisVendidos.map((produto) => ({
          ...produto,
          custoTotal: financeiroSensivelLiberado ? produto.custoTotal : null,
          impostoTotal: financeiroSensivelLiberado
            ? produto.impostoTotal
            : null,
          lucroTotal: financeiroSensivelLiberado ? produto.lucroTotal : null,
        })),
        menosVendidos: menosVendidos.map((produto) => ({
          ...produto,
          custoTotal: financeiroSensivelLiberado ? produto.custoTotal : null,
          impostoTotal: financeiroSensivelLiberado
            ? produto.impostoTotal
            : null,
          lucroTotal: financeiroSensivelLiberado ? produto.lucroTotal : null,
        })),
        maiorLucro: financeiroSensivelLiberado ? maiorLucro : [],
        menorLucro: financeiroSensivelLiberado ? menorLucro : [],
        produtosSemVenda: produtosSemVenda.map((produto) => ({
          ...produto,
          costPrice: financeiroSensivelLiberado ? produto.costPrice : null,
          taxPercent: financeiroSensivelLiberado ? produto.taxPercent : null,
        })),
      },
    });
  } catch (error) {
    console.error("Erro ao gerar relatório de produtos:", error);

    return NextResponse.json(
      { message: "Erro ao gerar relatório de produtos." },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { type Prisma, ProductSaleStatus } from "@prisma/client";
import { prisma } from "@/lib/prisma";
import { exigirModuloProdutosAtivoApi } from "@/lib/moduloProdutos";
import {
  exigirPermissaoApi,
  usuarioPodeVerDadosFinanceirosSensiveis,
} from "@/lib/permissaoApi";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

function texto(valor: unknown) {
  return String(valor || "").trim();
}

function textoOuNulo(valor: unknown) {
  const limpo = texto(valor);
  return limpo || null;
}

function numero(valor: unknown, fallback = 0) {
  const n = Number(valor);

  if (!Number.isFinite(n) || n < 0) return fallback;

  return n;
}

function inteiro(valor: unknown, fallback = 0) {
  return Math.max(0, Math.floor(numero(valor, fallback)));
}

function calcularProduto(produto: {
  salePrice: unknown;
  costPrice: unknown;
  taxPercent: unknown;
  stockQuantity: number | null;
  minStock: number;
}) {
  const salePrice = numero(produto.salePrice);
  const costPrice = numero(produto.costPrice);
  const taxPercent = numero(produto.taxPercent);

  const taxAmount = salePrice * (taxPercent / 100);
  const profitAmount = salePrice - costPrice - taxAmount;
  const marginPercent = salePrice > 0 ? (profitAmount / salePrice) * 100 : 0;

  const unlimitedStock = produto.stockQuantity === null;
  const lowStock =
    !unlimitedStock &&
    produto.minStock > 0 &&
    produto.stockQuantity !== null &&
    produto.stockQuantity < produto.minStock;

  return {
    salePrice,
    costPrice,
    taxPercent,
    taxAmount,
    profitAmount,
    marginPercent,
    unlimitedStock,
    lowStock,
  };
}

function formatarProduto(produto: any, soldQuantity = 0) {
  const calculos = calcularProduto(produto);

  return {
    ...produto,

    salePrice: calculos.salePrice,
    costPrice: calculos.costPrice,
    taxPercent: calculos.taxPercent,

    taxAmount: calculos.taxAmount,
    profitAmount: calculos.profitAmount,
    marginPercent: calculos.marginPercent,

    unlimitedStock: calculos.unlimitedStock,
    isUnlimited: calculos.unlimitedStock,
    lowStock: calculos.lowStock,

    soldQuantity,
  };
}

function protegerProduto(produto: any, financeiroSensivelLiberado: boolean) {
  const valorEstoqueVenda = produto.unlimitedStock
    ? null
    : numero(produto.salePrice) * produto.stockQuantity;
  const valorEstoqueCusto = produto.unlimitedStock
    ? null
    : numero(produto.costPrice) * produto.stockQuantity;

  if (financeiroSensivelLiberado) {
    return {
      ...produto,
      valorEstoqueVenda,
      valorEstoqueCusto,
    };
  }

  const {
    costPrice: _costPrice,
    taxPercent: _taxPercent,
    taxAmount: _taxAmount,
    profitAmount: _profitAmount,
    marginPercent: _marginPercent,
    ...seguro
  } = produto;

  return {
    ...seguro,
    costPrice: null,
    taxPercent: null,
    taxAmount: null,
    profitAmount: null,
    marginPercent: null,
    valorEstoqueVenda,
    valorEstoqueCusto: null,
  };
}

async function mapaVendidos() {
  const vendidos = await prisma.productSaleItem.groupBy({
    by: ["productId"],
    where: {
      productId: {
        not: null,
      },
      sale: {
        status: ProductSaleStatus.CONCLUIDA,
      },
    },
    _sum: {
      quantity: true,
    },
  });

  return new Map(
    vendidos.map((item) => [item.productId || "", item._sum.quantity || 0])
  );
}

async function montarRanking(financeiroSensivelLiberado: boolean) {
  const vendidosMap = await mapaVendidos();

  const produtos = await prisma.product.findMany({
    where: {
      isActive: true,
    },
    orderBy: {
      name: "asc",
    },
  });

  const produtosComVenda = produtos.map((produto) =>
    formatarProduto(produto, vendidosMap.get(produto.id) || 0)
  );

  const maisVendidos = [...produtosComVenda]
    .filter((produto) => produto.soldQuantity > 0)
    .sort((a, b) => b.soldQuantity - a.soldQuantity)
    .slice(0, 5)
    .map((produto) => protegerProduto(produto, financeiroSensivelLiberado));

  const menosVendidos = [...produtosComVenda]
    .sort((a, b) => a.soldQuantity - b.soldQuantity)
    .slice(0, 5)
    .map((produto) => protegerProduto(produto, financeiroSensivelLiberado));

  return {
    maisVendidos,
    menosVendidos,
  };
}

export async function GET(request: Request) {
  try {
    const bloqueioModuloProdutos = await exigirModuloProdutosAtivoApi();

    if (bloqueioModuloProdutos) {
      return bloqueioModuloProdutos;
    }

    const acesso = await exigirPermissaoApi([
      "produtos.ver",
      "estoque.ver",
      "vendas.ver",
    ]);

    if (!acesso.ok) {
      return acesso.response;
    }

    const financeiroSensivelLiberado =
      usuarioPodeVerDadosFinanceirosSensiveis(acesso.usuario);

    const { searchParams } = new URL(request.url);

    const busca = texto(searchParams.get("busca"));
    const status = texto(searchParams.get("status") || "ATIVOS").toUpperCase();
    const estoque = texto(searchParams.get("estoque") || "TODOS").toUpperCase();
    const categoria = texto(searchParams.get("categoria"));

    const where: Prisma.ProductWhereInput = {};

    if (busca) {
      where.OR = [
        {
          name: {
            contains: busca,
          },
        },
        {
          sku: {
            contains: busca,
          },
        },
        {
          category: {
            contains: busca,
          },
        },
        {
          description: {
            contains: busca,
          },
        },
      ];
    }

    if (categoria) {
      where.category = {
        contains: categoria,
      };
    }

    if (status === "ATIVOS") {
      where.isActive = true;
    }

    if (status === "INATIVOS") {
      where.isActive = false;
    }

    if (estoque === "ILIMITADO") {
      where.stockQuantity = null;
    }

    if (estoque === "SEM_ESTOQUE") {
      where.stockQuantity = 0;
    }

    if (estoque === "CONTROLADO") {
      where.stockQuantity = { not: null };
    }

    const vendidosMap = await mapaVendidos();

    const produtosBanco = await prisma.product.findMany({
      where,
      orderBy: {
        name: "asc",
      },
      take: 500,
    });

    let produtosCalculados = produtosBanco.map((produto) =>
      formatarProduto(produto, vendidosMap.get(produto.id) || 0)
    );

    if (estoque === "BAIXO") {
      produtosCalculados = produtosCalculados.filter(
        (produto) => produto.lowStock
      );
    }

    if (estoque === "ILIMITADO") {
      produtosCalculados = produtosCalculados.filter(
        (produto) => produto.unlimitedStock
      );
    }

    if (estoque === "CONTROLADO") {
      produtosCalculados = produtosCalculados.filter(
        (produto) => !produto.unlimitedStock
      );
    }

    if (estoque === "SEM_ESTOQUE") {
      produtosCalculados = produtosCalculados.filter(
        (produto) => produto.stockQuantity === 0
      );
    }

    const produtosAtivos = produtosCalculados.filter(
      (produto) => produto.isActive
    );

    const estoqueBaixo = produtosAtivos.filter((produto) => produto.lowStock);

    const estoqueIlimitado = produtosAtivos.filter(
      (produto) => produto.unlimitedStock
    );

    const semEstoque = produtosAtivos.filter(
      (produto) => produto.stockQuantity === 0
    );

    const valorEstoqueVenda = produtosAtivos.reduce((total, produto) => {
      if (produto.unlimitedStock) return total;
      return total + produto.salePrice * produto.stockQuantity;
    }, 0);

    const valorEstoqueCusto = financeiroSensivelLiberado
      ? produtosAtivos.reduce((total, produto) => {
          if (produto.unlimitedStock) return total;
          return total + produto.costPrice * produto.stockQuantity;
        }, 0)
      : null;

    const lucroPotencial = financeiroSensivelLiberado
      ? produtosAtivos.reduce((total, produto) => {
          if (produto.unlimitedStock) return total;
          return total + produto.profitAmount * produto.stockQuantity;
        }, 0)
      : null;

    const ranking = await montarRanking(financeiroSensivelLiberado);

    return NextResponse.json({
      resumo: {
        total: produtosCalculados.length,
        ativos: produtosAtivos.length,
        inativos: produtosCalculados.filter((produto) => !produto.isActive)
          .length,
        estoqueBaixo: estoqueBaixo.length,
        estoqueIlimitado: estoqueIlimitado.length,
        semEstoque: semEstoque.length,
        valorEstoque: valorEstoqueVenda,
        valorEstoqueVenda,
        valorEstoqueCusto,
        lucroPotencial,
      },
      produtos: produtosCalculados.map((produto) =>
        protegerProduto(produto, financeiroSensivelLiberado)
      ),
      maisVendidos: ranking.maisVendidos,
      menosVendidos: ranking.menosVendidos,
    });
  } catch (error) {
    console.error("Erro ao listar produtos:", error);

    return NextResponse.json(
      { message: "Erro ao listar produtos." },
      { status: 500 }
    );
  }
}

export async function POST(request: Request) {
  try {
    const bloqueioModuloProdutos = await exigirModuloProdutosAtivoApi();

    if (bloqueioModuloProdutos) {
      return bloqueioModuloProdutos;
    }

    const acesso = await exigirPermissaoApi("produtos.criar");

    if (!acesso.ok) {
      return acesso.response;
    }

    const financeiroSensivelLiberado =
      usuarioPodeVerDadosFinanceirosSensiveis(acesso.usuario);

    const body = (await request.json().catch(() => null)) as Record<
      string,
      unknown
    > | null;

    if (!body || typeof body !== "object") {
      return NextResponse.json(
        { message: "Dados inválidos para cadastrar produto." },
        { status: 400 }
      );
    }

    const name = texto(body.name);
    const sku = textoOuNulo(body.sku);
    const category = textoOuNulo(body.category);
    const description = textoOuNulo(body.description);
    const imageUrl = textoOuNulo(body.imageUrl);

    const salePrice = numero(body.salePrice);
    const costPrice = financeiroSensivelLiberado ? numero(body.costPrice) : 0;
    const taxPercent = financeiroSensivelLiberado
      ? numero(body.taxPercent)
      : 0;

    const unlimitedStock = body.unlimitedStock;
    const temQuantidade = Object.prototype.hasOwnProperty.call(
      body,
      "stockQuantity"
    );

    if (typeof unlimitedStock !== "boolean") {
      return NextResponse.json(
        {
          code: "VALIDATION_ERROR",
          message: "Informe explicitamente se o estoque é ilimitado.",
        },
        { status: 422 }
      );
    }

    if (unlimitedStock && temQuantidade && body.stockQuantity !== undefined) {
      return NextResponse.json(
        {
          code: "VALIDATION_ERROR",
          message: "Produto ilimitado não pode receber quantidade de estoque.",
        },
        { status: 422 }
      );
    }

    const quantidadeInformada = Number(body.stockQuantity);

    if (
      !unlimitedStock &&
      (!temQuantidade ||
        !Number.isInteger(quantidadeInformada) ||
        quantidadeInformada < 0)
    ) {
      return NextResponse.json(
        {
          code: "VALIDATION_ERROR",
          message: "Informe uma quantidade inteira maior ou igual a zero.",
        },
        { status: 422 }
      );
    }

    const stockQuantity = unlimitedStock ? null : quantidadeInformada;
    const minStock = inteiro(body.minStock);

    if (!name) {
      return NextResponse.json(
        { message: "Informe o nome do produto." },
        { status: 400 }
      );
    }

    if (salePrice <= 0) {
      return NextResponse.json(
        { message: "Informe o valor de venda do produto." },
        { status: 400 }
      );
    }

    if (taxPercent > 100) {
      return NextResponse.json(
        { message: "O imposto não pode ser maior que 100%." },
        { status: 400 }
      );
    }

    if (sku) {
      const skuExistente = await prisma.product.findFirst({
        where: {
          sku,
        },
        select: {
          id: true,
        },
      });

      if (skuExistente) {
        return NextResponse.json(
          { message: "Já existe um produto com esse código/SKU." },
          { status: 400 }
        );
      }
    }

    const produto = await prisma.product.create({
      data: {
        name,
        sku,
        category,
        description,
        imageUrl,
        salePrice,
        costPrice,
        taxPercent,
        stockQuantity,
        minStock,
        isActive: true,
      },
    });

    return NextResponse.json(
      {
        message: "Produto cadastrado com sucesso.",
        produto: protegerProduto(
          formatarProduto(produto),
          financeiroSensivelLiberado
        ),
      },
      { status: 201 }
    );
  } catch (error) {
    console.error("Erro ao cadastrar produto:", error);

    return NextResponse.json(
      { message: "Erro ao cadastrar produto." },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { readFile } from "fs/promises";
import path from "path";
import { caminhoUploadPublico } from "@/lib/runtimeStorage";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{
    arquivo: string;
  }>;
};

function contentTypePorExtensao(nomeArquivo: string) {
  const ext = path.extname(nomeArquivo).toLowerCase();

  if (ext === ".png") return "image/png";
  if (ext === ".jpg" || ext === ".jpeg") return "image/jpeg";
  if (ext === ".webp") return "image/webp";

  return "application/octet-stream";
}

export async function GET(_request: Request, context: RouteContext) {
  try {
    const { arquivo } = await context.params;

    const nomeSeguro = path.basename(arquivo || "");

    if (!nomeSeguro) {
      return NextResponse.json(
        { message: "Imagem não informada." },
        { status: 400 }
      );
    }

    const filePath = caminhoUploadPublico("produtos", nomeSeguro);

    const buffer = await readFile(filePath);

    return new NextResponse(new Uint8Array(buffer), {
      status: 200,
      headers: {
        "Content-Type": contentTypePorExtensao(nomeSeguro),
        "Cache-Control": "no-store, no-cache, must-revalidate",
      },
    });
  } catch {
    return NextResponse.json(
      { message: "Imagem não encontrada." },
      { status: 404 }
    );
  }
}

import { caminhoPublicoRuntime, caminhoUploadPublico } from "@/lib/runtimeStorage";
import { NextResponse } from "next/server";
import { mkdir, writeFile } from "fs/promises";
import path from "path";
import { randomUUID } from "crypto";
import { exigirModuloProdutosAtivoApi } from "@/lib/moduloProdutos";
import { exigirPermissaoApi } from "@/lib/permissaoApi";
export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const TIPOS_PERMITIDOS = ["image/png", "image/jpeg", "image/webp"];
const EXTENSOES: Record<string, string> = {
  "image/png": "png",
  "image/jpeg": "jpg",
  "image/webp": "webp",
};

function imagemValida(buffer: Buffer, type: string) {
  if (type === "image/png") {
    const assinatura = Buffer.from([
      0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a,
    ]);

    return buffer.length >= 8 && buffer.subarray(0, 8).equals(assinatura);
  }

  if (type === "image/jpeg") {
    return buffer.length >= 3 && buffer[0] === 0xff && buffer[1] === 0xd8;
  }

  if (type === "image/webp") {
    return (
      buffer.length >= 12 &&
      buffer.subarray(0, 4).toString("ascii") === "RIFF" &&
      buffer.subarray(8, 12).toString("ascii") === "WEBP"
    );
  }

  return false;
}

export async function POST(request: Request) {
  try {
    const bloqueioModuloProdutos = await exigirModuloProdutosAtivoApi();

    if (bloqueioModuloProdutos) {
      return bloqueioModuloProdutos;
    }

    const acesso = await exigirPermissaoApi([
      "produtos.criar",
      "produtos.editar",
    ]);

    if (!acesso.ok) {
      return acesso.response;
    }

    const formData = await request.formData().catch(() => null);
    const file = formData?.get("imagem");

    if (!(file instanceof File)) {
      return NextResponse.json(
        { message: "Nenhuma imagem enviada." },
        { status: 400 }
      );
    }

    if (!TIPOS_PERMITIDOS.includes(file.type)) {
      return NextResponse.json(
        { message: "Envie uma imagem PNG, JPG ou WEBP." },
        { status: 400 }
      );
    }

    const maxSize = 3 * 1024 * 1024;

    if (file.size > maxSize) {
      return NextResponse.json(
        { message: "A imagem deve ter no máximo 3MB." },
        { status: 400 }
      );
    }

    const bytes = await file.arrayBuffer();
    const buffer = Buffer.from(bytes);

    if (!imagemValida(buffer, file.type)) {
      return NextResponse.json(
        { message: "O arquivo enviado não parece ser uma imagem válida." },
        { status: 400 }
      );
    }

    const extensao = EXTENSOES[file.type] || "png";
    const nomeArquivo = `produto-${Date.now()}-${randomUUID()}.${extensao}`;

    const uploadDir = caminhoUploadPublico("produtos");
    const filePath = path.join(uploadDir, nomeArquivo);

    await mkdir(uploadDir, { recursive: true });
    await writeFile(filePath, buffer);

    return NextResponse.json({
      message: "Imagem enviada com sucesso.",
      imageUrl: `/api/uploads/produtos/${nomeArquivo}`,
    });
  } catch (error) {
    console.error("Erro ao enviar imagem do produto:", error);

    return NextResponse.json(
      { message: "Erro ao enviar imagem do produto." },
      { status: 500 }
    );
  }
}

import { NextRequest } from "next/server";
import PDFDocument from "pdfkit";
import fs from "fs";
import path from "path";
import { caminhoUploadPublico } from "@/lib/runtimeStorage";
import {
  exigirPermissaoApi,
  usuarioPodeVerDadosFinanceirosSensiveis,
} from "@/lib/permissaoApi";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type EmpresaConfig = {
  nomeEmpresa?: string;
  companyName?: string;
  nomeFantasia?: string;
  cnpj?: string;
  documento?: string;
  endereco?: string;
  address?: string;
  telefone?: string;
  phone?: string;
  whatsapp?: string;
  email?: string;
  logoUrl?: string;
  rodape?: string;
  footerText?: string;
};

const nomesStatus: Record<string, string> = {
  RECEBIDO: "RECEBIDO",
  EM_ANALISE: "EM ANÁLISE",
  AGUARDANDO_PECA: "AGUARDANDO PEÇA",
  EM_REPARO: "EM REPARO",
  PRONTO: "PRONTO",
  ENTREGUE: "ENTREGUE",
  CANCELADO: "CANCELADO",
};

const nomesEquipamento: Record<string, string> = {
  NOTEBOOK: "Notebook",
  COMPUTADOR: "Computador",
  CELULAR: "Celular",
  TABLET: "Tablet",
  VIDEOGAME: "Videogame",
  IMPRESSORA: "Impressora",
  TV: "TV",
  OUTRO: "Outro",
};

function formatarMoeda(valor: unknown) {
  const numero = Number(valor ?? 0);
  const seguro = Number.isFinite(numero) ? numero : 0;

  return seguro.toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL",
  });
}

function formatarData(data: unknown) {
  if (!data) return "-";

  const d = new Date(String(data));

  if (Number.isNaN(d.getTime())) return "-";

  return d.toLocaleDateString("pt-BR");
}

function criarDataLocalSegura(data: string) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(data);

  if (!match) return null;

  const ano = Number(match[1]);
  const mes = Number(match[2]);
  const dia = Number(match[3]);
  const d = new Date(ano, mes - 1, dia);

  if (
    d.getFullYear() !== ano ||
    d.getMonth() !== mes - 1 ||
    d.getDate() !== dia
  ) {
    return null;
  }

  return d;
}

function caminhoLogoSeguro(logoUrl?: string) {
  const uploadsDir = path.resolve(caminhoUploadPublico());
  const logoLimpa = String(logoUrl || "/uploads/logo.png").split("?")[0];

  if (!logoLimpa.startsWith("/uploads/")) {
    return null;
  }

  const relativo = logoLimpa.replace(/^\/+uploads[\\/]+/, "");
  const caminhoResolvido = path.resolve(uploadsDir, relativo);
  const dentro =
    caminhoResolvido === uploadsDir ||
    caminhoResolvido.startsWith(uploadsDir + path.sep);

  return dentro ? caminhoResolvido : null;
}

function texto(valor: unknown) {
  if (valor === null || valor === undefined || valor === "") return "-";
  return String(valor);
}

function cortar(textoOriginal: unknown, tamanho: number) {
  const valor = texto(textoOriginal);

  if (valor.length <= tamanho) return valor;

  return `${valor.slice(0, tamanho - 3)}...`;
}

function numeroOS(ordem: any) {
  const valor =
    ordem?.osNumber ??
    ordem?.numeroOS ??
    ordem?.numero ??
    ordem?.orderNumber ??
    "";

  if (!valor) return "-";

  return String(valor).padStart(3, "0");
}

function nomeCliente(ordem: any) {
  return (
    ordem?.customer?.name ||
    ordem?.cliente?.name ||
    ordem?.cliente?.nome ||
    ordem?.customerName ||
    ordem?.clienteNome ||
    ordem?.nomeCliente ||
    "-"
  );
}

function nomeEquipamento(ordem: any) {
  if (ordem?.nomeEquipamento) {
    return ordem.nomeEquipamento;
  }

  if (ordem?.equipmentType === "OUTRO") {
    return ordem?.equipmentOther || "Outro";
  }

  if (ordem?.equipmentType) {
    return nomesEquipamento[ordem.equipmentType] || ordem.equipmentType;
  }

  return (
    ordem?.equipamento ||
    ordem?.tipoEquipamento ||
    ordem?.aparelho ||
    "-"
  );
}

function valorOrdem(ordem: any) {
  return (
    ordem?.totalAmount ??
    ordem?.valorTotal ??
    ordem?.total ??
    ordem?.valorServico ??
    ordem?.valorRecebido ??
    0
  );
}

function totalItem(item: any) {
  const valor =
    item?.total ??
    item?.quantidade ??
    item?.count ??
    item?.totalOrdens ??
    item?._count?.equipmentType ??
    item?._count?.customerId ??
    item?._count?.id ??
    item?._count?._all ??
    0;

  const numero = Number(valor);
  return Number.isFinite(numero) ? numero : 0;
}

async function gerarBufferPDF(
  relatorio: any,
  empresa: EmpresaConfig,
  periodoInicio: string,
  periodoFim: string
): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    try {
      const doc = new PDFDocument({
        size: "A4",
        margin: 35,
        bufferPages: true,
      });

      const chunks: Buffer[] = [];

      doc.on("data", (chunk) => chunks.push(chunk));
      doc.on("end", () => resolve(Buffer.concat(chunks)));
      doc.on("error", reject);

      const pageWidth = doc.page.width;
      const margin = 35;
      const contentWidth = pageWidth - margin * 2;

      function linha(y?: number) {
        const posY = y ?? doc.y;

        doc
          .moveTo(margin, posY)
          .lineTo(pageWidth - margin, posY)
          .strokeColor("#cccccc")
          .lineWidth(0.5)
          .stroke();
      }

      function verificarEspaco(altura = 60) {
        if (doc.y + altura > doc.page.height - 55) {
          doc.addPage();
        }
      }

      function tituloSecao(titulo: string) {
        verificarEspaco(35);

        doc.moveDown(0.5);

        doc
          .fontSize(12)
          .fillColor("#111111")
          .font("Helvetica-Bold")
          .text(titulo, margin, doc.y);

        doc.moveDown(0.3);
        linha();
        doc.moveDown(0.6);
      }

      function cardResumo(titulo: string, valor: string, x: number, y: number, w: number) {
        doc
          .roundedRect(x, y, w, 48, 6)
          .strokeColor("#dddddd")
          .lineWidth(0.8)
          .stroke();

        doc
          .fontSize(8)
          .fillColor("#666666")
          .font("Helvetica")
          .text(titulo, x + 8, y + 8, {
            width: w - 16,
          });

        doc
          .fontSize(12)
          .fillColor("#111111")
          .font("Helvetica-Bold")
          .text(valor, x + 8, y + 25, {
            width: w - 16,
          });
      }

      const logoPath = caminhoLogoSeguro(empresa?.logoUrl);

      if (logoPath && fs.existsSync(logoPath)) {
        try {
          doc.image(logoPath, margin, 25, {
            fit: [80, 45],
          });
        } catch {
          // ignora logo inválida
        }
      }

      const nomeEmpresa =
        empresa?.nomeFantasia ||
        empresa?.nomeEmpresa ||
        empresa?.companyName ||
        "Relatório";

      const documento = empresa?.documento || empresa?.cnpj || "";
      const telefone = empresa?.telefone || empresa?.phone || "";
      const endereco = empresa?.endereco || empresa?.address || "";

      doc
        .fontSize(15)
        .fillColor("#111111")
        .font("Helvetica-Bold")
        .text(nomeEmpresa, 130, 28, {
          width: pageWidth - 165,
          align: "right",
        });

      doc
        .fontSize(8)
        .fillColor("#555555")
        .font("Helvetica")
        .text(
          [
            documento ? `CPF/CNPJ: ${documento}` : "",
            telefone ? `Tel: ${telefone}` : "",
            empresa?.whatsapp ? `WhatsApp: ${empresa.whatsapp}` : "",
            empresa?.email ? `E-mail: ${empresa.email}` : "",
          ]
            .filter(Boolean)
            .join("  |  "),
          130,
          48,
          {
            width: pageWidth - 165,
            align: "right",
          }
        );

      doc
        .fontSize(8)
        .fillColor("#555555")
        .text(endereco || "", 130, 62, {
          width: pageWidth - 165,
          align: "right",
        });

      doc.y = 95;
      linha();

      doc.moveDown(1);

      doc
        .fontSize(16)
        .fillColor("#111111")
        .font("Helvetica-Bold")
        .text("Relatório de Ordens de Serviço", margin, doc.y, {
          width: contentWidth,
          align: "center",
        });

      doc.moveDown(0.4);

      doc
        .fontSize(9)
        .fillColor("#555555")
        .font("Helvetica")
        .text(`Período: ${formatarData(periodoInicio)} até ${formatarData(periodoFim)}`, {
          width: contentWidth,
          align: "center",
        });

      doc.moveDown(1);

      tituloSecao("Resumo operacional");

      const resumo = relatorio?.resumo || {};

      const totalOS = resumo.totalOS ?? resumo.totalOrdens ?? 0;
      const abertas = resumo.osAbertas ?? resumo.ordensAbertas ?? resumo.abertas ?? 0;
      const entregues =
        resumo.osEntregues ??
        resumo.ordensEntregues ??
        resumo.entregues ??
        resumo.osConcluidas ??
        0;
      const canceladas =
        resumo.osCanceladas ?? resumo.ordensCanceladas ?? resumo.canceladas ?? 0;
      const valorRecebido = resumo.valorRecebido ?? resumo.totalRecebido ?? 0;
      const valorGerado = resumo.valorGerado ?? 0;
      const valorPendente = resumo.valorPendente ?? 0;
      const valorCobradoPecas = resumo.valorCobradoPecas ?? 0;
      const faturamentoBruto = resumo.faturamentoBruto ?? valorGerado;
      const receitaLiquida = resumo.receitaLiquida ?? valorGerado;
      const descontoTotal = resumo.descontoTotal ?? 0;
      const financeiroSensivelLiberado =
        relatorio?.financeiroSensivelLiberado === true;
      const custoPecas = resumo.custoPecas ?? 0;
      const lucroBruto = resumo.lucroBruto;
      const lucroBrutoParcial = resumo.lucroBrutoParcial ?? 0;
      const ordensSemCustoRastreado = resumo.ordensSemCustoRastreado ?? 0;

      const cardW = (contentWidth - 20) / 3;
      const startY = doc.y;

      cardResumo("Total de OS", String(totalOS), margin, startY, cardW);
      cardResumo("OS abertas", String(abertas), margin + cardW + 10, startY, cardW);
      cardResumo("OS entregues", String(entregues), margin + (cardW + 10) * 2, startY, cardW);

      const startY2 = startY + 58;

      cardResumo("OS canceladas", String(canceladas), margin, startY2, cardW);
      cardResumo("Valor recebido", formatarMoeda(valorRecebido), margin + cardW + 10, startY2, cardW);
      cardResumo("Valor gerado", formatarMoeda(valorGerado), margin + (cardW + 10) * 2, startY2, cardW);

      const startY3 = startY2 + 58;

      cardResumo("Faturamento bruto", formatarMoeda(faturamentoBruto), margin, startY3, cardW);
      cardResumo("Descontos", formatarMoeda(descontoTotal), margin + cardW + 10, startY3, cardW);
      cardResumo("Receita líquida", formatarMoeda(receitaLiquida), margin + (cardW + 10) * 2, startY3, cardW);

      let resumoFinalY = startY3 + 62;

      if (financeiroSensivelLiberado) {
        const startY4 = startY3 + 58;
        const lucroExibido =
          lucroBruto === null || lucroBruto === undefined
            ? lucroBrutoParcial
            : lucroBruto;

        cardResumo("Custo das peças", formatarMoeda(custoPecas), margin, startY4, cardW);
        cardResumo("Lucro bruto", formatarMoeda(lucroExibido), margin + cardW + 10, startY4, cardW);
        cardResumo("OS sem custo rastreado", String(ordensSemCustoRastreado), margin + (cardW + 10) * 2, startY4, cardW);

        resumoFinalY = startY4 + 62;
      }

      doc.y = resumoFinalY;

      doc
        .fontSize(9)
        .fillColor("#555555")
        .font("Helvetica")
        .text(
          `Valor pendente: ${formatarMoeda(valorPendente)}  |  Valor cobrado em peças: ${formatarMoeda(valorCobradoPecas)}`,
          margin,
          doc.y
        );

      if (financeiroSensivelLiberado && ordensSemCustoRastreado > 0) {
        doc.moveDown(0.35);
        doc
          .fontSize(8)
          .fillColor("#8a4b08")
          .text(
            `Atenção: ${ordensSemCustoRastreado} OS possui valor de peça antigo/manual sem custo histórico rastreado. O lucro exibido é parcial.`,
            margin,
            doc.y,
            { width: contentWidth }
          );
      }

      const equipamentos =
        relatorio?.equipamentosMaisConsertados ||
        relatorio?.equipamentos ||
        [];

      if (Array.isArray(equipamentos) && equipamentos.length > 0) {
        tituloSecao("Equipamentos mais consertados");

        equipamentos.slice(0, 10).forEach((item: any, index: number) => {
          verificarEspaco(18);

          const nome =
            item?.nome ||
            item?.name ||
            item?.equipamento ||
            item?.tipo ||
            (item?.equipmentType
              ? nomesEquipamento[item.equipmentType] || item.equipmentType
              : "-");

          doc
            .fontSize(9)
            .fillColor("#111111")
            .font("Helvetica")
            .text(`${index + 1}. ${nome} - ${totalItem(item)} OS`, margin, doc.y);

          doc.moveDown(0.25);
        });
      }

      const clientes =
        relatorio?.clientesMaisAtivos ||
        relatorio?.clientesAtivos ||
        relatorio?.clientes ||
        [];

      if (Array.isArray(clientes) && clientes.length > 0) {
        tituloSecao("Clientes mais ativos");

        clientes.slice(0, 10).forEach((item: any, index: number) => {
          verificarEspaco(18);

          const nome =
            item?.name ||
            item?.nome ||
            item?.clienteNome ||
            item?.cliente?.name ||
            item?.cliente?.nome ||
            "Cliente não encontrado";

          doc
            .fontSize(9)
            .fillColor("#111111")
            .font("Helvetica")
            .text(`${index + 1}. ${nome} - ${totalItem(item)} OS`, margin, doc.y);

          doc.moveDown(0.25);
        });
      }

      const ordens =
        relatorio?.ordens ||
        relatorio?.listaOrdens ||
        relatorio?.ordensPeriodo ||
        [];

      if (Array.isArray(ordens) && ordens.length > 0) {
        tituloSecao("Ordens do período");

        const tableX = margin;
        const colunas = financeiroSensivelLiberado
          ? [
              { key: "numero", label: "OS", width: 40, align: "left" as const },
              { key: "data", label: "Data", width: 48, align: "left" as const },
              { key: "cliente", label: "Cliente", width: 95, align: "left" as const },
              { key: "equipamento", label: "Equip.", width: 70, align: "left" as const },
              { key: "status", label: "Status", width: 55, align: "left" as const },
              { key: "bruto", label: "Bruto", width: 72, align: "right" as const },
              { key: "custo", label: "Custo", width: 72, align: "right" as const },
              { key: "lucro", label: "Lucro", width: 73, align: "right" as const },
            ]
          : [
              { key: "numero", label: "OS", width: 45, align: "left" as const },
              { key: "data", label: "Data", width: 55, align: "left" as const },
              { key: "cliente", label: "Cliente", width: 125, align: "left" as const },
              { key: "equipamento", label: "Equipamento", width: 105, align: "left" as const },
              { key: "status", label: "Status", width: 80, align: "left" as const },
              { key: "valor", label: "Total", width: 115, align: "right" as const },
            ];

        function escreverCelulas(
          valores: Record<string, string>,
          y: number,
          bold = false
        ) {
          let x = tableX;

          for (const coluna of colunas) {
            doc
              .fontSize(financeiroSensivelLiberado ? 7 : 8)
              .fillColor("#222222")
              .font(bold ? "Helvetica-Bold" : "Helvetica")
              .text(valores[coluna.key] || "-", x + 3, y, {
                width: coluna.width - 6,
                align: coluna.align,
                lineBreak: false,
              });

            x += coluna.width;
          }
        }

        function cabecalhoTabela() {
          verificarEspaco(28);

          const y = doc.y;
          doc.rect(tableX, y, contentWidth, 20).fillColor("#eeeeee").fill();

          escreverCelulas(
            Object.fromEntries(colunas.map((coluna) => [coluna.key, coluna.label])),
            y + 6,
            true
          );

          doc.y = y + 25;
        }

        cabecalhoTabela();

        ordens.forEach((ordem: any) => {
          verificarEspaco(24);

          const y = doc.y;
          const status = nomesStatus[ordem?.status] || ordem?.status || "-";
          const custoRastreado = ordem?.costTracked !== false;
          const lucroDisponivel =
            custoRastreado &&
            ordem?.grossProfit !== null &&
            ordem?.grossProfit !== undefined;

          escreverCelulas(
            financeiroSensivelLiberado
              ? {
                  numero: cortar(`Nº ${numeroOS(ordem)}`, 9),
                  data: formatarData(ordem?.openedAt || ordem?.createdAt || ordem?.dataEntrada),
                  cliente: cortar(nomeCliente(ordem), 18),
                  equipamento: cortar(nomeEquipamento(ordem), 12),
                  status: cortar(status, 10),
                  bruto: formatarMoeda(ordem?.grossAmount ?? valorOrdem(ordem)),
                  custo: custoRastreado
                    ? formatarMoeda(ordem?.technicalPartsCost ?? 0)
                    : "N/I",
                  lucro: lucroDisponivel
                    ? formatarMoeda(ordem?.grossProfit)
                    : "N/I",
                }
              : {
                  numero: cortar(`Nº ${numeroOS(ordem)}`, 12),
                  data: formatarData(ordem?.openedAt || ordem?.createdAt || ordem?.dataEntrada),
                  cliente: cortar(nomeCliente(ordem), 24),
                  equipamento: cortar(nomeEquipamento(ordem), 20),
                  status: cortar(status, 14),
                  valor: formatarMoeda(valorOrdem(ordem)),
                },
            y
          );

          doc.y = y + 18;
          doc
            .moveTo(tableX, doc.y)
            .lineTo(tableX + contentWidth, doc.y)
            .strokeColor("#eeeeee")
            .lineWidth(0.4)
            .stroke();

          doc.y += 5;
        });
      }

      const range = doc.bufferedPageRange();

      for (let i = range.start; i < range.start + range.count; i++) {
        doc.switchToPage(i);

        const footerY = doc.page.height - 35;

        doc
          .fontSize(7)
          .fillColor("#777777")
          .font("Helvetica")
          .text(
            empresa?.rodape ||
              empresa?.footerText ||
              "Relatório gerado pelo sistema de Ordem de Serviço.",
            margin,
            footerY - 10,
            {
              width: contentWidth,
              align: "center",
            }
          );

        doc
          .fontSize(7)
          .fillColor("#777777")
          .text(`Página ${i + 1} de ${range.count}`, margin, footerY + 2, {
            width: contentWidth,
            align: "center",
          });
      }

      doc.end();
    } catch (error) {
      reject(error);
    }
  });
}


async function gerarBufferPDFTecnicos(
  relatorio: any,
  empresa: EmpresaConfig,
  periodoInicio: string,
  periodoFim: string,
  tecnicoFiltro: string
): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    try {
      const doc = new PDFDocument({
        size: "A4",
        margin: 35,
        bufferPages: true,
      });
      const chunks: Buffer[] = [];

      doc.on("data", (chunk) => chunks.push(chunk));
      doc.on("end", () => resolve(Buffer.concat(chunks)));
      doc.on("error", reject);

      const margin = 35;
      const contentWidth = doc.page.width - margin * 2;
      const todos = tecnicoFiltro === "TODOS";
      const tecnicosBase = Array.isArray(relatorio?.tecnicosFinanceiros)
        ? relatorio.tecnicosFinanceiros
        : [];
      const tecnicos = todos
        ? tecnicosBase
        : tecnicosBase.filter(
            (item: any) => item?.technicianKey === tecnicoFiltro
          );
      const ordensBase = Array.isArray(relatorio?.ordens)
        ? relatorio.ordens
        : [];
      const ordens = ordensBase.filter(
        (ordem: any) =>
          Boolean(ordem?.technicianReportKey) &&
          (todos || ordem?.technicianReportKey === tecnicoFiltro)
      );

      const resumo = tecnicos.reduce(
        (acc: any, item: any) => ({
          totalOrders: acc.totalOrders + Number(item?.totalOrders || 0),
          grossProfitGenerated:
            acc.grossProfitGenerated +
            Number(item?.grossProfitGenerated || 0),
          technicianProfitShare:
            acc.technicianProfitShare +
            Number(item?.technicianProfitShare || 0),
          storeProfit: acc.storeProfit + Number(item?.storeProfit || 0),
          untrackedOrders:
            acc.untrackedOrders + Number(item?.untrackedOrders || 0),
        }),
        {
          totalOrders: 0,
          grossProfitGenerated: 0,
          technicianProfitShare: 0,
          storeProfit: 0,
          untrackedOrders: 0,
        }
      );

      const verificarEspaco = (altura = 45) => {
        if (doc.y + altura > doc.page.height - 55) doc.addPage();
      };

      const tituloSecao = (titulo: string) => {
        verificarEspaco(35);
        doc.moveDown(0.6);
        doc
          .font("Helvetica-Bold")
          .fontSize(12)
          .fillColor("#111111")
          .text(titulo, margin, doc.y);
        doc.moveDown(0.25);
        doc
          .moveTo(margin, doc.y)
          .lineTo(doc.page.width - margin, doc.y)
          .strokeColor("#dddddd")
          .lineWidth(0.5)
          .stroke();
        doc.moveDown(0.5);
      };

      const card = (
        titulo: string,
        valor: string,
        x: number,
        y: number,
        width: number
      ) => {
        doc
          .roundedRect(x, y, width, 48, 6)
          .strokeColor("#dddddd")
          .lineWidth(0.8)
          .stroke();
        doc
          .font("Helvetica")
          .fontSize(8)
          .fillColor("#666666")
          .text(titulo, x + 8, y + 8, { width: width - 16 });
        doc
          .font("Helvetica-Bold")
          .fontSize(11)
          .fillColor("#111111")
          .text(valor, x + 8, y + 25, { width: width - 16 });
      };

      const logoPath = caminhoLogoSeguro(empresa?.logoUrl);
      if (logoPath && fs.existsSync(logoPath)) {
        try {
          doc.image(logoPath, margin, 25, { fit: [80, 45] });
        } catch {
          // Logo inválida não impede o relatório.
        }
      }

      const nomeEmpresa =
        empresa?.nomeFantasia ||
        empresa?.nomeEmpresa ||
        empresa?.companyName ||
        "Relatório";

      doc
        .font("Helvetica-Bold")
        .fontSize(15)
        .fillColor("#111111")
        .text(nomeEmpresa, 130, 28, {
          width: doc.page.width - 165,
          align: "right",
        });

      doc.y = 95;
      doc
        .moveTo(margin, doc.y)
        .lineTo(doc.page.width - margin, doc.y)
        .strokeColor("#cccccc")
        .lineWidth(0.5)
        .stroke();

      doc.moveDown(1);
      doc
        .font("Helvetica-Bold")
        .fontSize(16)
        .fillColor("#111111")
        .text("Relatório de Lucro por Técnico", margin, doc.y, {
          width: contentWidth,
          align: "center",
        });

      doc.moveDown(0.35);
      doc
        .font("Helvetica")
        .fontSize(9)
        .fillColor("#555555")
        .text(
          `Período: ${formatarData(periodoInicio)} até ${formatarData(
            periodoFim
          )}`,
          { width: contentWidth, align: "center" }
        );

      doc.moveDown(0.15);
      doc
        .font("Helvetica-Bold")
        .fontSize(9)
        .fillColor("#333333")
        .text(
          todos
            ? "Técnico: Todos os técnicos"
            : `Técnico: ${tecnicos[0]?.technicianName || "Não encontrado"}`,
          { width: contentWidth, align: "center" }
        );

      tituloSecao("Resumo");

      const cardW = (contentWidth - 30) / 4;
      const yResumo = doc.y;

      card("OS", String(resumo.totalOrders), margin, yResumo, cardW);
      card(
        "Lucro gerado",
        formatarMoeda(resumo.grossProfitGenerated),
        margin + cardW + 10,
        yResumo,
        cardW
      );
      card(
        "Participação",
        formatarMoeda(resumo.technicianProfitShare),
        margin + (cardW + 10) * 2,
        yResumo,
        cardW
      );
      card(
        "Lucro loja",
        formatarMoeda(resumo.storeProfit),
        margin + (cardW + 10) * 3,
        yResumo,
        cardW
      );

      doc.y = yResumo + 62;

      if (resumo.untrackedOrders > 0) {
        doc
          .font("Helvetica")
          .fontSize(8)
          .fillColor("#8a4b08")
          .text(
            `${resumo.untrackedOrders} OS sem base suficiente para calcular a divisão financeira.`,
            margin,
            doc.y,
            { width: contentWidth }
          );
      }

      if (todos && tecnicos.length > 0) {
        tituloSecao("Resumo por técnico");

        tecnicos.forEach((tecnico: any, index: number) => {
          verificarEspaco(30);

          doc
            .font("Helvetica-Bold")
            .fontSize(9)
            .fillColor("#111111")
            .text(
              `${index + 1}. ${tecnico?.technicianName || "Técnico"}`,
              margin,
              doc.y
            );

          doc.moveDown(0.1);

          doc
            .font("Helvetica")
            .fontSize(8)
            .fillColor("#555555")
            .text(
              `${Number(tecnico?.totalOrders || 0)} OS | Lucro: ${formatarMoeda(
                tecnico?.grossProfitGenerated
              )} | Participação: ${formatarMoeda(
                tecnico?.technicianProfitShare
              )} | Loja: ${formatarMoeda(tecnico?.storeProfit)}`,
              margin,
              doc.y,
              { width: contentWidth }
            );

          doc.moveDown(0.35);
        });
      }

      tituloSecao("Ordens de serviço");

      if (ordens.length === 0) {
        doc
          .font("Helvetica")
          .fontSize(9)
          .fillColor("#555555")
          .text("Nenhuma OS encontrada para esta seleção.", margin, doc.y);
      } else {
        ordens.forEach((ordem: any) => {
          verificarEspaco(42);

          const rastreada =
            ordem?.profitShareTracked !== false &&
            ordem?.grossProfit !== null &&
            ordem?.grossProfit !== undefined;
          const percentual = rastreada
            ? `${Number(ordem?.technicianProfitPercent || 0).toLocaleString(
                "pt-BR",
                { maximumFractionDigits: 2 }
              )}%`
            : "N/I";

          doc
            .font("Helvetica-Bold")
            .fontSize(9)
            .fillColor("#111111")
            .text(
              `OS Nº ${numeroOS(ordem)} - ${
                ordem?.technicianResponsible || "Técnico não rastreado"
              }`,
              margin,
              doc.y,
              { width: contentWidth }
            );

          doc.moveDown(0.12);

          doc
            .font("Helvetica")
            .fontSize(8)
            .fillColor("#555555")
            .text(
              `Lucro: ${
                rastreada ? formatarMoeda(ordem?.grossProfit) : "N/I"
              } | %: ${percentual} | Participação: ${
                rastreada
                  ? formatarMoeda(ordem?.technicianProfitShare)
                  : "N/I"
              } | Loja: ${
                rastreada ? formatarMoeda(ordem?.storeProfit) : "N/I"
              }`,
              margin,
              doc.y,
              { width: contentWidth }
            );

          doc.moveDown(0.25);
          doc
            .moveTo(margin, doc.y)
            .lineTo(doc.page.width - margin, doc.y)
            .strokeColor("#eeeeee")
            .lineWidth(0.4)
            .stroke();
          doc.moveDown(0.35);
        });
      }

      const range = doc.bufferedPageRange();

      for (let i = range.start; i < range.start + range.count; i++) {
        doc.switchToPage(i);
        doc
          .font("Helvetica")
          .fontSize(7)
          .fillColor("#777777")
          .text(
            `Página ${i + 1} de ${range.count}`,
            margin,
            doc.page.height - 33,
            { width: contentWidth, align: "center" }
          );
      }

      doc.end();
    } catch (error) {
      reject(error);
    }
  });
}

export async function GET(request: NextRequest) {
  try {
    const { searchParams, origin } = new URL(request.url);
    const modo = searchParams.get("modo") === "tecnicos" ? "tecnicos" : "geral";
    const tecnicoFiltro = String(searchParams.get("tecnico") || "TODOS").slice(
      0,
      180
    );

    const acesso = await exigirPermissaoApi(
      modo === "tecnicos"
        ? "relatorios.financeiro"
        : ["relatorios.ver", "relatorios.financeiro"]
    );

    if (!acesso.ok) {
      return acesso.response;
    }

    if (
      modo === "tecnicos" &&
      !usuarioPodeVerDadosFinanceirosSensiveis(acesso.usuario)
    ) {
      return Response.json(
        { error: "Você não tem permissão para gerar este relatório." },
        { status: 403 }
      );
    }

    const inicio = searchParams.get("inicio") || "";
    const fim = searchParams.get("fim") || "";

    if (!inicio || !fim) {
      return Response.json(
        {
          error: "Informe o período inicial e final.",
        },
        {
          status: 400,
        }
      );
    }

    const inicioValido = criarDataLocalSegura(inicio);
    const fimValido = criarDataLocalSegura(fim);

    if (!inicioValido || !fimValido) {
      return Response.json(
        {
          error: "Período inválido para gerar PDF.",
        },
        {
          status: 400,
        }
      );
    }

    if (fimValido < inicioValido) {
      return Response.json(
        {
          error: "A data final não pode ser menor que a data inicial.",
        },
        {
          status: 400,
        }
      );
    }

    const urlRelatorio = new URL("/api/relatorios", origin);
    urlRelatorio.searchParams.set("dataInicial", inicio);
    urlRelatorio.searchParams.set("dataFinal", fim);

    const cookieHeader = request.headers.get("cookie") || "";

const relatorioResponse = await fetch(urlRelatorio.toString(), {
  cache: "no-store",
  headers: {
    cookie: cookieHeader,
  },
});

    if (!relatorioResponse.ok) {
  const erro = await relatorioResponse.json().catch(() => null);

  return Response.json(
    {
      error:
        erro?.message ||
        erro?.error ||
        "Não foi possível carregar os dados do relatório.",
    },
    {
      status: relatorioResponse.status,
    }
  );
}

    const relatorio = await relatorioResponse.json();

    const urlConfiguracoes = new URL("/api/configuracoes", origin);

    const configuracoesResponse = await fetch(urlConfiguracoes.toString(), {
  cache: "no-store",
  headers: {
    cookie: cookieHeader,
  },
});

    let empresa: EmpresaConfig = {};

    if (configuracoesResponse.ok) {
      empresa = await configuracoesResponse.json();
    }

    if (modo === "tecnicos" && tecnicoFiltro !== "TODOS") {
      const existe = Array.isArray(relatorio?.tecnicosFinanceiros)
        ? relatorio.tecnicosFinanceiros.some(
            (item: any) => item?.technicianKey === tecnicoFiltro
          )
        : false;

      if (!existe) {
        return Response.json(
          { error: "Técnico não encontrado no período informado." },
          { status: 404 }
        );
      }
    }

    const buffer =
      modo === "tecnicos"
        ? await gerarBufferPDFTecnicos(
            relatorio,
            empresa,
            inicio,
            fim,
            tecnicoFiltro
          )
        : await gerarBufferPDF(relatorio, empresa, inicio, fim);

    return new Response(buffer as unknown as BodyInit, {
  status: 200,
  headers: {
    "Content-Type": "application/pdf",
    "Content-Disposition":
      modo === "tecnicos"
        ? `inline; filename="relatorio-tecnicos-${inicio}-a-${fim}.pdf"`
        : `inline; filename="relatorio-${inicio}-a-${fim}.pdf"`,
    "Cache-Control": "no-store",
  },
});
  } catch (error) {
    console.error("Erro ao gerar PDF do relatório:", error);

    return Response.json(
      {
        error: "Erro ao gerar PDF do relatório.",
      },
      {
        status: 500,
      }
    );
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import {
  exigirPermissaoApi,
  usuarioPodeVerDadosFinanceirosSensiveis,
} from "@/lib/permissaoApi";
import {
  labelsDiasFuncionamento,
  lojaAbertaNaData,
  normalizarDiasFuncionamento,
  normalizarHora,
} from "@/lib/funcionamentoLoja";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const DIAS_SEMANA = [
  "Domingo",
  "Segunda-feira",
  "Terça-feira",
  "Quarta-feira",
  "Quinta-feira",
  "Sexta-feira",
  "Sábado",
];

const nomesEquipamento: Record<string, string> = {
  NOTEBOOK: "Notebook",
  COMPUTADOR: "Computador",
  CELULAR: "Celular",
  TABLET: "Tablet",
  VIDEOGAME: "Videogame",
  IMPRESSORA: "Impressora",
  TV: "TV",
  OUTRO: "Outro",
};

function criarDataLocalSegura(data: string | null) {
  if (!data) return null;

  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(data);

  if (!match) return null;

  const ano = Number(match[1]);
  const mes = Number(match[2]);
  const dia = Number(match[3]);

  const d = new Date(ano, mes - 1, dia);

  if (
    d.getFullYear() !== ano ||
    d.getMonth() !== mes - 1 ||
    d.getDate() !== dia
  ) {
    return null;
  }

  return d;
}

function inicioDoDia(data: Date) {
  const d = new Date(data);
  d.setHours(0, 0, 0, 0);
  return d;
}

function fimDoDia(data: Date) {
  const d = new Date(data);
  d.setHours(23, 59, 59, 999);
  return d;
}

function numero(valor: unknown) {
  const n = Number(valor ?? 0);
  return Number.isFinite(n) ? n : 0;
}

function moeda(valor: number) {
  return Math.round((valor + Number.EPSILON) * 100) / 100;
}

function percentual(valor: unknown) {
  return Math.min(Math.max(numero(valor), 0), 100);
}

function formatarDataInput(data: Date) {
  const ano = data.getFullYear();
  const mes = String(data.getMonth() + 1).padStart(2, "0");
  const dia = String(data.getDate()).padStart(2, "0");

  return `${ano}-${mes}-${dia}`;
}

function criarDiasDoPeriodo(inicio: Date, fim: Date, diasFuncionamento: number[]) {
  const dias: {
    data: string;
    label: string;
    totalOrdens: number;
    ordensAbertas: number;
    ordensEntregues: number;
    ordensCanceladas: number;
    totalAmount: number;
  }[] = [];

  const atual = new Date(
    inicio.getFullYear(),
    inicio.getMonth(),
    inicio.getDate(),
    0,
    0,
    0,
    0
  );

  const limite = new Date(
    fim.getFullYear(),
    fim.getMonth(),
    fim.getDate(),
    0,
    0,
    0,
    0
  );

  while (atual <= limite) {
    if (lojaAbertaNaData(atual, diasFuncionamento)) {
      dias.push({
        data: formatarDataInput(atual),
        label: atual.toLocaleDateString("pt-BR"),
        totalOrdens: 0,
        ordensAbertas: 0,
        ordensEntregues: 0,
        ordensCanceladas: 0,
        totalAmount: 0,
      });
    }

    atual.setDate(atual.getDate() + 1);
  }

  return dias;
}

async function buscarFuncionamentoLoja() {
  const configuracoes = await prisma.companySettings.findFirst({
    select: {
      businessDays: true,
      businessOpenTime: true,
      businessCloseTime: true,
    },
  });

  const diasAbertos = normalizarDiasFuncionamento(
    configuracoes?.businessDays
  );

  return {
    diasAbertos,
    labels: labelsDiasFuncionamento(diasAbertos),
    abertura: normalizarHora(configuracoes?.businessOpenTime, "08:00"),
    fechamento: normalizarHora(configuracoes?.businessCloseTime, "18:00"),
  };
}

function nomeEquipamento(ordem: {
  equipmentType?: string | null;
  equipmentOther?: string | null;
}) {
  if (ordem.equipmentType === "OUTRO") {
    return ordem.equipmentOther?.trim() || "Outro";
  }

  return nomesEquipamento[ordem.equipmentType || ""] || ordem.equipmentType || "-";
}

export async function GET(request: Request) {
  try {
    const acesso = await exigirPermissaoApi([
      "relatorios.ver",
      "relatorios.financeiro",
    ]);

    if (!acesso.ok) {
      return acesso.response;
    }

    const financeiroSensivelLiberado =
      usuarioPodeVerDadosFinanceirosSensiveis(acesso.usuario);

    const { searchParams } = new URL(request.url);

    const dataInicialParam =
      searchParams.get("dataInicial") || searchParams.get("inicio");

    const dataFinalParam =
      searchParams.get("dataFinal") || searchParams.get("fim");

    const inicioInformado = criarDataLocalSegura(dataInicialParam);
    const fimInformado = criarDataLocalSegura(dataFinalParam);

    if (dataInicialParam && !inicioInformado) {
      return NextResponse.json(
        { message: "Data inicial inválida." },
        { status: 400 }
      );
    }

    if (dataFinalParam && !fimInformado) {
      return NextResponse.json(
        { message: "Data final inválida." },
        { status: 400 }
      );
    }

    const hoje = new Date();

    const dataInicial = inicioInformado
      ? inicioDoDia(inicioInformado)
      : new Date(hoje.getFullYear(), hoje.getMonth(), 1, 0, 0, 0, 0);

    const dataFinal = fimInformado
      ? fimDoDia(fimInformado)
      : new Date(hoje.getFullYear(), hoje.getMonth() + 1, 0, 23, 59, 59, 999);

    if (dataFinal < dataInicial) {
      return NextResponse.json(
        { message: "A data final não pode ser menor que a data inicial." },
        { status: 400 }
      );
    }

    const funcionamento = await buscarFuncionamentoLoja();

    const filtroOrdens = {
      openedAt: {
        gte: dataInicial,
        lte: dataFinal,
      },
    };

    const filtroPagamentos = {
      createdAt: {
        gte: dataInicial,
        lte: dataFinal,
      },
    };

    const [ordens, pagamentosPeriodo] = await Promise.all([
      prisma.serviceOrder.findMany({
        where: filtroOrdens,
        orderBy: {
          openedAt: "desc",
        },
        select: {
          id: true,
          osNumber: true,
          customerId: true,
          equipmentType: true,
          equipmentOther: true,
          brand: true,
          model: true,
          status: true,
          technicianUserId: true,
          technicianResponsible: true,
          technicianProfitPercentSnapshot: true,
          totalAmount: true,
          partsCost: true,
          laborCost: true,
          discount: true,
          paidAmount: true,
          openedAt: true,
          technicalParts: {
            select: {
              state: true,
              totalCostSnapshot: true,
            },
          },
          customer: {
            select: {
              id: true,
              name: true,
              whatsapp: true,
            },
          },
        },
      }),

      prisma.serviceOrderPayment.findMany({
            where: filtroPagamentos,
            select: {
              amount: true,
              paymentMethod: true,
            },
          }),
    ]);

    const totalOrdens = ordens.length;

    const ordensAbertas = ordens.filter(
      (ordem) => !["ENTREGUE", "CANCELADO"].includes(ordem.status)
    ).length;

    const ordensEntregues = ordens.filter(
      (ordem) => ordem.status === "ENTREGUE"
    ).length;

    const ordensCanceladas = ordens.filter(
      (ordem) => ordem.status === "CANCELADO"
    ).length;

    const diasSemanaTodos = DIAS_SEMANA.map((dia, index) => ({
      diaSemana: index,
      label: dia,
      lojaAberta: funcionamento.diasAbertos.includes(index),
      totalOrdens: 0,
      ordensAbertas: 0,
      ordensEntregues: 0,
      ordensCanceladas: 0,
      totalAmount: 0,
    }));

    const diasPeriodo = criarDiasDoPeriodo(
      dataInicial,
      dataFinal,
      funcionamento.diasAbertos
    );

    const diasPeriodoMap = new Map(diasPeriodo.map((dia) => [dia.data, dia]));

    for (const ordem of ordens) {
      const dataOrdem = new Date(ordem.openedAt);
      const diaSemana = dataOrdem.getDay();
      const dataKey = formatarDataInput(dataOrdem);
      const aberta = !["ENTREGUE", "CANCELADO"].includes(ordem.status);
      const entregue = ordem.status === "ENTREGUE";
      const cancelada = ordem.status === "CANCELADO";
      const total = ordem.status === "CANCELADO" ? 0 : numero(ordem.totalAmount);

      if (diasSemanaTodos[diaSemana]?.lojaAberta) {
        diasSemanaTodos[diaSemana].totalOrdens += 1;
        diasSemanaTodos[diaSemana].ordensAbertas += aberta ? 1 : 0;
        diasSemanaTodos[diaSemana].ordensEntregues += entregue ? 1 : 0;
        diasSemanaTodos[diaSemana].ordensCanceladas += cancelada ? 1 : 0;
        diasSemanaTodos[diaSemana].totalAmount += total;
      }

      const diaPeriodo = diasPeriodoMap.get(dataKey);

      if (diaPeriodo) {
        diaPeriodo.totalOrdens += 1;
        diaPeriodo.ordensAbertas += aberta ? 1 : 0;
        diaPeriodo.ordensEntregues += entregue ? 1 : 0;
        diaPeriodo.ordensCanceladas += cancelada ? 1 : 0;
        diaPeriodo.totalAmount += total;
      }
    }

    const diasSemana = diasSemanaTodos.filter((dia) => dia.lojaAberta);

    const diaSemanaMaisForte = [...diasSemana].sort(
      (a, b) => b.totalOrdens - a.totalOrdens
    )[0] || null;

    const diaSemanaMaisFraco = [...diasSemana].sort(
      (a, b) => a.totalOrdens - b.totalOrdens
    )[0] || null;

    const diasPeriodoComOrdem = diasPeriodo.filter(
      (dia) => dia.totalOrdens > 0
    );

    const diaMesMaisForte =
      [...diasPeriodoComOrdem].sort(
        (a, b) => b.totalOrdens - a.totalOrdens
      )[0] || null;

    const diaMesMaisFraco =
      [...diasPeriodo].sort((a, b) => a.totalOrdens - b.totalOrdens)[0] || null;

    const valorRecebido = pagamentosPeriodo.reduce(
      (total, pagamento) => total + Number(pagamento.amount || 0),
      0
    );

    const recebidoPorForma =
      pagamentosPeriodo.reduce<Record<string, number>>((acc, pagamento) => {
          const forma = pagamento.paymentMethod || "NAO_INFORMADO";
          acc[forma] = (acc[forma] || 0) + Number(pagamento.amount || 0);
          return acc;
        }, {});

    const ordensNaoCanceladas = ordens.filter(
      (ordem) => ordem.status !== "CANCELADO"
    );

    const financeiroPorOrdem = new Map(
      ordens.map((ordem) => {
        const cancelada = ordem.status === "CANCELADO";
        const pecasAtivas = ordem.technicalParts.filter(
          (item) => item.state === "RESERVED" || item.state === "CONSUMED"
        );
        const custoPecas = cancelada
          ? 0
          : pecasAtivas.reduce(
              (total, item) => total + numero(item.totalCostSnapshot),
              0
            );
        const valorPecas = cancelada ? 0 : numero(ordem.partsCost);
        const maoDeObra = cancelada ? 0 : numero(ordem.laborCost);
        const desconto = cancelada ? 0 : numero(ordem.discount);
        const faturamentoBruto = valorPecas + maoDeObra;
        const receitaLiquida = cancelada ? 0 : numero(ordem.totalAmount);

        const custoRastreado =
          cancelada || valorPecas <= 0 || pecasAtivas.length > 0;
        const lucroBruto = custoRastreado
          ? moeda(receitaLiquida - custoPecas)
          : null;

        const possuiSnapshotParticipacao =
          ordem.technicianProfitPercentSnapshot !== null &&
          ordem.technicianProfitPercentSnapshot !== undefined;
        const concluidaComTecnicoEsperado =
          ordem.status === "PRONTO" || ordem.status === "ENTREGUE";

        // Antes do PRONTO ainda não existe participação adquirida.
        // PRONTO/ENTREGUE antigo sem snapshot fica explicitamente não rastreado.
        const participacaoRastreada =
          cancelada || possuiSnapshotParticipacao || !concluidaComTecnicoEsperado;
        const percentualTecnico = possuiSnapshotParticipacao
          ? percentual(ordem.technicianProfitPercentSnapshot)
          : participacaoRastreada
            ? 0
            : null;

        const participacaoTecnico =
          lucroBruto === null || percentualTecnico === null
            ? null
            : moeda(Math.max(lucroBruto, 0) * (percentualTecnico / 100));
        const lucroLoja =
          lucroBruto === null || participacaoTecnico === null
            ? null
            : moeda(lucroBruto - participacaoTecnico);

        return [
          ordem.id,
          {
            faturamentoBruto,
            receitaLiquida,
            custoPecas,
            desconto,
            custoRastreado,
            lucroBruto,
            participacaoRastreada,
            percentualTecnico,
            participacaoTecnico,
            lucroLoja,
          },
        ] as const;
      })
    );

    const faturamentoBruto = ordensNaoCanceladas.reduce(
      (total, ordem) =>
        total + (financeiroPorOrdem.get(ordem.id)?.faturamentoBruto || 0),
      0
    );
    const receitaLiquida = ordensNaoCanceladas.reduce(
      (total, ordem) =>
        total + (financeiroPorOrdem.get(ordem.id)?.receitaLiquida || 0),
      0
    );
    const custoPecas = ordensNaoCanceladas.reduce(
      (total, ordem) =>
        total + (financeiroPorOrdem.get(ordem.id)?.custoPecas || 0),
      0
    );
    const ordensSemCustoRastreado = ordensNaoCanceladas.filter(
      (ordem) => financeiroPorOrdem.get(ordem.id)?.custoRastreado === false
    ).length;
    const lucroBrutoParcial = ordensNaoCanceladas.reduce((total, ordem) => {
      const lucro = financeiroPorOrdem.get(ordem.id)?.lucroBruto;
      return total + (lucro === null || lucro === undefined ? 0 : lucro);
    }, 0);
    const lucroBruto =
      ordensSemCustoRastreado === 0 ? lucroBrutoParcial : null;

    const ordensSemParticipacaoCalculavel = ordensNaoCanceladas.filter(
      (ordem) => {
        const financeiro = financeiroPorOrdem.get(ordem.id);
        return (
          financeiro?.custoRastreado === false ||
          financeiro?.participacaoRastreada === false
        );
      }
    ).length;

    const participacaoTecnicosParcial = moeda(
      ordensNaoCanceladas.reduce((total, ordem) => {
        const valor = financeiroPorOrdem.get(ordem.id)?.participacaoTecnico;
        return total + (valor === null || valor === undefined ? 0 : valor);
      }, 0)
    );

    const lucroLojaParcial = moeda(
      ordensNaoCanceladas.reduce((total, ordem) => {
        const valor = financeiroPorOrdem.get(ordem.id)?.lucroLoja;
        return total + (valor === null || valor === undefined ? 0 : valor);
      }, 0)
    );

    const participacaoTecnicos =
      ordensSemParticipacaoCalculavel === 0
        ? participacaoTecnicosParcial
        : null;
    const lucroLoja =
      ordensSemParticipacaoCalculavel === 0 ? lucroLojaParcial : null;

    const tecnicosFinanceiros = financeiroSensivelLiberado
      ? Array.from(
          ordensNaoCanceladas.reduce(
            (mapa, ordem) => {
              const nome = ordem.technicianResponsible?.trim();
              const financeiro = financeiroPorOrdem.get(ordem.id);
              const possuiSnapshot =
                ordem.technicianProfitPercentSnapshot !== null &&
                ordem.technicianProfitPercentSnapshot !== undefined;

              if (!nome || !possuiSnapshot) return mapa;

              const chave =
                ordem.technicianUserId?.trim() ||
                `nome:${nome.toLocaleLowerCase("pt-BR")}`;

              const atual = mapa.get(chave) || {
                technicianKey: chave,
                technicianName: nome,
                totalOrders: 0,
                grossProfitGenerated: 0,
                technicianProfitShare: 0,
                storeProfit: 0,
                untrackedOrders: 0,
              };

              atual.totalOrders += 1;

              if (
                financeiro?.lucroBruto === null ||
                financeiro?.lucroBruto === undefined ||
                financeiro?.participacaoTecnico === null ||
                financeiro?.participacaoTecnico === undefined ||
                financeiro?.lucroLoja === null ||
                financeiro?.lucroLoja === undefined
              ) {
                atual.untrackedOrders += 1;
              } else {
                atual.grossProfitGenerated = moeda(
                  atual.grossProfitGenerated + financeiro.lucroBruto
                );
                atual.technicianProfitShare = moeda(
                  atual.technicianProfitShare + financeiro.participacaoTecnico
                );
                atual.storeProfit = moeda(
                  atual.storeProfit + financeiro.lucroLoja
                );
              }

              mapa.set(chave, atual);
              return mapa;
            },
            new Map<
              string,
              {
                technicianKey: string;
                technicianName: string;
                totalOrders: number;
                grossProfitGenerated: number;
                technicianProfitShare: number;
                storeProfit: number;
                untrackedOrders: number;
              }
            >()
          ).values()
        ).sort(
          (a, b) =>
            b.technicianProfitShare - a.technicianProfitShare ||
            a.technicianName.localeCompare(b.technicianName, "pt-BR")
        )
      : [];

    const valorGerado = receitaLiquida;
    const valorPendente = ordensNaoCanceladas.reduce(
      (total, ordem) =>
        total + Math.max(numero(ordem.totalAmount) - numero(ordem.paidAmount), 0),
      0
    );
    const valorCobradoPecas = ordensNaoCanceladas.reduce(
      (total, ordem) => total + numero(ordem.partsCost),
      0
    );
    const valorMaoDeObra = ordensNaoCanceladas.reduce(
      (total, ordem) => total + numero(ordem.laborCost),
      0
    );
    const descontoTotal = ordensNaoCanceladas.reduce(
      (total, ordem) => total + numero(ordem.discount),
      0
    );
    const ticketMedio =
      ordensNaoCanceladas.length > 0
        ? receitaLiquida / ordensNaoCanceladas.length
        : 0;

    const equipamentosMap = new Map<string, number>();

    for (const ordem of ordens) {
      const nome = nomeEquipamento(ordem);
      equipamentosMap.set(nome, (equipamentosMap.get(nome) || 0) + 1);
    }

    const equipamentos = Array.from(equipamentosMap.entries())
      .map(([nome, total]) => ({
        nome,
        total,
        quantidade: total,
      }))
      .sort((a, b) => b.total - a.total);

    const clientesMap = new Map<
      string,
      {
        customerId: string;
        name: string;
        whatsapp: string | null;
        totalOrdens: number;
        total: number;
        quantidade: number;
      }
    >();

    for (const ordem of ordens) {
      const customerId = ordem.customerId || "sem-cliente";
      const atual = clientesMap.get(customerId);

      if (atual) {
        atual.totalOrdens += 1;
        atual.total += 1;
        atual.quantidade += 1;
        continue;
      }

      clientesMap.set(customerId, {
        customerId,
        name: ordem.customer?.name || "Cliente não encontrado",
        whatsapp: ordem.customer?.whatsapp || null,
        totalOrdens: 1,
        total: 1,
        quantidade: 1,
      });
    }

    const clientesMaisAtivos = Array.from(clientesMap.values()).sort(
      (a, b) => b.totalOrdens - a.totalOrdens
    );

    const ordensFormatadas = ordens.map((ordem) => {
      const financeiro = financeiroPorOrdem.get(ordem.id);

      return {
      id: ordem.id,
      osNumber: ordem.osNumber,
      numeroOS: ordem.osNumber,
      equipmentType: ordem.equipmentType,
      equipmentOther: ordem.equipmentOther,
      nomeEquipamento: nomeEquipamento(ordem),
      brand: ordem.brand,
      model: ordem.model,
      status: ordem.status,
      totalAmount: numero(ordem.totalAmount),
      openedAt: ordem.openedAt,
      customer: ordem.customer
        ? {
            id: ordem.customer.id,
            name: ordem.customer.name,
            whatsapp: ordem.customer.whatsapp,
          }
        : null,
      customerName: ordem.customer?.name || "-",
      customerWhatsapp: ordem.customer?.whatsapp || null,
      grossAmount: financeiro?.faturamentoBruto || 0,
      netAmount: financeiro?.receitaLiquida || 0,
      ...(financeiroSensivelLiberado
        ? {
            technicalPartsCost: financeiro?.custoPecas || 0,
            grossProfit: financeiro?.lucroBruto ?? null,
            costTracked: financeiro?.custoRastreado ?? true,
            technicianResponsible: ordem.technicianResponsible || null,
            technicianReportKey:
              ordem.technicianUserId?.trim() ||
              (ordem.technicianResponsible?.trim()
                ? `nome:${ordem.technicianResponsible
                    .trim()
                    .toLocaleLowerCase("pt-BR")}`
                : null),
            technicianProfitPercent: financeiro?.percentualTecnico ?? null,
            technicianProfitShare: financeiro?.participacaoTecnico ?? null,
            storeProfit: financeiro?.lucroLoja ?? null,
            profitShareTracked: financeiro?.participacaoRastreada ?? true,
          }
        : {}),
      };
    });

    return NextResponse.json({
      financeiroSensivelLiberado,
      financeiroLiberado: financeiroSensivelLiberado,
      funcionamento,
      periodo: {
        dataInicial: dataInicial.toISOString(),
        dataFinal: dataFinal.toISOString(),
      },
      resumo: {
        totalOrdens,
        ordensAbertas,
        ordensEntregues,
        ordensCanceladas,
        valorRecebido,
        totalRecebido: valorRecebido,
        recebidoPorForma,
        valorGerado,
        valorPendente,
        valorCobradoPecas,
        valorMaoDeObra,
        descontoTotal,
        ticketMedio,
        faturamentoBruto,
        receitaLiquida,
        custoPecas: financeiroSensivelLiberado ? custoPecas : null,
